INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c58db52-31f5-47e2-9495-bcf586364c8e', '塞下二首 一', '塞下二首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["胡虜偏狂悍，邊兵不敢閑。","防秋朝伏弩，縱火夜搜山。","鴈逆風鼙振，沙飛獵騎還。","安西雖有路，難更出陽關。"]', '["胡虜偏狂悍，邊兵不敢闲。","防秋朝伏弩，縱火夜搜山。","鴈逆风鼙振，沙飞獵騎還。","安西雖有路，难更出陽关。"]', '诗', 'shi', '', NULL, '塞下二首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fcd682-33e0-4119-8305-d97892d9dbf6', '塞下二首 二', '塞下二首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["征役已不定，又緣無定河。","塞深烽砦密，山亂犬羊多。","漢卒聞笳泣，胡兒擊劒歌。","番情終未測，今昔謾言和。"]', '["征役已不定，又緣無定河。","塞深烽砦密，山亂犬羊多。","漢卒闻笳泣，胡兒擊劒歌。","番情終未測，今昔謾言和。"]', '诗', 'shi', '', NULL, '塞下二首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99f7f90c-b956-4cc2-a6a5-6a8b926a186d', '題張喬昇平里居', '題張喬昇平里居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["下馬似無人，開門只一身。","心同孤鶴靜，行過老僧真。","亂水藏幽徑，高原隔遠津。","匡廬曾共隱，相見自相親。"]', '["下马似無人，开门只一身。","心同孤鹤静，行過老僧真。","亂水藏幽徑，高原隔远津。","匡廬曾共隐，相见自相親。"]', '诗', 'shi', '', NULL, '題張喬昇平里居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571a741e-535b-49e8-baf3-16363d531471', '題鄭拾遺南齋', '題鄭拾遺南斋', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["明時無事諫，豈事隱明君。","每值離丹陛，多陪宴白雲。","門連蕭洞僻，地與曲江分。","滿院皆檉竹，期棲鸞鶴羣。"]', '["明时無事諫，豈事隐明君。","每值離丹陛，多陪宴白云。","门連蕭洞僻，地與曲江分。","满院皆檉竹，期棲鸾鹤羣。"]', '诗', 'shi', '', NULL, '題鄭拾遺南齋 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924c13fb-af38-40c9-a49a-f376d70b0b8f', '渭上送人南歸', '渭上送人南归', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["遠役與歸愁，同來渭水頭。","南浮應到海，北去阻無州。","楚雨天連地，胡風夏甚秋。","江人如見問，爲話復貧遊。"]', '["远役與归愁，同来渭水头。","南浮應到海，北去阻無州。","楚雨天連地，胡风夏甚秋。","江人如见问，爲話复貧游。"]', '诗', 'shi', '', NULL, '渭上送人南歸 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd0d2b79-12aa-4720-a028-324836ce830e', '寄睦州陸郎中', '寄睦州陸郎中', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["下國多高趣，終年半是吟。","海濤通越分，部伍雜閩音。","曉郭雲藏市，春山鳥護林。","東浮雖未遂，日日至中心。"]', '["下国多高趣，終年半是吟。","海濤通越分，部伍杂閩音。","晓郭云藏市，春山鸟護林。","东浮雖未遂，日日至中心。"]', '诗', 'shi', '', NULL, '寄睦州陸郎中 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e07dce-686b-4f6f-a62d-074d75191aab', '投徐端公', '投徐端公', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["無謀尋舊友，強喜亦如愁。","丹桂阻丹懇，白衣成白頭。","窮吳迷釣業，大漠事貧遊。","霄漢期提引，龍鍾未擬休。"]', '["無謀尋旧友，強喜亦如愁。","丹桂阻丹懇，白衣成白头。","窮吳迷釣業，大漠事貧游。","霄漢期提引，龙鍾未擬休。"]', '诗', 'shi', '', NULL, '投徐端公 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4be3e7-539c-478c-8dcf-c3aca712868c', '出塞門', '出塞门', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["步步經戎虜，防兵不離身。","山多曾戰處，路斷野行人。","暴雨聲同瀑，奔沙勢異塵。","片時懷萬慮，白髮數莖新。"]', '["步步經戎虜，防兵不離身。","山多曾戰处，路斷野行人。","暴雨声同瀑，奔沙勢異塵。","片时懷万慮，白髮數莖新。"]', '诗', 'shi', '', NULL, '出塞門 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff37d448-1e74-4674-9b78-07109a745135', '新年呈友', '新年呈友', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["一月月相似，一年年不同。","清晨窺古鏡，旅貌近衰翁。","處世閑難得，關身事半空。","浮生能幾許，莫惜醉春風。"]', '["一月月相似，一年年不同。","清晨窺古镜，旅貌近衰翁。","处世闲难得，关身事半空。","浮生能幾許，莫惜醉春风。"]', '诗', 'shi', '', NULL, '新年呈友 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2904f1-b240-48a2-8cdf-31352b17dce3', '銀州北書事', '銀州北书事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["南辭采石遠，北背乞銀深。","磧路雖多險，江人不廢吟。","鵰依孤堠立，鷗向迥沙沈。","因共邊人熟，行行起戰心。"]', '["南辞采石远，北背乞銀深。","磧路雖多險，江人不廢吟。","鵰依孤堠立，鷗向迥沙沈。","因共邊人熟，行行起戰心。"]', '诗', 'shi', '', NULL, '銀州北書事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3114bfa-0709-4755-b79a-0d65b98c913f', '寄趙能卿', '寄趙能卿', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["我命同君命，君詩似我詩。","俱無中道計，各失半生期。","素業滄江遠，清時白髮垂。","蹉跎一如此，何處卜棲遲。"]', '["我命同君命，君诗似我诗。","俱無中道計，各失半生期。","素業滄江远，清时白髮垂。","蹉跎一如此，何处卜棲遲。"]', '诗', 'shi', '', NULL, '寄趙能卿 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('558f05a6-2d64-4d74-9477-fddfb139a080', '夏州道中', '夏州道中', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["茫茫沙漠廣，漸遠赫連城。","堡迥烽相見，河移浪旋生。","無蟬嘶折柳，有寇似防兵。","不耐饑寒迫，終誰至此行。"]', '["茫茫沙漠廣，漸远赫連城。","堡迥烽相见，河移浪旋生。","無蟬嘶折柳，有寇似防兵。","不耐饑寒迫，終誰至此行。"]', '诗', 'shi', '', NULL, '夏州道中 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7b4d66-1c9c-4410-97fe-8415fed1056b', '經故楊太尉舊居', '經故楊太尉旧居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["在漢信垂功，於唐道更隆。","一川留古跡，多代仰高風。","樹折巢墮鳥，階荒草覆蟲。","行人過豈少，獨駐夕陽中。"]', '["在漢信垂功，於唐道更隆。","一川留古跡，多代仰高风。","樹折巢墮鸟，階荒草覆蟲。","行人過豈少，独駐夕陽中。"]', '诗', 'shi', '', NULL, '經故楊太尉舊居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87206e5-44a3-41d3-aaee-eaa71e723047', '東歸次采石江', '东归次采石江', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["東下經牛渚，依然是故關。","客程臨岸盡，鄉思入鷗閑。","雨漲巴來浪，雲增楚際山。","漁翁知未達，相顧不開顏。"]', '["东下經牛渚，依然是故关。","客程臨岸尽，乡思入鷗闲。","雨漲巴来浪，云增楚際山。","漁翁知未達，相顧不开顏。"]', '诗', 'shi', '', NULL, '東歸次采石江 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c31bec8-e8f2-4072-8537-456d66d89320', '隴上書事', '隴上书事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["城疊連雲壑，人家似隱居。","樹飛鸚鵡衆，川下鶺鴒疎。","滴夢關山雨，資餐隴水魚。","誰知江徼客，此景倍相於。"]', '["城叠連云壑，人家似隐居。","樹飞鸚鵡衆，川下鶺鴒疎。","滴梦关山雨，資餐隴水鱼。","誰知江徼客，此景倍相於。"]', '诗', 'shi', '', NULL, '隴上書事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab0df14-2bb9-4dcc-bfb4-739b572d0677', '陳情獻江西李常侍五首 一', '陳情獻江西李常侍五首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["二十二三年，遊秦復滯燕。","徒陪羣彥後，自苦此生前。","徑折啼猿樹，巖荒噴月泉。","東堂曾受薦，垂白志猶堅。"]', '["二十二三年，游秦复滯燕。","徒陪羣彥後，自苦此生前。","徑折啼猿樹，巖荒噴月泉。","东堂曾受薦，垂白志猶堅。"]', '诗', 'shi', '', NULL, '陳情獻江西李常侍五首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c68e64e8-011b-419a-8de5-d507ed7eddb7', '陳情獻江西李常侍五首 二', '陳情獻江西李常侍五首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["淅淅復棲棲，人間只自迷。","終年愁遠道，到老去何蹊。","始見紅葉落，又聞黃鳥啼。","不因趨大斾，誰肯暫提攜。"]', '["淅淅复棲棲，人间只自迷。","終年愁远道，到老去何蹊。","始见紅葉落，又闻黄鸟啼。","不因趨大斾，誰肯暫提携。"]', '诗', 'shi', '', NULL, '陳情獻江西李常侍五首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91415ba5-a44e-4573-8a08-18bd310905f2', '陳情獻江西李常侍五首 三', '陳情獻江西李常侍五首 三', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["童蒙即苦辛，未識杏園春。","謾倚無爲日，還成不偶人。","鄉程長恨遠，旅夢亦愁貧。","天地雖云廣，殊難寄此身。"]', '["童蒙即苦辛，未識杏园春。","謾倚無爲日，還成不偶人。","乡程长恨远，旅梦亦愁貧。","天地雖云廣，殊难寄此身。"]', '诗', 'shi', '', NULL, '陳情獻江西李常侍五首 三 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54a87d2f-ddd3-4066-b93e-1fb229853af5', '陳情獻江西李常侍五首 四', '陳情獻江西李常侍五首 四', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["春闈久已滯，秋賦又逢停。","選士疑長阻，傷時自不寧。","秦城還逐夢，楚徼影隨形。","此去吟雖苦，何人更肯聽。"]', '["春闈久已滯，秋賦又逢停。","選士疑长阻，傷时自不寧。","秦城還逐梦，楚徼影隨形。","此去吟雖苦，何人更肯听。"]', '诗', 'shi', '', NULL, '陳情獻江西李常侍五首 四 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('096298d2-37c5-4c60-b29b-c6213c5f62c6', '陳情獻江西李常侍五首 五', '陳情獻江西李常侍五首 五', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["孤立時全塞，求名勢轉難。","身多離下國，分合阻長安。","越鳥啼春早，蠻花送雨寒。","丘門沾顧重，未別欲闌干。"]', '["孤立时全塞，求名勢轉难。","身多離下国，分合阻长安。","越鸟啼春早，蠻花送雨寒。","丘门沾顧重，未別欲闌干。"]', '诗', 'shi', '', NULL, '陳情獻江西李常侍五首 五 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4a11dd-8bc6-4ab3-bd36-60331c807963', '經八合坂', '經八合坂', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["躡險入高空，初疑勢不窮。","又緣千嶂盡，還共七盤同。","下辨東流水，平隨北去鴻。","天然無此道，應免患窮通。"]', '["躡險入高空，初疑勢不窮。","又緣千嶂尽，還共七盤同。","下辨东流水，平隨北去鴻。","天然無此道，應免患窮通。"]', '诗', 'shi', '', NULL, '經八合坂 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abe37e1d-3483-4bdc-b04b-8011a673681b', '送友人北遊', '送友人北游', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["北出陰關去，何人肯待君。","無青山擁晉，半濁水通汾。","鴈塞雖多鴈，雲州却少雲。","茲遊殊不惡，莫恨暫離羣。"]', '["北出陰关去，何人肯待君。","無青山擁晉，半濁水通汾。","鴈塞雖多鴈，云州却少云。","茲游殊不惡，莫恨暫離羣。"]', '诗', 'shi', '', NULL, '送友人北遊 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c518a3a-30f3-47ad-a914-789c503e687c', '登凌歊臺', '登凌歊台', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["平蕪望已極，況復倚凌歊。","江截吳山斷，天臨楚澤遙。","雲帆高出樹，水市迥分橋。","立久斜陽盡，無言似寂寥。"]', '["平蕪望已極，況复倚凌歊。","江截吳山斷，天臨楚澤遙。","云帆高出樹，水市迥分橋。","立久斜陽尽，無言似寂寥。"]', '诗', 'shi', '', NULL, '登凌歊臺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef7bdab3-c1fa-4a91-85fb-d5c3bb87e21e', '曲江三月三日', '曲江三月三日', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["滿國賞芳辰，飛蹄復走輪。","好花皆折盡，明日恐無春。","鳥避連雲幄，魚驚遠浪塵。","如何當此節，獨自作愁人。"]', '["满国賞芳辰，飞蹄复走輪。","好花皆折尽，明日恐無春。","鸟避連云幄，鱼驚远浪塵。","如何當此節，独自作愁人。"]', '诗', 'shi', '', NULL, '曲江三月三日 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5f7001-ac50-450f-bcc7-7e909043b361', '贈棲白上人', '贈棲白上人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["閑身却不閑，日日對天顏。","已住城中寺，難歸海上山。","詩傳華夏外，偈布市朝間。","欲問空門事，空門豈有關。"]', '["闲身却不闲，日日对天顏。","已住城中寺，难归海上山。","诗傳华夏外，偈布市朝间。","欲问空门事，空门豈有关。"]', '诗', 'shi', '', NULL, '贈棲白上人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc3faf1-36c7-43ff-ba3b-7fb0c0c3ca17', '野步', '野步', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["閑賞步易遠，野吟聲自高。","路無人到跡，林有鶴遺毛。","物外趣都別，塵中心枉勞。","沿溪收墮果，坐石喚飢猱。"]', '["闲賞步易远，野吟声自高。","路無人到跡，林有鹤遺毛。","物外趣都別，塵中心枉勞。","沿溪收墮果，坐石喚飢猱。"]', '诗', 'shi', '', NULL, '野步 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fe86db-ddd1-49ab-a972-c1f0ef6907d8', '過湍溝谷', '過湍溝谷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["西去窮胡處，嵓崖境不常。","石形相對聳，天勢一條長。","棧底鳴流水，林端歛夕陽。","雖隨兵馬至，未免畏豺狼。"]', '["西去窮胡处，嵓崖境不常。","石形相对聳，天勢一條长。","棧底鳴流水，林端歛夕陽。","雖隨兵马至，未免畏豺狼。"]', '诗', 'shi', '', NULL, '過湍溝谷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c4c676-d804-4200-a60b-e4ea33a3bfaa', '送友人遊蜀', '送友人游蜀', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["巴興千萬尋，此去若爲心。","蟋蟀既將定，獼猴應正吟。","劒門秋斷鴈，褒谷夜多砧。","自古西南路，艱難直至今。"]', '["巴兴千万尋，此去若爲心。","蟋蟀既將定，獼猴應正吟。","劒门秋斷鴈，褒谷夜多砧。","自古西南路，艱难直至今。"]', '诗', 'shi', '', NULL, '送友人遊蜀 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5933f9d5-1ba8-4f09-961d-9960f8632f3f', '題秦州城', '題秦州城', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["聖澤滋遐徼，河隄四向通。","大荒收虜帳，遺土復秦風。","亂燒迷歸路，遙山似夢中。","此時懷感切，極目思無窮。"]', '["聖澤滋遐徼，河隄四向通。","大荒收虜帳，遺土复秦风。","亂燒迷归路，遙山似梦中。","此时懷感切，極目思無窮。"]', '诗', 'shi', '', NULL, '題秦州城 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80707477-bfd6-4b6e-9215-65b38e2fbe31', '寄敬亭山清越上人', '寄敬亭山清越上人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["南朝山半寺，謝朓故鄉鄰。","嶺上非無主，秋詩復有人。","高禪星月近，野火虎狼馴。","舊許陪閑社，終應待此身。"]', '["南朝山半寺，謝朓故乡鄰。","嶺上非無主，秋诗复有人。","高禪星月近，野火虎狼馴。","旧許陪闲社，終應待此身。"]', '诗', 'shi', '', NULL, '寄敬亭山清越上人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60fd50d-dd9d-48c0-92fd-6d59ba884652', '秋江霽望', '秋江霽望', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["高秋偏入望，霽景倍關情。","落木滿江水，離人懷渭城。","山高孤戍斷，野極暮天平。","漁父時相問，羞真道姓名。"]', '["高秋偏入望，霽景倍关情。","落木满江水，離人懷渭城。","山高孤戍斷，野極暮天平。","漁父时相问，羞真道姓名。"]', '诗', 'shi', '', NULL, '秋江霽望 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6fc7146-3447-47f8-9997-6314ef7f877b', '隴州旅中書事寄李中丞', '隴州旅中书事寄李中丞', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["三伏客吟過，長安未擬還。","蛩聲秋不動，燕別思仍閑。","亂葉隨寒雨，孤蟾起暮關。","經時高嶺外，來往斾旌間。"]', '["三伏客吟過，长安未擬還。","蛩声秋不动，燕別思仍闲。","亂葉隨寒雨，孤蟾起暮关。","經时高嶺外，来往斾旌间。"]', '诗', 'shi', '', NULL, '隴州旅中書事寄李中丞 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd37b57-bc4c-4bcd-9d14-28ece3f4475e', '秋日歸舊山', '秋日归旧山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["山雲蟬滿樹，欲住更何安。","上國回將晚，孤峰別自難。","磧遙鴻未到，江近夜先寒。","泉石雖堪戀，行人不願看。"]', '["山云蟬满樹，欲住更何安。","上国回將晚，孤峰別自难。","磧遙鴻未到，江近夜先寒。","泉石雖堪戀，行人不願看。"]', '诗', 'shi', '', NULL, '秋日歸舊山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3247fa57-5b9c-4804-ac44-9701949916af', '下黃耳盤', '下黄耳盤', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["獨下黃盤路，多虞部落連。","雲晴仍著地，樹古自參天。","亂鳥飛人上，驚麋起馬前。","行行無郡邑，唯見虎狼煙。"]', '["独下黄盤路，多虞部落連。","云晴仍著地，樹古自參天。","亂鸟飞人上，驚麋起马前。","行行無郡邑，唯见虎狼煙。"]', '诗', 'shi', '', NULL, '下黃耳盤 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1391a02-16b8-466f-932f-2944c267d362', '旅懷', '旅懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["終年唯旅舍，只似已無家。","白髮除還出，丹霄去轉賒。","夏遊窮塞路，春醉負秦花。","應是穹蒼意，空教老若耶。"]', '["終年唯旅舍，只似已無家。","白髮除還出，丹霄去轉賒。","夏游窮塞路，春醉負秦花。","應是穹蒼意，空教老若耶。"]', '诗', 'shi', '', NULL, '旅懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f19e1f-93f4-48e3-9eaf-eda6448207e5', '題金山寺', '題金山寺', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["四面波濤匝，中樓日月鄰。","上窮如出世，下瞷忽驚神。","剎礙長空鳥，船通外國人。","房房皆疊石，風掃永無塵。"]', '["四面波濤匝，中楼日月鄰。","上窮如出世，下瞷忽驚神。","剎礙长空鸟，船通外国人。","房房皆叠石，风掃永無塵。"]', '诗', 'shi', '', NULL, '題金山寺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10cb128-2335-4fa0-8f07-11e1333d19c5', '送王侍御赴宣城', '送王侍御赴宣城', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["朝回離九陌，島外賞殘春。","經宿留閑客，看雲作主人。","時清難議隱，位重亦甘貧。","巖洞真仙境，應休別臥鄰。"]', '["朝回離九陌，島外賞殘春。","經宿留闲客，看云作主人。","时清难議隐，位重亦甘貧。","巖洞真仙境，應休別臥鄰。"]', '诗', 'shi', '', NULL, '送王侍御赴宣城 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba8def9-f47e-484d-b109-f34c1d8dd8ef', '題汧湖二首 一', '題汧湖二首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["偶得湖中趣，都忘隴坻愁。","邊聲風下鴈，楚思浪移舟。","靜極亭連寺，涼多島近樓。","吟遊終不厭，還似曲江頭。"]', '["偶得湖中趣，都忘隴坻愁。","邊声风下鴈，楚思浪移舟。","静極亭連寺，涼多島近楼。","吟游終不厭，還似曲江头。"]', '诗', 'shi', '', NULL, '題汧湖二首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fd12ec-2b8c-46b4-bc64-6ecc8f771467', '題汧湖二首 二', '題汧湖二首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["隴首時無事，湖邊日縱吟。","遊魚來復去，浴鳥出還沈。","蜃氣藏孤嶼，波光到遠林。","無人見垂釣，暗起洞庭心。"]', '["隴首时無事，湖邊日縱吟。","游鱼来复去，浴鸟出還沈。","蜃氣藏孤嶼，波光到远林。","無人见垂釣，暗起洞庭心。"]', '诗', 'shi', '', NULL, '題汧湖二首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b046e21d-7ccd-48c8-9894-3f9580aeace3', '宿青山館', '宿青山館', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["下馬青山下，無言有所思。","雲藏李白墓，苔暗謝公詩。","烈燒飛荒野，棲鳧宿廣陂。","東來與西去，皆是不閑時。"]', '["下马青山下，無言有所思。","云藏李白墓，苔暗謝公诗。","烈燒飞荒野，棲鳧宿廣陂。","东来與西去，皆是不闲时。"]', '诗', 'shi', '', NULL, '宿青山館 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc628054-7221-432e-b0cd-2eed4a7d4bca', '宿同州厲評事舊業寄華下', '宿同州厲評事旧業寄华下', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["從戎依遠地，無日見家山。","地近風沙處，城當甸服間。","阻河通渭水，曲苑帶秦關。","待月登樓夜，何人相伴閑。"]', '["從戎依远地，無日见家山。","地近风沙处，城當甸服间。","阻河通渭水，曲苑带秦关。","待月登楼夜，何人相伴闲。"]', '诗', 'shi', '', NULL, '宿同州厲評事舊業寄華下 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca2f6a2-42a5-4d5d-a9e2-a7a7478fbc9c', '聞蟬十二韻', '闻蟬十二韻', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["造化生微物，常能應候鳴。","初離何處樹，又發去年聲。","未蛻唯愁動，纔飛似解驚。","聞來鄰海徼，恨起過邊城。","騷屑隨風遠，悠揚類雪輕。","報秋涼漸至，嘶月思偏清。","互默疑相荅，微搖似欲行。","繁音人已厭，朽殼蟻猶爭。","朝士嚴冠飾，宮嬪逞鬢名。","亂依西日噪，多引北歸情。","篠露凝潛吸，蛛絲忽迸縈。","此時吟立者，不覺萬愁生。"]', '["造化生微物，常能應候鳴。","初離何处樹，又發去年声。","未蛻唯愁动，纔飞似解驚。","闻来鄰海徼，恨起過邊城。","騷屑隨风远，悠揚類雪轻。","報秋涼漸至，嘶月思偏清。","互默疑相荅，微搖似欲行。","繁音人已厭，朽殼蟻猶爭。","朝士嚴冠飾，宮嬪逞鬢名。","亂依西日噪，多引北归情。","篠露凝潛吸，蛛絲忽迸縈。","此时吟立者，不覺万愁生。"]', '诗', 'shi', '', NULL, '聞蟬十二韻 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b65719f5-c8b3-43aa-b68a-0c305564a423', '冬杪歸陵陽別業五首 一', '冬杪归陵陽別業五首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["無媒歸別業，所向自乖心。","閭里故人少，田園荒草深。","浪翻全失岸，竹迸別成林。","鷗鳥猶相識，時來聽苦吟。"]', '["無媒归別業，所向自乖心。","閭里故人少，田园荒草深。","浪翻全失岸，竹迸別成林。","鷗鸟猶相識，时来听苦吟。"]', '诗', 'shi', '', NULL, '冬杪歸陵陽別業五首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b0e790-6d63-46ac-9250-6ff3edf88f86', '冬杪歸陵陽別業五首 二', '冬杪归陵陽別業五首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["眠雲終未遂，策馬暫休期。","上國勞魂夢，中心甚別離。","冰封巖溜斷，雪壓砌松欹。","骨肉嗟名晚，看歸却淚垂。"]', '["眠云終未遂，策马暫休期。","上国勞魂梦，中心甚別離。","冰封巖溜斷，雪壓砌松欹。","骨肉嗟名晚，看归却泪垂。"]', '诗', 'shi', '', NULL, '冬杪歸陵陽別業五首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc34297-8e44-420b-8b26-92efaaba2a22', '冬杪歸陵陽別業五首 三', '冬杪归陵陽別業五首 三', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["學劒雖無術，吟詩似有魔。","已貧甘事晚，臨老愛閑多。","雞犬唯隨鹿，兒童只衣簑。","時因尋野叟，狂醉復狂歌。"]', '["学劒雖無術，吟诗似有魔。","已貧甘事晚，臨老愛闲多。","雞犬唯隨鹿，兒童只衣簑。","时因尋野叟，狂醉复狂歌。"]', '诗', 'shi', '', NULL, '冬杪歸陵陽別業五首 三 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9238e8-53ff-4beb-88b9-b5ab6a21e1fb', '冬杪歸陵陽別業五首 四', '冬杪归陵陽別業五首 四', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["鄉國亂離後，交親半旅遊。","遠聞誠可念，歸見豈無愁。","敗葦迷荒徑，寒簑沒壞舟。","衡門終不掩，倚杖看波流。"]', '["乡国亂離後，交親半旅游。","远闻誠可念，归见豈無愁。","敗葦迷荒徑，寒簑沒壞舟。","衡门終不掩，倚杖看波流。"]', '诗', 'shi', '', NULL, '冬杪歸陵陽別業五首 四 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfaf9310-de9a-44da-9cdb-3052d6c140ea', '冬杪歸陵陽別業五首 五', '冬杪归陵陽別業五首 五', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["遊秦復滯燕，不覺近衰年。","旅貌同柴毀，行衣對骨穿。","籬寒多啄雀，木落斷浮煙。","楚夜聞鳴鴈，猶疑在塞天。"]', '["游秦复滯燕，不覺近衰年。","旅貌同柴毀，行衣对骨穿。","籬寒多啄雀，木落斷浮煙。","楚夜闻鳴鴈，猶疑在塞天。"]', '诗', 'shi', '', NULL, '冬杪歸陵陽別業五首 五 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b09137-def5-4523-9a53-99e5ea78da53', '送王侍御赴宣城', '送王侍御赴宣城', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["戴豸却驅雞，東南上句溪。","路過金谷口，帆轉石城西。","水樹連天暗，山禽繞郡啼。","江人諳舊化，那復俟招攜。"]', '["戴豸却驱雞，东南上句溪。","路過金谷口，帆轉石城西。","水樹連天暗，山禽繞郡啼。","江人諳旧化，那复俟招携。"]', '诗', 'shi', '', NULL, '送王侍御赴宣城 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964b60ab-3b87-4c2e-b8c6-24bc24ae591b', '春日烏延道中', '春日烏延道中', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["邊窮厄未窮，復此逐歸鴻。","去路多相似，行人半不同。","山川藏北狄，草木背東風。","虛負男兒志，無因立戰功。"]', '["邊窮厄未窮，复此逐归鴻。","去路多相似，行人半不同。","山川藏北狄，草木背东风。","虛負男兒志，無因立戰功。"]', '诗', 'shi', '', NULL, '春日烏延道中 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a417fe1-2881-48e5-a0cf-4bf8bba80c9d', '寄華陰劉拾遺', '寄华陰劉拾遺', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["堅心持諫諍，自古亦艱難。","寄邑雖行化，眠雲似去官。","河分中野斷，岳入半天寒。","瀑布冰成日，誰陪吟復看。"]', '["堅心持諫諍，自古亦艱难。","寄邑雖行化，眠云似去官。","河分中野斷，岳入半天寒。","瀑布冰成日，誰陪吟复看。"]', '诗', 'shi', '', NULL, '寄華陰劉拾遺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218443b5-5d0b-4b72-8364-f60953ec1581', '憶江南', '憶江南', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["南楚西秦遠，名遲別歲深。","欲歸難遂去，閑憶自成吟。","雷電閑傾雨，猿猱鬬墮林。","眠雲機尚在，未忍負初心。"]', '["南楚西秦远，名遲別歲深。","欲归难遂去，闲憶自成吟。","雷電闲傾雨，猿猱鬬墮林。","眠云機尚在，未忍負初心。"]', '诗', 'shi', '', NULL, '憶江南 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea1cfd6-14e5-40d4-ab2e-1ec1b1db96df', '送前汝州李侍御罷歸宣城', '送前汝州李侍御罷归宣城', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["吟詩早得名，戴豸又加榮。","下國閑歸去，他人少此情。","雲移寒嶠出，燒夾夜江明。","重引池塘思，還登謝朓城。"]', '["吟诗早得名，戴豸又加榮。","下国闲归去，他人少此情。","云移寒嶠出，燒夾夜江明。","重引池塘思，還登謝朓城。"]', '诗', 'shi', '', NULL, '送前汝州李侍御罷歸宣城 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043cdcf0-7296-4ca6-a692-7ab91f2a1138', '失題', '失題', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["獨夜長城下，孤吟近北辰。","半天初去鴈，窮磧遠來人。","月黯氛埃積，風羶帳幕鄰。","惟聞防虜寇，不語暗傷神。"]', '["独夜长城下，孤吟近北辰。","半天初去鴈，窮磧远来人。","月黯氛埃積，风羶帳幕鄰。","惟闻防虜寇，不語暗傷神。"]', '诗', 'shi', '', NULL, '失題 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eacfde8-c696-4716-9ef1-4704b6e209fc', '送裴拾遺宰下邽', '送裴拾遺宰下邽', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["受謫因延諫，茲行不出關。","直廬辭玉陛，上馬向仙山。","地古桑麻廣，城偏僕御閑。","縣齋高枕臥，猶夢犯天顏。"]', '["受謫因延諫，茲行不出关。","直廬辞玉陛，上马向仙山。","地古桑麻廣，城偏僕御闲。","縣斋高枕臥，猶梦犯天顏。"]', '诗', 'shi', '', NULL, '送裴拾遺宰下邽 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13db476-8d88-4257-ba3a-4511d057aaec', '隗囂宮晚望', '隗囂宮晚望', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["西顧伊蘭近，方驚滯極邊。","水隨空谷轉，山向夕陽偏。","磧鳥多依地，胡雲不滿天。","秋風動衰草，只覺犬羊羶。"]', '["西顧伊蘭近，方驚滯極邊。","水隨空谷轉，山向夕陽偏。","磧鸟多依地，胡云不满天。","秋风动衰草，只覺犬羊羶。"]', '诗', 'shi', '', NULL, '隗囂宮晚望 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066a2bda-265a-47fa-a4a4-5eb830613e90', '江上行', '江上行', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["片席隨高鳥，連天積浪間。","葦寬雲不匝，風廣雨無閑。","戍影臨孤浦，潮痕在半山。","東原歸未得，荏苒滯江關。"]', '["片席隨高鸟，連天積浪间。","葦寬云不匝，风廣雨無闲。","戍影臨孤浦，潮痕在半山。","东原归未得，荏苒滯江关。"]', '诗', 'shi', '', NULL, '江上行 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6234fd0-ce24-48d1-94f0-5f594f58b87a', '登山', '登山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["信步上鳥道，不知身忽高。","近空無世界，當楚見波濤。","頂峭松多瘦，崖懸石盡牢。","獼猴呼獨散，隔水向人號。"]', '["信步上鸟道，不知身忽高。","近空無世界，當楚见波濤。","頂峭松多瘦，崖懸石尽牢。","獼猴呼独散，隔水向人號。"]', '诗', 'shi', '', NULL, '登山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b4dcb3-7b8a-49a7-90f6-d3677351e5ee', '哭宣城元徵君', '哭宣城元徵君', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["高眠終不起，遠趣固難知。","琴劒今無主，園林舊許誰。","苔封僧坐石，葦漲鶴翹池。","後代傳青史，方欽道德垂。"]', '["高眠終不起，远趣固难知。","琴劒今無主，园林旧許誰。","苔封僧坐石，葦漲鹤翹池。","後代傳青史，方欽道德垂。"]', '诗', 'shi', '', NULL, '哭宣城元徵君 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc8a755-e892-47e1-91f7-a6d342e5cc58', '寄建州姚員外', '寄建州姚員外', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["誣譖遭遐謫，明君即自知。","鄉遙辭劒外，身獨向天涯。","嶺堠蠻雲積，閩空瘴雨垂。","南來終不遂，日探北歸期。"]', '["誣譖遭遐謫，明君即自知。","乡遙辞劒外，身独向天涯。","嶺堠蠻云積，閩空瘴雨垂。","南来終不遂，日探北归期。"]', '诗', 'shi', '', NULL, '寄建州姚員外 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53947303-41a6-4709-bef4-5ecff9eb7a0f', '送厲校書從事鳯翔', '送厲校书從事鳯翔', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["赴辟依丞相，超榮事豈同。","城池當隴右，山水是關中。","日有來巴使，秋高出塞鴻。","旬休隨大斾，應到九成宮。"]', '["赴辟依丞相，超榮事豈同。","城池當隴右，山水是关中。","日有来巴使，秋高出塞鴻。","旬休隨大斾，應到九成宮。"]', '诗', 'shi', '', NULL, '送厲校書從事鳯翔 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4c6d04-8ac9-40bc-b92d-5cd59b944f6f', '春夜同厲文學先輩會宿', '春夜同厲文学先輩會宿', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["江漢久分路，京關重聚吟。","更爲他夜約，方盡昔年心。","月隔明河遠，花藏宿鳥深。","無眠將及曙，多是說山陰。"]', '["江漢久分路，京关重聚吟。","更爲他夜約，方尽昔年心。","月隔明河远，花藏宿鸟深。","無眠將及曙，多是说山陰。"]', '诗', 'shi', '', NULL, '春夜同厲文學先輩會宿 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b65dee2f-f4d0-4819-bd29-e136eb668c40', '長安書情', '长安书情', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["疎散過閑人，同人不在秦。","近來驚白髮，方解惜青春。","僻寺居將遍，權門到絕因。","行藏如此輩，何以謂謀身。"]', '["疎散過闲人，同人不在秦。","近来驚白髮，方解惜青春。","僻寺居將遍，權门到絕因。","行藏如此輩，何以謂謀身。"]', '诗', 'shi', '', NULL, '長安書情 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c587eba-b94f-41ea-8a36-700c28a8f76d', '過故洛城', '過故洛城', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["七百數還窮，城池一旦空。","夕陽唯照草，危堞不勝風。","岸斷河聲別，田荒野色同。"]', '["七百數還窮，城池一旦空。","夕陽唯照草，危堞不勝风。","岸斷河声別，田荒野色同。"]', '诗', 'shi', '', NULL, '過故洛城 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa583569-b65d-4ba3-b4ee-637bdc3b64fc', '寄廬山賈處士', '寄廬山賈处士', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["時泰亦高眠，人皆謂不然。","窮經休望辟，餌朮止期仙。","彭蠡波涵月，爐峰雪照天。","常聞風雨夜，到曉在漁船。"]', '["时泰亦高眠，人皆謂不然。","窮經休望辟，餌朮止期仙。","彭蠡波涵月，爐峰雪照天。","常闻风雨夜，到晓在漁船。"]', '诗', 'shi', '', NULL, '寄廬山賈處士 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30962e66-2d7d-446b-852c-f00d11ba7f13', '下第東歸留別鄭侍郎', '下第东归留別鄭侍郎', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["無才副至公，豈是命難通。","分合吟詩老，家宜逐浪空。","別心懸闕下，歸念極吳東。","唯畏重回日，初情恐不同。"]', '["無才副至公，豈是命难通。","分合吟诗老，家宜逐浪空。","別心懸闕下，归念極吳东。","唯畏重回日，初情恐不同。"]', '诗', 'shi', '', NULL, '下第東歸留別鄭侍郎 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb53543-d3f8-4ff5-9e8d-65e72cce228d', '泗上早發', '泗上早發', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["獨起無人見，長河夜泛時。","平蕪疑自動，落月似相隨。","楚外離空早，關西去已遲。","漁歌聞不絕，却軫洞庭思。"]', '["独起無人见，长河夜泛时。","平蕪疑自动，落月似相隨。","楚外離空早，关西去已遲。","漁歌闻不絕，却軫洞庭思。"]', '诗', 'shi', '', NULL, '泗上早發 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c63d051-2a3f-4fde-b05c-7cc089562837', '贈天台僧', '贈天台僧', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["赤城霞外寺，不忘舊登年。","石上吟分海，樓中語近天。","重遊空有夢，再隱定無緣。","獨夜休行道，星辰靜照禪。"]', '["赤城霞外寺，不忘旧登年。","石上吟分海，楼中語近天。","重游空有梦，再隐定無緣。","独夜休行道，星辰静照禪。"]', '诗', 'shi', '', NULL, '贈天台僧 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269c5fd4-1215-4486-8f89-6bcf83085d53', '冬夜與友人會宿', '冬夜與友人會宿', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["君初離鴈塞，我久滯雕陰。","隔閏俱勞夢，通宵各話心。","禁風吹漏出，原樹映星沉。","白晝常多事，無妨到曉吟。"]', '["君初離鴈塞，我久滯雕陰。","隔閏俱勞梦，通宵各話心。","禁风吹漏出，原樹映星沉。","白晝常多事，無妨到晓吟。"]', '诗', 'shi', '', NULL, '冬夜與友人會宿 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17a881c-c59c-4166-a2dc-bf5c763c4609', '送元遂上人歸吳中', '送元遂上人归吳中', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["落髪在王畿，承恩著紫衣。","印心誰受請，講疏自攜歸。","泛浦龍驚錫，禪雲虎繞扉。","吳中知久別，菴樹想成圍。"]', '["落髪在王畿，承恩著紫衣。","印心誰受請，講疏自携归。","泛浦龙驚錫，禪云虎繞扉。","吳中知久別，菴樹想成圍。"]', '诗', 'shi', '', NULL, '送元遂上人歸吳中 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35f0577-ee8f-4f1e-9006-598450ff168d', '贈志空上人', '贈志空上人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["了了在心中，南宗與北宗。","行高無外染，骨瘦是真容。","飯野盂埋雪，禪雲杖倚松。","常修不住性，必擬老何峰。"]', '["了了在心中，南宗與北宗。","行高無外染，骨瘦是真容。","飯野盂埋雪，禪云杖倚松。","常修不住性，必擬老何峰。"]', '诗', 'shi', '', NULL, '贈志空上人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6abf3000-e6b7-4e12-a5a6-0d5a24083e70', '邊城晚望', '邊城晚望', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["廣漠杳無窮，孤城四面空。","馬行高磧上，日墮迥沙中。","逼曉人移帳，當川樹列風。","迢迢河外路，知直去崆峒。"]', '["廣漠杳無窮，孤城四面空。","马行高磧上，日墮迥沙中。","逼晓人移帳，當川樹列风。","迢迢河外路，知直去崆峒。"]', '诗', 'shi', '', NULL, '邊城晚望 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4da124a-1fbf-4a48-bff9-51614c235346', '汴上暮秋', '汴上暮秋', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["獨立長堤上，西風滿客衣。","日臨秋草廣，山接遠天微。","岸葉隨波盡，沙雲與鳥飛。","秦人寧有素，去意自知歸。"]', '["独立长堤上，西风满客衣。","日臨秋草廣，山接远天微。","岸葉隨波尽，沙云與鸟飞。","秦人寧有素，去意自知归。"]', '诗', 'shi', '', NULL, '汴上暮秋 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2982e9-cf10-4393-9a1c-6b15947f4db0', '春日言懷', '春日言懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["東風萬物新，獨未到幽人。","賦命自多蹇，陽和非不均。","五陵三月暮，百越一家貧。","早悞閑眠處，無愁異此身。"]', '["东风万物新，独未到幽人。","賦命自多蹇，陽和非不均。","五陵三月暮，百越一家貧。","早悞闲眠处，無愁異此身。"]', '诗', 'shi', '', NULL, '春日言懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed42ee7-4f0f-4138-ab25-2dade6390175', '奉天寒食書事', '奉天寒食书事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["處處無煙火，人家似暫空。","曉林花落雨，寒谷鳥啼風。","故里芳洲外，殘春甸服中。","誰知獨西去，步步泣途窮。"]', '["处处無煙火，人家似暫空。","晓林花落雨，寒谷鸟啼风。","故里芳洲外，殘春甸服中。","誰知独西去，步步泣途窮。"]', '诗', 'shi', '', NULL, '奉天寒食書事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78075d0-f785-4652-ba84-179cde9e25d9', '長安寓居', '长安寓居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["貧寄帝城居，交朋日自疎。","愁迎離磧鴈，夢逐出關書。","經雨蟬聲盡，兼風杵韻餘。","誰知江徼塞，所憶在樵漁。"]', '["貧寄帝城居，交朋日自疎。","愁迎離磧鴈，梦逐出关书。","經雨蟬声尽，兼风杵韻餘。","誰知江徼塞，所憶在樵漁。"]', '诗', 'shi', '', NULL, '長安寓居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19dde813-d122-454b-991c-998dc508d3dd', '寫懷', '寫懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["此生居此世，堪笑復堪悲。","在處有岐路，何人無別離。","長當多難日，愁過少年時。","窮達都判了，休閑鑷白髭。"]', '["此生居此世，堪笑复堪悲。","在处有岐路，何人無別離。","长當多难日，愁過少年时。","窮達都判了，休闲鑷白髭。"]', '诗', 'shi', '', NULL, '寫懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b968e6-ce41-4ed5-bfed-9815700ada3d', '白菊', '白菊', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["所尚雪霜姿，非關落帽期。","香飄風外別，影到月中疑。","發在林彫後，繁當露冷時。","人間稀有此，自古乃無詩。"]', '["所尚雪霜姿，非关落帽期。","香飄风外別，影到月中疑。","發在林彫後，繁當露冷时。","人间稀有此，自古乃無诗。"]', '诗', 'shi', '', NULL, '白菊 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c54cae-3f4f-4dc9-8751-a72db00b428d', '中秋夜對月', '中秋夜对月', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["月月勢皆圓，中秋朗最偏。","萬方期一夕，到曉是經年。","影蔽星芒盡，光分物狀全。","惟應苦吟者，目斷向遙天。"]', '["月月勢皆圓，中秋朗最偏。","万方期一夕，到晓是經年。","影蔽星芒尽，光分物狀全。","惟應苦吟者，目斷向遙天。"]', '诗', 'shi', '', NULL, '中秋夜對月 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78c11ea-f427-4c7d-b4d4-e30ee6cc5643', '陪郢州張員外宴白雪樓', '陪郢州張員外宴白雪楼', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["高情日日閑，多宴雪樓間。","灑檻江干雨，當筵天際山。","帶帆分浪色，駐樂話朝班。","豈料羈浮者，樽前得解顏。"]', '["高情日日闲，多宴雪楼间。","灑檻江干雨，當筵天際山。","带帆分浪色，駐乐話朝班。","豈料羈浮者，樽前得解顏。"]', '诗', 'shi', '', NULL, '陪郢州張員外宴白雪樓 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5787c1fc-a94e-40da-b988-8298bad288ee', '和薛侍御題興善寺松', '和薛侍御題兴善寺松', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["何年斸到城，滿國響高名。","半寺陰常匝，鄰坊景亦清。","代多無朽勢，風定有餘聲。","自得天然狀，非同澗底生。"]', '["何年斸到城，满国响高名。","半寺陰常匝，鄰坊景亦清。","代多無朽勢，风定有餘声。","自得天然狀，非同澗底生。"]', '诗', 'shi', '', NULL, '和薛侍御題興善寺松 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b7fce3-199e-45e9-b133-d495e9d32835', '題鄭侍郎巖隱十韻', '題鄭侍郎巖隐十韻', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["朝退常歸隱，真修大隱情。","園林應得趣，巖谷自爲名。","野步難尋寺，閑吟少在城。","樹藏幽洞黑，花照遠村明。","海石分湖路，風泉遰雨聲。","性高憐散逸，官達厭公卿。","架引藤重長，階延笋迸生。","青門無到客，紫閣有來鶯。","物外身雖隱，區中望本清。","終難依此境，坐臥避鈞衡。"]', '["朝退常归隐，真修大隐情。","园林應得趣，巖谷自爲名。","野步难尋寺，闲吟少在城。","樹藏幽洞黑，花照远村明。","海石分湖路，风泉遰雨声。","性高怜散逸，官達厭公卿。","架引藤重长，階延笋迸生。","青门無到客，紫閣有来鶯。","物外身雖隐，區中望本清。","終难依此境，坐臥避鈞衡。"]', '诗', 'shi', '', NULL, '題鄭侍郎巖隱十韻 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f011c51-8964-48f2-944d-e7fc3a1cdd14', '宿靈山蘭若', '宿靈山蘭若', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["江心天半寺，一夕萬緣空。","地出浮雲上，星搖積浪中。","滴漚垂閣雨，吹檜送帆風。","旦夕聞清磬，唯應是釣翁。"]', '["江心天半寺，一夕万緣空。","地出浮云上，星搖積浪中。","滴漚垂閣雨，吹檜送帆风。","旦夕闻清磬，唯應是釣翁。"]', '诗', 'shi', '', NULL, '宿靈山蘭若 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00e09799-b2c9-4eb0-90ac-82766c7402fe', '親仁里雙鷺', '親仁里雙鷺', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["雙去雙來日已頻，只應知我是江人。","對欹雪頂思尋水，更振霜翎恐染塵。","三楚幾時初失侶，五陵何樹又棲身。","天然不與凡禽類，傍砌聽吟性自馴。"]', '["雙去雙来日已頻，只應知我是江人。","对欹雪頂思尋水，更振霜翎恐染塵。","三楚幾时初失侶，五陵何樹又棲身。","天然不與凡禽類，傍砌听吟性自馴。"]', '诗', 'shi', '', NULL, '親仁里雙鷺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2daa2155-cd32-40c9-9283-0941a17e0745', '成紀書事二首 一', '成紀书事二首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["東吳遠別客西秦，懷舊傷時暗灑巾。","滿野多成無主塚，防邊半是異鄉人。","山河再闊千餘里，城市曾經一百春。","閑與將軍議戎事，伊蘭猶未絕胡塵。"]', '["东吳远別客西秦，懷旧傷时暗灑巾。","满野多成無主塚，防邊半是異乡人。","山河再闊千餘里，城市曾經一百春。","闲與將軍議戎事，伊蘭猶未絕胡塵。"]', '诗', 'shi', '', NULL, '成紀書事二首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016a4ee1-0e71-4fcf-9b97-89ccba275655', '成紀書事二首 二', '成紀书事二首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["蹉跎遠入犬羊中，荏苒將成白首翁。","三楚田園歸未得，五原岐路去無窮。","天垂大野鵰盤草，月落孤城角嘯風。","難問開元向前事，依稀猶認隗囂宮。"]', '["蹉跎远入犬羊中，荏苒將成白首翁。","三楚田园归未得，五原岐路去無窮。","天垂大野鵰盤草，月落孤城角嘯风。","难问开元向前事，依稀猶認隗囂宮。"]', '诗', 'shi', '', NULL, '成紀書事二首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a79304b-d2a1-4624-8721-3d1454d2406d', '秦中遇友人', '秦中遇友人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["半生南走復西馳，愁過楊朱罷泣岐。","遠夢亦羞歸海徼，貧遊多是滯邊陲。","胡雲不聚風無定，隴路難行棧更危。","旦暮唯聞語征戰，看看已欲廢吟詩。"]', '["半生南走复西驰，愁過楊朱罷泣岐。","远梦亦羞归海徼，貧游多是滯邊陲。","胡云不聚风無定，隴路难行棧更危。","旦暮唯闻語征戰，看看已欲廢吟诗。"]', '诗', 'shi', '', NULL, '秦中遇友人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425ef6f9-c6a9-4b14-8dcb-4aff9d68c360', '過分水嶺', '過分水嶺', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["隴山高共鳥行齊，瞰險盤空甚躡梯。","雲勢崩騰時向背，水聲嗚咽若東西。","風兼雨氣吹人面，石帶冰棱礙馬蹄。","此去秦川無別路，隔崖窮谷却難迷。"]', '["隴山高共鸟行齊，瞰險盤空甚躡梯。","云勢崩腾时向背，水声嗚咽若东西。","风兼雨氣吹人面，石带冰棱礙马蹄。","此去秦川無別路，隔崖窮谷却难迷。"]', '诗', 'shi', '', NULL, '過分水嶺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f584ef-a7b5-4308-bdb7-4ed9c2b4286a', '講德陳情上淮南李僕射八首 一', '講德陳情上淮南李僕射八首 一', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["天降賢人佐聖時，自然聲教滿華夷。","英明不獨中朝仰，清重兼聞外國知。","涼夜酒醒多對月，曉庭公退半吟詩。","梁城東下雖經戰，風俗猶傳守舊規。"]', '["天降賢人佐聖时，自然声教满华夷。","英明不独中朝仰，清重兼闻外国知。","涼夜酒醒多对月，晓庭公退半吟诗。","梁城东下雖經戰，风俗猶傳守旧規。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 一 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e040e802-2855-49c0-9c97-f6b60c21361c', '講德陳情上淮南李僕射八首 二', '講德陳情上淮南李僕射八首 二', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["多朝軒冕冠乾坤，四海皆推聖最尊。","楚玉已曾分卞玉，膺門依舊是龍門。","筵開樂振高雲動，城掩鼙收落日昏。","嘗念蒼生如赤子，九州無處不沾恩。"]', '["多朝軒冕冠乾坤，四海皆推聖最尊。","楚玉已曾分卞玉，膺门依旧是龙门。","筵开乐振高云动，城掩鼙收落日昏。","嘗念蒼生如赤子，九州無处不沾恩。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 二 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b7bb8c-4fdd-484d-b17c-1585dde29399', '講德陳情上淮南李僕射八首 三', '講德陳情上淮南李僕射八首 三', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["未領春闈望早清，況聯戎閫控強兵。","風威遍布江山靜，教化高同日月明。","九郡竟歌兼煮海，四方皆得共和羹。","東南自此全無事，只爲期年政已成。"]', '["未領春闈望早清，況聯戎閫控強兵。","风威遍布江山静，教化高同日月明。","九郡竟歌兼煮海，四方皆得共和羹。","东南自此全無事，只爲期年政已成。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 三 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b33d72-8eda-4c1c-9a3f-3cb2466f31d6', '講德陳情上淮南李僕射八首 四', '講德陳情上淮南李僕射八首 四', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["帝念淮堧疫疹頻，牢籠山海委名臣。","古來比德由無侶，當代同途豈有人。","夜宴獨吟梁苑月，朝遊重見廣陵春。","多年疲瘵全蘇息，須到謳謠日滿秦。"]', '["帝念淮堧疫疹頻，牢籠山海委名臣。","古来比德由無侶，當代同途豈有人。","夜宴独吟梁苑月，朝游重见廣陵春。","多年疲瘵全蘇息，須到謳謠日满秦。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 四 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ae41d7-92e6-4144-8bcb-0698ac15ad0b', '講德陳情上淮南李僕射八首 五', '講德陳情上淮南李僕射八首 五', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["三紀吟詩望一名，丹霄待得白頭成。","已期到老還沾祿，無復偷閑却養生。","當宴每垂聽樂淚，望雲長起憶山情。","朱門舊是登龍客，初脫魚鱗膽尚驚。"]', '["三紀吟诗望一名，丹霄待得白头成。","已期到老還沾祿，無复偷闲却養生。","當宴每垂听乐泪，望云长起憶山情。","朱门旧是登龙客，初脫鱼鱗膽尚驚。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 五 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f5a26f-e70f-4d09-90dc-77fca2345ecc', '講德陳情上淮南李僕射八首 六', '講德陳情上淮南李僕射八首 六', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["東來淮海拜旌旟，不把公卿一字書。","曾侍晚齋吟對雪，又容華館食兼魚。","孤微自省恩非次，際會誰知分有餘。","唯耻舊橋題處在，榮歸無計似相如。"]', '["东来淮海拜旌旟，不把公卿一字书。","曾侍晚斋吟对雪，又容华館食兼鱼。","孤微自省恩非次，際會誰知分有餘。","唯耻旧橋題处在，榮归無計似相如。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 六 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5555e848-95bb-495a-9cac-006bdffcadc3', '講德陳情上淮南李僕射八首 七', '講德陳情上淮南李僕射八首 七', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["平生南北逐蓬飄，待得名成鬢已彫。","寒浦一從拋釣艇，舊林無處認風飆。","程途雖喜關河盡，時節猶驚骨肉遙。","愁策羸蹄更歸去，亂山流水滿翻潮。"]', '["平生南北逐蓬飄，待得名成鬢已彫。","寒浦一從拋釣艇，旧林無处認风飆。","程途雖喜关河尽，时節猶驚骨肉遙。","愁策羸蹄更归去，亂山流水满翻潮。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 七 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb68444e-2252-4083-b9bc-5276dce424e1', '講德陳情上淮南李僕射八首 八', '講德陳情上淮南李僕射八首 八', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["丹霄空把桂枝歸，白首依前着布衣。","當路公卿誰見待，故鄉親愛自疑非。","東風乍喜還滄海，棲旅終愁出翠微。","應念無媒居選限，二年須更守漁磯。"]', '["丹霄空把桂枝归，白首依前着布衣。","當路公卿誰见待，故乡親愛自疑非。","东风乍喜還滄海，棲旅終愁出翠微。","應念無媒居選限，二年須更守漁磯。"]', '诗', 'shi', '', NULL, '講德陳情上淮南李僕射八首 八 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3be07d-63fe-47e3-86be-7cb8e3d26c69', '獻獨孤尚書', '獻独孤尚书', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["虛拋南楚滯西秦，白首依前衣白身。","退鷁已經三十載，登龍曾見一千人。","魂離爲役詩篇苦，淚竭緣嗟骨相貧。","今日鞠躬高斾下，欲傾肝膽杳無因。"]', '["虛拋南楚滯西秦，白首依前衣白身。","退鷁已經三十載，登龙曾见一千人。","魂離爲役诗篇苦，泪竭緣嗟骨相貧。","今日鞠躬高斾下，欲傾肝膽杳無因。"]', '诗', 'shi', '', NULL, '獻獨孤尚書 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141ab2c2-5d74-453a-aba3-94a1f1b6c23d', '將過單于', '將過單于', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["荒磧連天堡戍稀，日憂蕃寇却忘機。","江山不到處皆到，隴鴈已歸時未歸。","行李亦須攜戰器，趨迎當便著戎衣。","幷州去路殊迢遰，風雨何當達近畿。"]', '["荒磧連天堡戍稀，日憂蕃寇却忘機。","江山不到处皆到，隴鴈已归时未归。","行李亦須携戰器，趨迎當便著戎衣。","幷州去路殊迢遰，风雨何當達近畿。"]', '诗', 'shi', '', NULL, '將過單于 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bf66c7-df85-4c06-bdca-66fb75e56028', '貞女祠', '貞女祠', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["何穴藏貞骨，荒祠見舊顏。","精靈應自在，雲雨不相關。","落石泉多咽，無風樹盡閑。","唯疑千古後，爲瑞向人間。"]', '["何穴藏貞骨，荒祠见旧顏。","精靈應自在，云雨不相关。","落石泉多咽，無风樹尽闲。","唯疑千古後，爲瑞向人间。"]', '诗', 'shi', '', NULL, '貞女祠 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe90a3a-14c7-45f9-aaa6-2532610d3e37', '宿華山', '宿华山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["異境良難測，非仙豈合遊。","星辰方滿岳，風雨忽移舟。","噴月泉垂壁，棲松鶴在樓。","因知休養處，不必在嵩丘。"]', '["異境良难測，非仙豈合游。","星辰方满岳，风雨忽移舟。","噴月泉垂壁，棲松鹤在楼。","因知休養处，不必在嵩丘。"]', '诗', 'shi', '', NULL, '宿華山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1e25e7-2ecb-4804-bb6e-338990f3106d', '送張員外西川從事', '送張員外西川從事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["爲郎不入朝，自是赴嘉招。","豸角初離首，金章已在腰。","劒橫陰綠野，棧響近丹霄。","迎驛應相續，懸愁去路遙。"]', '["爲郎不入朝，自是赴嘉招。","豸角初離首，金章已在腰。","劒橫陰綠野，棧响近丹霄。","迎驛應相續，懸愁去路遙。"]', '诗', 'shi', '', NULL, '送張員外西川從事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9e3a7d-76f6-450f-8fa0-b23a2588282a', '題慈恩寺元遂上人院', '題慈恩寺元遂上人院', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["竹檻匝回廊，城中似外方。","月雲開作片，枝鳥立成行。","徑接河源潤，庭容塔影涼。","天台頻去說，誰占最高房。"]', '["竹檻匝回廊，城中似外方。","月云开作片，枝鸟立成行。","徑接河源潤，庭容塔影涼。","天台頻去说，誰占最高房。"]', '诗', 'shi', '', NULL, '題慈恩寺元遂上人院 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b1d624-848d-4497-b9eb-4f8090b01e9d', '送杜倉曹往滄洲覲叔常侍', '送杜倉曹往滄洲覲叔常侍', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["浮陽橫巨浸，南巷擁旌旃。","別帶秦城雨，行聞魏國蟬。","磧鴻來每後，朝日見常先。","東鄙雲霞廣，高林間水天。"]', '["浮陽橫巨浸，南巷擁旌旃。","別带秦城雨，行闻魏国蟬。","磧鴻来每後，朝日见常先。","东鄙云霞廣，高林间水天。"]', '诗', 'shi', '', NULL, '送杜倉曹往滄洲覲叔常侍 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b92379-60e2-4202-abe1-1f60edaa379c', '雕陰道中作', '雕陰道中作', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["五月綏州北，途程少鬱蒸。","馬依羶草聚，人抱濁河澄。","蹟固長城壘，冤深太子陵。","往來經此地，悲苦有誰能。"]', '["五月綏州北，途程少鬱蒸。","马依羶草聚，人抱濁河澄。","蹟固长城壘，冤深太子陵。","往来經此地，悲苦有誰能。"]', '诗', 'shi', '', NULL, '雕陰道中作 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f46f04-5812-4986-8569-0cf288a67869', '留別從弟郴', '留別從弟郴', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["同承太嶽胤，俱值太平時。","丹陛懷趨計，滄洲負去期。","久貧成蹭蹬，多病惜支離。","宗分兼交分，吾知汝亦知。"]', '["同承太嶽胤，俱值太平时。","丹陛懷趨計，滄洲負去期。","久貧成蹭蹬，多病惜支離。","宗分兼交分，吾知汝亦知。"]', '诗', 'shi', '', NULL, '留別從弟郴 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('688e565c-a8c4-4e76-bfaf-2774e7a15531', '尋山', '尋山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["躡履復支筇，深山草木中。","隔溪遙避虎，當塢忽聞鐘。","落葉多相似，幽禽半不同。","羣猱呼却散，如此異林翁。"]', '["躡履复支筇，深山草木中。","隔溪遙避虎，當塢忽闻鐘。","落葉多相似，幽禽半不同。","羣猱呼却散，如此異林翁。"]', '诗', 'shi', '', NULL, '尋山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5f10c9-8d99-47a5-9e5e-627953a61201', '送徐侍御充南詔判官', '送徐侍御充南詔判官', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["西去安夷落，乘軺從節行。","彤庭傳聖旨，異城化戎情。","瘴路窮巴徼，蠻川過嶠城。","地偏風自雜，天漏月稀明。","危棧連空動，長江到底清。","笑宜防狒狒，言好聽猩猩。","撫論如敦行，歸情自合盟。","迴期佩印綬，何更見新正。"]', '["西去安夷落，乘軺從節行。","彤庭傳聖旨，異城化戎情。","瘴路窮巴徼，蠻川過嶠城。","地偏风自杂，天漏月稀明。","危棧連空动，长江到底清。","笑宜防狒狒，言好听猩猩。","撫論如敦行，归情自合盟。","迴期佩印綬，何更见新正。"]', '诗', 'shi', '', NULL, '送徐侍御充南詔判官 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26c79d6-e596-4074-a733-738ca69bd464', '送省玄上人歸江東', '送省玄上人归江东', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["釋律周儒禮，嚴持用戒身。","安禪思剡石，留偈別都人。","雨合吳江黑，潮移海路新。","缾盂自此去，應不更還秦。"]', '["釋律周儒禮，嚴持用戒身。","安禪思剡石，留偈別都人。","雨合吳江黑，潮移海路新。","缾盂自此去，應不更還秦。"]', '诗', 'shi', '', NULL, '送省玄上人歸江東 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c721d80-41c2-4095-863e-16d5bcd1687c', '送劉校書遊東魯', '送劉校书游东魯', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["內閣勞讎校，東邦忽縱遊。","才編精二雅，分合遇諸侯。","暗海龜蒙雨，連空趙魏秋。","如經麟見處，駐馬瞰荒丘。"]', '["內閣勞讎校，东邦忽縱游。","才編精二雅，分合遇諸侯。","暗海龟蒙雨，連空趙魏秋。","如經麟见处，駐马瞰荒丘。"]', '诗', 'shi', '', NULL, '送劉校書遊東魯 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a227a6-77bf-4939-a217-9bf9ec7f41ec', '送金吾侍御奉使日東', '送金吾侍御奉使日东', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["還鄉兼作使，到日倍榮親。","向化雖多國，如公有幾人。","孤山無返照，積水合蒼旻。","膝下知難住，金章已繫身。"]', '["還乡兼作使，到日倍榮親。","向化雖多国，如公有幾人。","孤山無返照，積水合蒼旻。","膝下知难住，金章已繫身。"]', '诗', 'shi', '', NULL, '送金吾侍御奉使日東 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca39a67e-23b4-446e-8416-4384f3e7c027', '題甘露寺', '題甘露寺', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["丹檻拂丹霄，人寰下瞰遙。","何年增造化，萬古出塵囂。","地勢盤三楚，江聲換幾朝。","滿欄皆異藥，到頂盡飛橋。","澤廣方雲夢，山孤數沃焦。","中[宵]霞始散，經臘木稀凋。","鐸動天風度，窗明海氣消。","帶鼙分迥堞，當日辨翻潮。","鳥去沉葭菼，帆來映泬㵳。","浮生自多事，無計免迴鑣。"]', '["丹檻拂丹霄，人寰下瞰遙。","何年增造化，万古出塵囂。","地勢盤三楚，江声換幾朝。","满欄皆異藥，到頂尽飞橋。","澤廣方云梦，山孤數沃焦。","中[宵]霞始散，經臘木稀凋。","鐸动天风度，窗明海氣消。","带鼙分迥堞，當日辨翻潮。","鸟去沉葭菼，帆来映泬㵳。","浮生自多事，無計免迴鑣。"]', '诗', 'shi', '', NULL, '題甘露寺 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af4226f9-84bb-4c36-bf9f-f168379c4a07', '冬夜懷真里友人會宿', '冬夜懷真里友人會宿', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["靜語與高吟，搜神又爽心。","各來依帝里，相對似山陰。","漏永星河沒，堂寒月彩深。","從容不易到，莫惜曙鐘侵。"]', '["静語與高吟，搜神又爽心。","各来依帝里，相对似山陰。","漏永星河沒，堂寒月彩深。","從容不易到，莫惜曙鐘侵。"]', '诗', 'shi', '', NULL, '冬夜懷真里友人會宿 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80e109a-8bda-445d-b83f-b5fc8236edf8', '陪友人夏夜對月', '陪友人夏夜对月', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["後伏中宵月，高秋滿魄齊。","輪移仙掌外，影下玉繩西。","蟬雀飛多悞，星螢出自迷。","煩蒸驚頓絕，吟翫畏聞雞。"]', '["後伏中宵月，高秋满魄齊。","輪移仙掌外，影下玉繩西。","蟬雀飞多悞，星螢出自迷。","煩蒸驚頓絕，吟翫畏闻雞。"]', '诗', 'shi', '', NULL, '陪友人夏夜對月 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d850b7-e5fa-4bc9-9291-cca36a0af3c8', '送從弟籌任告成尉', '送從弟籌任告成尉', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["海上從戎罷，嵩陽佐縣初。","故人皆羨去，吾祖舊曾居。","地古多生藥，溪靈不聚魚。","唯應尋隱者，閑寺講仙書。"]', '["海上從戎罷，嵩陽佐縣初。","故人皆羨去，吾祖旧曾居。","地古多生藥，溪靈不聚鱼。","唯應尋隐者，闲寺講仙书。"]', '诗', 'shi', '', NULL, '送從弟籌任告成尉 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eaceacf-41ce-4ed0-9683-352578db792b', '秋日陪陸校書遊玉泉', '秋日陪陸校书游玉泉', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["共愛泉源異，頻來不覺勞。","散光垂草細，繁響出風高。","沫滯潭花片，沙遺浴鳥毛。","塵間喧與悶，須向此中逃。"]', '["共愛泉源異，頻来不覺勞。","散光垂草細，繁响出风高。","沫滯潭花片，沙遺浴鸟毛。","塵间喧與悶，須向此中逃。"]', '诗', 'shi', '', NULL, '秋日陪陸校書遊玉泉 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1b49fd-0e0a-4f8a-86b0-3436e286fac7', '送防州鄔員外', '送防州鄔員外', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["千溪與萬嶂，繚繞復崢嶸。","太守勞車馬，何從駐斾旌。","椒香近滿郭，漆貨遠通京。","唯滌雙塵耳，東南聽政聲。"]', '["千溪與万嶂，繚繞复崢嶸。","太守勞车马，何從駐斾旌。","椒香近满郭，漆貨远通京。","唯滌雙塵耳，东南听政声。"]', '诗', 'shi', '', NULL, '送防州鄔員外 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df80663c-eb58-410d-b2f5-0f7188bde5ee', '過穆陵關', '過穆陵关', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["荒關無守吏，亦耻白衣過。","地廣人耕絕，天寒鴈下多。","東西方自感，雨雪更相和。","日暮聊攄思，搖鞭一放歌。"]', '["荒关無守吏，亦耻白衣過。","地廣人耕絕，天寒鴈下多。","东西方自感，雨雪更相和。","日暮聊攄思，搖鞭一放歌。"]', '诗', 'shi', '', NULL, '過穆陵關 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b91b959f-e79d-4b87-b91e-c96b1c352183', '江上遇友人', '江上遇友人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["闕下分離日，杏園花半開。","江邊相值夜，榆塞鴈初來。","坐久河沉斗，吟長月浸杯。","鱸魚非不戀，共有客程催。"]', '["闕下分離日，杏园花半开。","江邊相值夜，榆塞鴈初来。","坐久河沉斗，吟长月浸杯。","鱸鱼非不戀，共有客程催。"]', '诗', 'shi', '', NULL, '江上遇友人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e6f1dc-f2be-4a99-90bc-cbdd55dc7b5e', '憶宛陵舊居', '憶宛陵旧居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["舊憶陵陽北，林園近板橋。","江晴帆影滿，野迥鶴聲遙。","鳥徑通山市，汀扉上海潮。","秦城歸去夢，夜夜到漁樵。"]', '["旧憶陵陽北，林园近板橋。","江晴帆影满，野迥鹤声遙。","鸟徑通山市，汀扉上海潮。","秦城归去梦，夜夜到漁樵。"]', '诗', 'shi', '', NULL, '憶宛陵舊居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab529ff-af54-4265-b1a6-560d2fbfc749', '題聞琴館', '題闻琴館', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["城非宓賤邑，館亦號聞琴。","乃是前賢意，常留化俗心。","代公存綠綺，誰更寄清音。","此迹應無改，寥寥畢古今。"]', '["城非宓賤邑，館亦號闻琴。","乃是前賢意，常留化俗心。","代公存綠綺，誰更寄清音。","此迹應無改，寥寥畢古今。"]', '诗', 'shi', '', NULL, '題聞琴館 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('923eca15-6f96-4c09-829f-642286c17dd6', '寄江上弟妹', '寄江上弟妹', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["無成歸未得，不是不謀歸。","垂老登雲路，猶勝守釣磯。","大荒身去數，窮海信來稀。","孤立皆難進，非關命獨違。"]', '["無成归未得，不是不謀归。","垂老登云路，猶勝守釣磯。","大荒身去數，窮海信来稀。","孤立皆难進，非关命独違。"]', '诗', 'shi', '', NULL, '寄江上弟妹 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfd5abd-1077-4f6a-a88e-aab15d17b448', '題李昌符豐樂幽居', '題李昌符豐乐幽居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["詩家依闕下，野景似山中。","蘭菊俱含露，杉梧爲奏風。","破門韋曲對，淺岸御溝通。","莫歎連年屈，君須遇至公。"]', '["诗家依闕下，野景似山中。","蘭菊俱含露，杉梧爲奏风。","破门韋曲对，淺岸御溝通。","莫歎連年屈，君須遇至公。"]', '诗', 'shi', '', NULL, '題李昌符豐樂幽居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3977d7-0456-4269-aa94-313158c14c11', '青山晚望', '青山晚望', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["昔人懷感處，此地倍魂消。","四海經搖落，三吳正寂寥。","風移殘燒遠，帆帶夕陽遙。","欲繼前賢跡，誰能似隱招。"]', '["昔人懷感处，此地倍魂消。","四海經搖落，三吳正寂寥。","风移殘燒远，帆带夕陽遙。","欲繼前賢跡，誰能似隐招。"]', '诗', 'shi', '', NULL, '青山晚望 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5d50cd-88b8-4977-9935-1f405c00dc58', '宣城送進士鄭徽赴舉', '宣城送進士鄭徽赴舉', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["長安去是歸，上馬肯沾衣。","水國車通少，秦人楚薦稀。","鴻方離北鄙，葉下已西畿。","好整丹霄步，知音在紫微。"]', '["长安去是归，上马肯沾衣。","水国车通少，秦人楚薦稀。","鴻方離北鄙，葉下已西畿。","好整丹霄步，知音在紫微。"]', '诗', 'shi', '', NULL, '宣城送進士鄭徽赴舉 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85aea06b-20d9-4d9a-8394-798cd69b3c7f', '言懷', '言懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["萬事不關心，終朝但苦吟。","久貧慙負債，漸老愛山深。","日月銷天外，帆檣棄海陰。","榮枯應已定，無復繫浮沉。"]', '["万事不关心，終朝但苦吟。","久貧慙負債，漸老愛山深。","日月銷天外，帆檣棄海陰。","榮枯應已定，無复繫浮沉。"]', '诗', 'shi', '', NULL, '言懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf4bcae-a0b5-403c-bab1-feca26fd8a5d', '汴河十二韻', '汴河十二韻', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["昔年開汴水，元應別有由。","或兼通楚塞，寧獨爲揚州。","直斷平蕪色，橫分積石流。","所思千里便，豈計萬方憂。","首甚資功濟，終難弭宴遊。","空懷龍舸下，不見錦帆收。","浪倒長汀柳，風欹遠岸樓。","奔逾懷許竭，澄徹泗濱休。","路要多行客，魚稀少釣舟。","日開天際晚，鴈合磧西秋。","一派注滄海，幾人生白頭。","常期身事畢，於此泳東浮。"]', '["昔年开汴水，元應別有由。","或兼通楚塞，寧独爲揚州。","直斷平蕪色，橫分積石流。","所思千里便，豈計万方憂。","首甚資功濟，終难弭宴游。","空懷龙舸下，不见錦帆收。","浪倒长汀柳，风欹远岸楼。","奔逾懷許竭，澄徹泗濱休。","路要多行客，鱼稀少釣舟。","日开天際晚，鴈合磧西秋。","一派注滄海，幾人生白头。","常期身事畢，於此泳东浮。"]', '诗', 'shi', '', NULL, '汴河十二韻 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('176d8f52-e01b-4d31-9aed-993aa81c1d0c', '旅中送人歸九華', '旅中送人归九华', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["分與仙山背，多年負翠微。","無因隨鹿去，只是送人歸。","頂木晴摩日，根嵐曉潤衣。","會於猨鳥外，相對掩高扉。"]', '["分與仙山背，多年負翠微。","無因隨鹿去，只是送人归。","頂木晴摩日，根嵐晓潤衣。","會於猨鸟外，相对掩高扉。"]', '诗', 'shi', '', NULL, '旅中送人歸九華 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c7e56b-5129-4da4-9c8b-b911a3e6f21b', '送友人歸江南', '送友人归江南', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["皇州五更鼓，月落西南維。","此時有行客，別我孤舟歸。","上國身無主，下第誠可悲。"]', '["皇州五更鼓，月落西南維。","此时有行客，別我孤舟归。","上国身無主，下第誠可悲。"]', '诗', 'shi', '', NULL, '送友人歸江南 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84560c0-6d4d-4875-9e36-ca08dad0abc8', '洞庭湖', '洞庭湖', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["空江浩蕩景蕭然，盡日菰蒲泊釣船。","青草浪高三月渡，綠楊花撲一溪煙。","情多莫舉傷春目，愁極兼無買酒錢。","猶有漁人數家住，不成村落夕陽邊。"]', '["空江浩蕩景蕭然，尽日菰蒲泊釣船。","青草浪高三月渡，綠楊花撲一溪煙。","情多莫舉傷春目，愁極兼無買酒錢。","猶有漁人數家住，不成村落夕陽邊。"]', '诗', 'shi', '', NULL, '洞庭湖 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f57b2b-b013-43bc-a5c1-349b66b282b5', '句', '句', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["曉嶂猨開戶，寒湫鹿舐冰。","當空吟待月，到晚坐看山。","一年三領郡，領郡管仙山。"]', '["晓嶂猨开戶，寒湫鹿舐冰。","當空吟待月，到晚坐看山。","一年三領郡，領郡管仙山。"]', '诗', 'shi', '', NULL, '句 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361e35b8-dcc9-42ea-99ad-f07e9ef14918', '放歌行', '放歌行', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["龜爲秉靈亡，魚爲弄珠死。","心中自有賊，莫怨任公子。","屈原若不賢，焉得沈湘水。"]', '["龟爲秉靈亡，鱼爲弄珠死。","心中自有賊，莫怨任公子。","屈原若不賢，焉得沈湘水。"]', '诗', 'shi', '', NULL, '放歌行 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0614785f-46f6-4ba9-9e14-0c25326f6f06', '長安寒食', '长安寒食', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["春日照九衢，春風媚羅綺。","萬騎出都門，擁在香塵裏。","莫辭弔枯骨，千載長如此。","安知今日身，不是昔時鬼。","但看平地遊，亦見摧輈死。"]', '["春日照九衢，春风媚羅綺。","万騎出都门，擁在香塵裏。","莫辞弔枯骨，千載长如此。","安知今日身，不是昔时鬼。","但看平地游，亦见摧輈死。"]', '诗', 'shi', '', NULL, '長安寒食 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996d8689-9292-4d6b-bba5-f675cd0be3c7', '貞女墓', '貞女墓', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["生持節操心，死作堅貞鬼。","至今墳上春，草木無花卉。"]', '["生持節操心，死作堅貞鬼。","至今墳上春，草木無花卉。"]', '诗', 'shi', '', NULL, '貞女墓 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa01339-4c77-4c49-828d-b859885ac1c4', '自歎', '自歎', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["春蠶未成繭，已賀箱籠實。","蟢子徒有絲，終年不成匹。","每念古人言，有得則有失。","我命獨如何，憔悴長如一。","白日九衢中，幽獨暗如漆。","流泉有枯時，窮賤無盡日。","惆悵復惆悵，幾迴新月出。"]', '["春蠶未成繭，已賀箱籠實。","蟢子徒有絲，終年不成匹。","每念古人言，有得則有失。","我命独如何，憔悴长如一。","白日九衢中，幽独暗如漆。","流泉有枯时，窮賤無尽日。","惆悵复惆悵，幾迴新月出。"]', '诗', 'shi', '', NULL, '自歎 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cdd7471-9eee-46b8-a481-c6d1234ca163', '送徐羣宰望江', '送徐羣宰望江', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["古人力文學，所務安疲甿。","今人力文學，所務惟公卿。","大賢重邦本，屈跡官武城。","勸民勤機杼，自然國用幷。","但見富貴者，知食不知耕。","忽爾秋不熟，儲廩焉得盈。","貢藝既精苦，用心必公平。","吾道不遺賢，霄漢期芳馨。","一夫若有德，千古稱其英。","陶潛雖理邑，崔烈徒台衡。","濁者必惡清，瞽者必惡明。","孤松自有色，豈奪衆草榮。","爲刀若不利，焉得宰牛名。","爲絲若不直，焉得琴上聲。","好去立高節，重來振羽翎。"]', '["古人力文学，所務安疲甿。","今人力文学，所務惟公卿。","大賢重邦本，屈跡官武城。","勸民勤機杼，自然国用幷。","但见富貴者，知食不知耕。","忽爾秋不熟，儲廩焉得盈。","貢藝既精苦，用心必公平。","吾道不遺賢，霄漢期芳馨。","一夫若有德，千古稱其英。","陶潛雖理邑，崔烈徒台衡。","濁者必惡清，瞽者必惡明。","孤松自有色，豈奪衆草榮。","爲刀若不利，焉得宰牛名。","爲絲若不直，焉得琴上声。","好去立高節，重来振羽翎。"]', '诗', 'shi', '', NULL, '送徐羣宰望江 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b263ca8e-028e-41e3-93e5-435eaafef2d2', '秋夕', '秋夕', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["萬里憑夢歸，骨肉皆在眼。","覺來益惆悵，不信長安遠。","人人但爲農，我獨常逢旱。","惡命如漏巵，滴滴添不滿。","天末雁來時，一呌一腸斷。"]', '["万里憑梦归，骨肉皆在眼。","覺来益惆悵，不信长安远。","人人但爲農，我独常逢旱。","惡命如漏巵，滴滴添不满。","天末雁来时，一呌一腸斷。"]', '诗', 'shi', '', NULL, '秋夕 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3864e8c1-a9da-4f18-bc2d-3a0ad463e0df', '覽孟東野集', '覽孟东野集', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["蚌死留夜光，劍折留鋒鋩。","哲人歸大夜，千古傳珪璋。","珪璋徧四海，人倫多變改。","題花花已無，翫月月猶在。","不知天地間，白日幾時昧。"]', '["蚌死留夜光，劍折留鋒鋩。","哲人归大夜，千古傳珪璋。","珪璋徧四海，人倫多变改。","題花花已無，翫月月猶在。","不知天地间，白日幾时昧。"]', '诗', 'shi', '', NULL, '覽孟東野集 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1654d196-c27a-46d9-a5d1-78253ba3eaa5', '送友人江行', '送友人江行', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["送君若浪水，疊疊愁思起。","夢魂如月明，相送秋江裏。"]', '["送君若浪水，叠叠愁思起。","梦魂如月明，相送秋江裏。"]', '诗', 'shi', '', NULL, '送友人江行 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('208bbede-53a4-444d-8417-4fc0f2d0af3f', '下第有感', '下第有感', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["古人有遺言，天地如掌闊。","我行三十載，青雲路未達。","嘗聞讀書者，所貴免征伐。","誰知失意時，痛於刃傷骨。","身如石上草，根蔕淺難活。","人人皆愛春，我獨愁花發。","如何歸故山，相攜採薇蕨。"]', '["古人有遺言，天地如掌闊。","我行三十載，青云路未達。","嘗闻读书者，所貴免征伐。","誰知失意时，痛於刃傷骨。","身如石上草，根蔕淺难活。","人人皆愛春，我独愁花發。","如何归故山，相携採薇蕨。"]', '诗', 'shi', '', NULL, '下第有感 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d452827-47fe-4b4d-bd2a-69a69dff558c', '論政', '論政', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["賢哉三握髪，爲有天下憂。","孫弘不開閣，丙吉寧問牛。","內政由股肱，外政由諸侯。","股肱政若行，諸侯政自修。","一物不得所，蟻穴滿山丘。","莫言萬木死，不因一葉秋。","朱雲若不直，漢帝終自由。","子嬰一失國，渭水東悠悠。"]', '["賢哉三握髪，爲有天下憂。","孫弘不开閣，丙吉寧问牛。","內政由股肱，外政由諸侯。","股肱政若行，諸侯政自修。","一物不得所，蟻穴满山丘。","莫言万木死，不因一葉秋。","朱云若不直，漢帝終自由。","子嬰一失国，渭水东悠悠。"]', '诗', 'shi', '', NULL, '論政 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62dcae30-df84-4dae-aa84-f8ac164d8404', '戰城南', '戰城南', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["武皇重征伐，戰士輕生死。","朝爭刃上功，暮作泉下鬼。","悲風弔枯骨，明日照荒壘。","千載留長聲，嗚咽城南水。"]', '["武皇重征伐，戰士轻生死。","朝爭刃上功，暮作泉下鬼。","悲风弔枯骨，明日照荒壘。","千載留长声，嗚咽城南水。"]', '诗', 'shi', '', NULL, '戰城南 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1309961c-a099-4ff1-9e5f-53d6544cda43', '贈鄭殷處士', '贈鄭殷处士', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["善琴不得聽，嘉玉不得名。","知音既已死，良匠亦未生。","退居一河湄，山中物景清。","魚沈池水碧，鶴去松枝輕。","長材靡入用，大廈失巨楹。","顏子不得祿，誰謂天道平。"]', '["善琴不得听，嘉玉不得名。","知音既已死，良匠亦未生。","退居一河湄，山中物景清。","鱼沈池水碧，鹤去松枝轻。","长材靡入用，大廈失巨楹。","顏子不得祿，誰謂天道平。"]', '诗', 'shi', '', NULL, '贈鄭殷處士 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0d23a5-cdc0-4faa-ac96-c6ef571db628', '古樂府', '古乐府', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["對酒彈古琴，弦中發新音。","新音不可辨，十指幽怨深。","妾顏不自保，四時如車輪。","不知今夜月，曾照幾時人。","露滴芙蓉香，香銷心亦死。","良時無可留，殘紅謝池水。"]', '["对酒彈古琴，弦中發新音。","新音不可辨，十指幽怨深。","妾顏不自保，四时如车輪。","不知今夜月，曾照幾时人。","露滴芙蓉香，香銷心亦死。","良时無可留，殘紅謝池水。"]', '诗', 'shi', '', NULL, '古樂府 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c13484-b61b-4d20-9b88-83cd27a5cc14', '經安容先生舊居', '經安容先生旧居', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["羽化留遺蹤，千載蹤難沒。","一泉巖下水，幾度換明月。","松老不改柯，龍久皆變骨。","雲雨有歸時，雞犬無還日。","至今青山中，寂寞桃花發。"]', '["羽化留遺蹤，千載蹤难沒。","一泉巖下水，幾度換明月。","松老不改柯，龙久皆变骨。","云雨有归时，雞犬無還日。","至今青山中，寂寞桃花發。"]', '诗', 'shi', '', NULL, '經安容先生舊居 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f562fdd3-4d2e-44eb-a8d0-ebf21fd1883d', '望行人', '望行人', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["登樓恐不高，及高君已遠。","雲行郎即行，雲歸郎不返。","嗟爲樓上人，望望不相近。","若作轍中泥，不放郎車轉。","白日下西山，望盡妾腸斷。"]', '["登楼恐不高，及高君已远。","云行郎即行，云归郎不返。","嗟爲楼上人，望望不相近。","若作轍中泥，不放郎车轉。","白日下西山，望尽妾腸斷。"]', '诗', 'shi', '', NULL, '望行人 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1f17b09-e1e7-4a18-a2b0-6b6da05aef17', '歲豐', '歲豐', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["皇天降豐年，本憂貧士食。","貧士無良疇，安能得稼穡。","工傭輸富家，日落長歎息。","爲供豪者糧，役盡匹夫力。","天地莫施恩，施恩強者得。"]', '["皇天降豐年，本憂貧士食。","貧士無良疇，安能得稼穡。","工傭輸富家，日落长歎息。","爲供豪者糧，役尽匹夫力。","天地莫施恩，施恩強者得。"]', '诗', 'shi', '', NULL, '歲豐 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6feae66-234a-4cb5-a705-53134ae9764f', '金谷園懷古', '金谷园懷古', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["在富莫驕奢，驕奢多自亡。","爲女莫騁容，騁容多自傷。","如何金谷園，鬱鬱椒蘭房。","昨夜綺羅列，今日池館荒。","竹死不變節，花落有餘香。","美人抱義死，千載名猶彰。","嬌歌無遺音，明月留清光。","浮雲易改色，衰草難重芳。","不學韓侯婦，銜冤報宋王。"]', '["在富莫驕奢，驕奢多自亡。","爲女莫騁容，騁容多自傷。","如何金谷园，鬱鬱椒蘭房。","昨夜綺羅列，今日池館荒。","竹死不变節，花落有餘香。","美人抱義死，千載名猶彰。","嬌歌無遺音，明月留清光。","浮云易改色，衰草难重芳。","不学韓侯婦，銜冤報宋王。"]', '诗', 'shi', '', NULL, '金谷園懷古 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc9b7b3-f1e1-4b60-9410-9fbab9071398', '春日有感', '春日有感', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["我心如蘗苦，他見如薺甘。","火未到身者，痛楚難共諳。","但言貧者拙，不言富者貧。","誰知苦寒女，力盡爲桑蠶。"]', '["我心如蘗苦，他见如薺甘。","火未到身者，痛楚难共諳。","但言貧者拙，不言富者貧。","誰知苦寒女，力尽爲桑蠶。"]', '诗', 'shi', '', NULL, '春日有感 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04192c6-beac-455d-b26d-55eae5bfd9fc', '學仙詞', '学仙词', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["上仙傳祕訣，澹薄與無營。","鍊藥□□□，變姓不變形。","三尸既無累，百慮自不生。","是知寸心中，有路通上清。","祖龍好仙術，燒却黃金精。"]', '["上仙傳祕訣，澹薄與無營。","鍊藥□□□，变姓不变形。","三尸既無累，百慮自不生。","是知寸心中，有路通上清。","祖龙好仙術，燒却黄金精。"]', '诗', 'shi', '', NULL, '學仙詞 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bf402e-877e-4b88-99c3-a27068584f49', '妓女', '妓女', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["天若許人登，青山高不止。","地若許人窮，黃泉深無水。","量諸造化情，物成皆有以。","如何上青冥，視之平若砥。","日下騁琅玕，空中無羅綺。","但見勢騰凌，將爲長如此。","炫燿一時間，逡巡九泉裏。","一種爲埃塵，不學墮樓死。"]', '["天若許人登，青山高不止。","地若許人窮，黄泉深無水。","量諸造化情，物成皆有以。","如何上青冥，視之平若砥。","日下騁琅玕，空中無羅綺。","但见勢腾凌，將爲长如此。","炫燿一时间，逡巡九泉裏。","一種爲埃塵，不学墮楼死。"]', '诗', 'shi', '', NULL, '妓女 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bee3b72-de25-49a1-8395-a96eac7d2e09', '寒女行', '寒女行', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["寒女命自薄，生來多賤微。","家貧人不聘，一身無所歸。","養蠶多苦心，繭熟他人絲。","織素徒苦力，素成他人衣。","青樓富家女，纔生便有主。","終日著羅綺，何曾識機杼。","清夜聞歌聲，聽之淚如雨。","他人如何歡，我意又何苦。","所以問皇天，皇天竟無語。"]', '["寒女命自薄，生来多賤微。","家貧人不聘，一身無所归。","養蠶多苦心，繭熟他人絲。","织素徒苦力，素成他人衣。","青楼富家女，纔生便有主。","終日著羅綺，何曾識機杼。","清夜闻歌声，听之泪如雨。","他人如何歡，我意又何苦。","所以问皇天，皇天竟無語。"]', '诗', 'shi', '', NULL, '寒女行 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f18e429-e1b7-4513-aac6-cd8d43696e0d', '覽鏡', '覽镜', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["一照一迴悲，再照顏色衰。","日月自流水，不知身老時。","昨日照紅顏，今朝照白絲。","白絲與紅顏，相去咫尺間。"]', '["一照一迴悲，再照顏色衰。","日月自流水，不知身老时。","昨日照紅顏，今朝照白絲。","白絲與紅顏，相去咫尺间。"]', '诗', 'shi', '', NULL, '覽鏡 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070e07e3-99f1-45ce-936a-474bf1daebac', '輕薄行', '轻薄行', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["薄薄身上衣，輕輕浮雲質。","長安一花開，九陌馬蹄疾。","誰言公子車，不是天上力。"]', '["薄薄身上衣，轻轻浮云質。","长安一花开，九陌马蹄疾。","誰言公子车，不是天上力。"]', '诗', 'shi', '', NULL, '輕薄行 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9853ae44-9a48-4d73-94ca-451094647d5d', '苦別離', '苦別離', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["十五爲君婚，二十入君門。","自從入戶後，見君長出門。","朝看相送人，暮看相送人。","若遣折楊柳，此地樹無根。","願爲陌上土，得作馬蹄塵。","願爲曲木枝，得作雙車輪。","安得太行山，移來君馬前。"]', '["十五爲君婚，二十入君门。","自從入戶後，见君长出门。","朝看相送人，暮看相送人。","若遣折楊柳，此地樹無根。","願爲陌上土，得作马蹄塵。","願爲曲木枝，得作雙车輪。","安得太行山，移来君马前。"]', '诗', 'shi', '', NULL, '苦別離 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed75571-bbbb-4857-bac0-4dd26a09ca66', '覽張騫傳', '覽張騫傳', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["採藥不得根，尋河不得源。","此時虛白首，徒感武皇恩。","桑田未聞改，日月曾幾昏。","仙骨若求得，壟頭無新墳。","不見杜陵草，至今空自繁。"]', '["採藥不得根，尋河不得源。","此时虛白首，徒感武皇恩。","桑田未闻改，日月曾幾昏。","仙骨若求得，壟头無新墳。","不见杜陵草，至今空自繁。"]', '诗', 'shi', '', NULL, '覽張騫傳 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bdf16fb-53cc-4a88-96f5-7cf1d475e3d2', '白頭吟', '白头吟', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["漢家天宇闊，日月不暫閑。","常將古今骨，裨作北邙山。","山高勢已極，猶自凋朱顏。"]', '["漢家天宇闊，日月不暫闲。","常將古今骨，裨作北邙山。","山高勢已極，猶自凋朱顏。"]', '诗', 'shi', '', NULL, '白頭吟 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f027da9c-fdcc-4ca3-a6e3-70448b408a97', '瞽者歎', '瞽者歎', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["我心豈不平，我目自不明。","徒云備雙足，天下何由行。"]', '["我心豈不平，我目自不明。","徒云備雙足，天下何由行。"]', '诗', 'shi', '', NULL, '瞽者歎 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802d7972-70ff-4ee3-a7db-9683813c4f27', '送從弟長安下第南歸覲親', '送從弟长安下第南归覲親', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["白日不得照，戴天如戴盆。","青雲未見路，丹車勞出門。","採薇秦山鎮，養親湘水源。","心中豈不切，其如行路難。","爲文清益峻，爲心直且安。","芝蘭未入用，馨香志獨存。","他門種桃李，猶能蔭子孫。","我家有棠陰，枝葉竟不繁。","心醉豈因酒，愁多徒見萱。","征徒忽告歸，執袂殷勤論。","在鳥終爲鳳，爲魚須化鯤。","富貴豈長守，貧賤寧有根。","丈夫志不大，何以佐乾坤。","晝短疾於箭，早來獻天言。","莫戀蒼梧畔，野煙橫破村。"]', '["白日不得照，戴天如戴盆。","青云未见路，丹车勞出门。","採薇秦山鎮，養親湘水源。","心中豈不切，其如行路难。","爲文清益峻，爲心直且安。","芝蘭未入用，馨香志独存。","他门種桃李，猶能蔭子孫。","我家有棠陰，枝葉竟不繁。","心醉豈因酒，愁多徒见萱。","征徒忽告归，執袂殷勤論。","在鸟終爲鳳，爲鱼須化鯤。","富貴豈长守，貧賤寧有根。","丈夫志不大，何以佐乾坤。","晝短疾於箭，早来獻天言。","莫戀蒼梧畔，野煙橫破村。"]', '诗', 'shi', '', NULL, '送從弟長安下第南歸覲親 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9d3e35-0981-4763-8522-d496d55c5602', '少年行', '少年行', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["丈夫十八九，膽氣欺韓彭。","報讎不用劍，輔國不用兵。","以目爲水鑑，以心作權衡。","願君似堯舜，能使天下平。","何必走馬誇弓矢，然後致得人心爭。"]', '["丈夫十八九，膽氣欺韓彭。","報讎不用劍，輔国不用兵。","以目爲水鑑，以心作權衡。","願君似堯舜，能使天下平。","何必走马誇弓矢，然後致得人心爭。"]', '诗', 'shi', '', NULL, '少年行 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc683d88-62eb-4c1f-90db-40259387809b', '漢宮井', '漢宮井', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["轆轤聲絕離宮靜，班姬幾度照金井。","梧桐老去殘花開，猶似當時美人影。"]', '["轆轤声絕離宮静，班姬幾度照金井。","梧桐老去殘花开，猶似當时美人影。"]', '诗', 'shi', '', NULL, '漢宮井 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b62ad48-49d0-452a-a177-0cd725f293b0', '顯茂樓', '显茂楼', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["秦山渭水尚悠悠，如何草樹迷宮闕。","繁華朱翠盡東流，唯有望樓對明月。"]', '["秦山渭水尚悠悠，如何草樹迷宮闕。","繁华朱翠尽东流，唯有望楼对明月。"]', '诗', 'shi', '', NULL, '顯茂樓 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d424da5f-29b5-49ca-9e00-289b629d6c20', '紫閣峯', '紫閣峯', '2c4e290a-207e-496d-b0b0-277bbeaddf13', '唐', '["壯國山河倚空碧，迥拔煙霞侵太白。","綠崖下視千萬尋，青天只據百餘尺。"]', '["壯国山河倚空碧，迥拔煙霞侵太白。","綠崖下視千万尋，青天只據百餘尺。"]', '诗', 'shi', '', NULL, '紫閣峯 邵謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ffa20a5-ecb8-4df9-8fa0-f51f304f518a', '送李員外頻之建州', '送李員外頻之建州', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["句踐江頭月，客星臺畔松。","爲郎久不見，出守暫相逢。","鳥泊牽灘索，花空押號鐘。","遠人思化切，休上武夷峰。"]', '["句踐江头月，客星台畔松。","爲郎久不见，出守暫相逢。","鸟泊牽灘索，花空押號鐘。","远人思化切，休上武夷峰。"]', '诗', 'shi', '', NULL, '送李員外頻之建州 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7dc2bf9-c4d3-4a9c-a07c-c2e91e4afcb1', '送許棠先輩歸宣州', '送許棠先輩归宣州', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["髪枯窮律韻，字字合塤篪。","日月所到處，姓名無不知。","鶯啼謝守壘，苔老謫仙碑。","詩道喪來久，東歸爲弔之。"]', '["髪枯窮律韻，字字合塤篪。","日月所到处，姓名無不知。","鶯啼謝守壘，苔老謫仙碑。","诗道喪来久，东归爲弔之。"]', '诗', 'shi', '', NULL, '送許棠先輩歸宣州 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d8af169-8b32-469c-8760-12e25f14b914', '窮冬太學', '窮冬太学', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["投跡依槐館，荒亭草合時。","雪深鳶嘯急，薪濕鼎吟遲。","默坐同誰話，非僧不我知。","匡廬瀑布畔，何日副心期。"]', '["投跡依槐館，荒亭草合时。","雪深鳶嘯急，薪濕鼎吟遲。","默坐同誰話，非僧不我知。","匡廬瀑布畔，何日副心期。"]', '诗', 'shi', '', NULL, '窮冬太學 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b0ab99c-6b1d-44dd-8614-11e6450e9efa', '陪鄭諴郎中假日省中寓直', '陪鄭諴郎中假日省中寓直', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["憲廳名最重，假日許從容。","牀滿諸司印，庭高五粒松。","井尋芸吏汲，茶拆岳僧封。","鳥度簾旌暮，猶吟隔苑鐘。"]', '["憲廳名最重，假日許從容。","牀满諸司印，庭高五粒松。","井尋芸吏汲，茶拆岳僧封。","鸟度簾旌暮，猶吟隔苑鐘。"]', '诗', 'shi', '', NULL, '陪鄭諴郎中假日省中寓直 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a956c5ba-b15f-44f0-b0d2-8f03a37a0f3c', '送謝石先輩歸宣州', '送謝石先輩归宣州', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["名隨春色遠，湖外已先知。","花盡方辭醉，鶯殘是放時。","天寒千尺嶽，頷白半聯詩。","笋蕨猶堪採，榮歸及養期。"]', '["名隨春色远，湖外已先知。","花尽方辞醉，鶯殘是放时。","天寒千尺嶽，頷白半聯诗。","笋蕨猶堪採，榮归及養期。"]', '诗', 'shi', '', NULL, '送謝石先輩歸宣州 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9116a4f5-6a50-4ade-a8ff-547f408fec90', '下第寄歐陽瓚', '下第寄歐陽瓚', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["詩人道僻命多奇，更值干戈亂起時。","莫作江寧王少府，一生吟苦竟誰知。"]', '["诗人道僻命多奇，更值干戈亂起时。","莫作江寧王少府，一生吟苦竟誰知。"]', '诗', 'shi', '', NULL, '下第寄歐陽瓚 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f518a6-d254-42c3-a574-53ae65c90785', '寄何紹餘', '寄何紹餘', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["雁過君猶未入城，清賢門下舊知名。","風波凍馬遙逢見，革橐飢僮尚挈行。","住在閑坊無轍跡，別來何寺有泉聲。","芙蓉苑北曲江岸，期看終南新雪晴。"]', '["雁過君猶未入城，清賢门下旧知名。","风波凍马遙逢见，革橐飢僮尚挈行。","住在闲坊無轍跡，別来何寺有泉声。","芙蓉苑北曲江岸，期看終南新雪晴。"]', '诗', 'shi', '', NULL, '寄何紹餘 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('718a0c14-5339-4204-b988-5771a83d7296', '送人宰浦城', '送人宰浦城', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["東南猶阻寇，梨嶺更誰登。","作宰應無俸，歸船必有僧。","灘平眠獺石，燒斷飲猨藤。","歲盡校殊最，方當見異能。"]', '["东南猶阻寇，梨嶺更誰登。","作宰應無俸，归船必有僧。","灘平眠獺石，燒斷饮猨藤。","歲尽校殊最，方當见異能。"]', '诗', 'shi', '', NULL, '送人宰浦城 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ade34684-60aa-4bb2-9499-09beebead399', '省試臘後望春宮', '省試臘後望春宮', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["皇都初度臘，鳳輦出深宮。","高凭樓臺上，遙瞻灞滻中。","仗凝霜彩白，袍映日華紅。","柳眼方開凍，鶯聲漸轉風。","御溝穿斷靄，驪岫照斜空。","時見宸游興，因觀稼穡功。"]', '["皇都初度臘，鳳輦出深宮。","高凭楼台上，遙瞻灞滻中。","仗凝霜彩白，袍映日华紅。","柳眼方开凍，鶯声漸轉风。","御溝穿斷靄，驪岫照斜空。","时见宸游兴，因观稼穡功。"]', '诗', 'shi', '', NULL, '省試臘後望春宮 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbe085c-055c-403c-a4d5-926e6e2fe7ad', '寄省中知己', '寄省中知己', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["門掩清曹晚，靜將烏府鄰。","花開封印早，雪下典衣頻。","怪木風吹閣，廢巢時落薪。","每憐吾道苦，長說向同人。"]', '["门掩清曹晚，静將烏府鄰。","花开封印早，雪下典衣頻。","怪木风吹閣，廢巢时落薪。","每怜吾道苦，长说向同人。"]', '诗', 'shi', '', NULL, '寄省中知己 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4c6c56-7bf2-4f58-930e-64824f8e4363', '朱坡', '朱坡', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["朱坡坡上望，不似在秦京。","漸覺溪山秀，更高魚鳥情。","夜吟禪子室，曉爨獵人鐺。","恃此偷佳賞，九衢蜩未鳴。"]', '["朱坡坡上望，不似在秦京。","漸覺溪山秀，更高鱼鸟情。","夜吟禪子室，晓爨獵人鐺。","恃此偷佳賞，九衢蜩未鳴。"]', '诗', 'shi', '', NULL, '朱坡 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ce3cca-3da3-43a0-8b15-01d0051cdb1a', '酬陳樵見寄', '酬陳樵见寄', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["失意閑眠起更遲，又將羈薄謝深知。","囊書旋入酒家盡，紗帽長依僧壁垂。","待月句新遭鬼哭，尋山貌古被猨窺。","元和才子多如此，除却清吟何所爲。"]', '["失意闲眠起更遲，又將羈薄謝深知。","囊书旋入酒家尽，紗帽长依僧壁垂。","待月句新遭鬼哭，尋山貌古被猨窺。","元和才子多如此，除却清吟何所爲。"]', '诗', 'shi', '', NULL, '酬陳樵見寄 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ea2b0d-4345-449a-8b12-bbe26150d113', '華清宮', '华清宮', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["殿角鐘殘立宿鴉，朝元歸駕望無涯。","香泉空浸宮前草，未到春時爭發花。"]', '["殿角鐘殘立宿鴉，朝元归駕望無涯。","香泉空浸宮前草，未到春时爭發花。"]', '诗', 'shi', '', NULL, '華清宮 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4093339-f20d-4607-a48c-7789623d4899', '終南山', '終南山', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["標奇聳峻壯長安，影入千門萬戶寒。","徒自倚天生氣色，塵中誰爲舉頭看。"]', '["標奇聳峻壯长安，影入千门万戶寒。","徒自倚天生氣色，塵中誰爲舉头看。"]', '诗', 'shi', '', NULL, '終南山 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103dad37-ff58-4d15-be02-5a944406f7a8', '歌風臺', '歌风台', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["蒿棘空存百尺基，酒酣曾唱大風詞。","莫言馬上得天下，自古英雄盡解詩。"]', '["蒿棘空存百尺基，酒酣曾唱大风词。","莫言马上得天下，自古英雄尽解诗。"]', '诗', 'shi', '', NULL, '歌風臺 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c79ec9c-409e-41fc-aca7-da6086bed142', '送人歸日東', '送人归日东', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["滄溟西畔望，一望一心摧。","地即同正朔，天教阻往來。","波翻夜作電，鯨吼晝爲雷。","門外人葠徑，到時花幾開。"]', '["滄溟西畔望，一望一心摧。","地即同正朔，天教阻往来。","波翻夜作電，鯨吼晝爲雷。","门外人葠徑，到时花幾开。"]', '诗', 'shi', '', NULL, '送人歸日東 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a111c0-a531-456b-85b7-1779f65ba90d', '寓興', '寓兴', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["西母一杯酒，空言浩劫春。","英雄歸厚土，日月照閑人。","衰草珠璣塚，冷灰龍鳳身。","茂陵驪岫晚，過者暗傷神。"]', '["西母一杯酒，空言浩劫春。","英雄归厚土，日月照闲人。","衰草珠璣塚，冷灰龙鳳身。","茂陵驪岫晚，過者暗傷神。"]', '诗', 'shi', '', NULL, '寓興 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611d75ff-fcb9-4d4e-8826-939d3329ef67', '少年行', '少年行', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["柳煙侵御道，門映夾城開。","白日莫空過，青春不再來。","報讎衝雪去，乘醉臂鷹迴。","看取歌鐘地，殘陽滿壞臺。"]', '["柳煙侵御道，门映夾城开。","白日莫空過，青春不再来。","報讎衝雪去，乘醉臂鷹迴。","看取歌鐘地，殘陽满壞台。"]', '诗', 'shi', '', NULL, '少年行 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f217cf4f-841a-4ba9-8201-dc2500548215', '塞上還荅友人', '塞上還荅友人', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["無端遊絕塞，歸鬢已蒼然。","戎羯圍中過，風沙馬上眠。","草衰頻過燒，耳冷不聞蟬。","從此甘貧坐，休言更到邊。"]', '["無端游絕塞，归鬢已蒼然。","戎羯圍中過，风沙马上眠。","草衰頻過燒，耳冷不闻蟬。","從此甘貧坐，休言更到邊。"]', '诗', 'shi', '', NULL, '塞上還荅友人 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcaccdaa-a09c-44da-9f57-00753b021e3a', '哭棲白供奉', '哭棲白供奉', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["侍輦才難得，三朝有上人。","琢詩方到骨，至死不離貧。","風帳孤螢入，霜堦積葉頻。","夕陽門半掩，過此亦無因。"]', '["侍輦才难得，三朝有上人。","琢诗方到骨，至死不離貧。","风帳孤螢入，霜堦積葉頻。","夕陽门半掩，過此亦無因。"]', '诗', 'shi', '', NULL, '哭棲白供奉 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccaefadf-cda0-432d-9a38-3ba3e44e4cca', '送昇道靖恭相公分司', '送昇道靖恭相公分司', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["東風時不遇，果見致君難。","海岳影猶動，鵾鵬勢未安。","星沈關鎖冷，雞唱驛燈殘。","誰似二賓客，門閑嵩洛寒。"]', '["东风时不遇，果见致君难。","海岳影猶动，鵾鵬勢未安。","星沈关鎖冷，雞唱驛灯殘。","誰似二賓客，门闲嵩洛寒。"]', '诗', 'shi', '', NULL, '送昇道靖恭相公分司 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a21f00-d533-4410-8d23-ac48b5db9486', '關下早行', '关下早行', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["軋軋推危轍，聽雞獨早行。","風吹宿靄散，月照華山明。","白首東西客，黃河晝夜清。","相逢皆有事，唯我是閑情。"]', '["軋軋推危轍，听雞独早行。","风吹宿靄散，月照华山明。","白首东西客，黄河晝夜清。","相逢皆有事，唯我是闲情。"]', '诗', 'shi', '', NULL, '關下早行 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec1af9f-2d78-4e9a-ae5d-9f2013c4974b', '曲江', '曲江', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["曲江初碧草初青，萬轂千蹄匝岸行。","傾國妖姬雲鬢重，薄徒公子雪衫輕。","瓊鐫狒𤝞遶觥舞，金蹙辟邪拏撥鳴。","柳絮杏花留不得，隨風處處逐歌聲。"]', '["曲江初碧草初青，万轂千蹄匝岸行。","傾国妖姬云鬢重，薄徒公子雪衫轻。","瓊鐫狒𤝞遶觥舞，金蹙辟邪拏撥鳴。","柳絮杏花留不得，隨风处处逐歌声。"]', '诗', 'shi', '', NULL, '曲江 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c1da97-44d4-4e6b-9d8f-dcda611214ce', '長安遣懷', '长安遣懷', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["醉下高樓醒復登，任從浮薄笑才能。","青龍寺裏三門上，立爲南山不爲僧。"]', '["醉下高楼醒复登，任從浮薄笑才能。","青龙寺裏三门上，立爲南山不爲僧。"]', '诗', 'shi', '', NULL, '長安遣懷 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f222e8-59bf-4229-b44e-125b9b779a3b', '送僧遊太白峰', '送僧游太白峰', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["雲深遊太白，莫惜遍探奇。","頂上多靈跡，塵中少客知。","懸崖倚凍瀑，飛狖過孤枝。","出定更何事，相逢必有詩。"]', '["云深游太白，莫惜遍探奇。","頂上多靈跡，塵中少客知。","懸崖倚凍瀑，飞狖過孤枝。","出定更何事，相逢必有诗。"]', '诗', 'shi', '', NULL, '送僧遊太白峰 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d4a5faf-b503-4732-aff6-90a18c476277', '哭造微禪師', '哭造微禪師', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["神遷不火葬，新塔露疎檉。","是物皆磨滅，唯師出死生。","虛堂散釣叟，怪木哭山精。","林下路長在，無因更此行。"]', '["神遷不火葬，新塔露疎檉。","是物皆磨滅，唯師出死生。","虛堂散釣叟，怪木哭山精。","林下路长在，無因更此行。"]', '诗', 'shi', '', NULL, '哭造微禪師 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4da1855-f3cb-4bc9-a2e7-a451c6eb91a4', '獻同年孔郎中', '獻同年孔郎中', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["炊瓊爇桂帝關居，賣盡寒衣典盡書。","驅馬每尋霜影裏，到門常在鼓聲初。","蟾枝交彩清蘭署，鸞珮排光映玉除。","一顧深恩身未殺，爭期皎日負吹噓。"]', '["炊瓊爇桂帝关居，賣尽寒衣典尽书。","驱马每尋霜影裏，到门常在鼓声初。","蟾枝交彩清蘭署，鸾珮排光映玉除。","一顧深恩身未殺，爭期皎日負吹噓。"]', '诗', 'shi', '', NULL, '獻同年孔郎中 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865e96b8-d12f-4bb6-805f-f025d0cc6b34', '聞雁', '闻雁', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["接影橫空背雪飛，聲聲寒出玉關遲。","上陽宮裏三千夢，月冷風清聞過時。"]', '["接影橫空背雪飞，声声寒出玉关遲。","上陽宮裏三千梦，月冷风清闻過时。"]', '诗', 'shi', '', NULL, '聞雁 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec595bea-428b-49fb-b0e4-cd28acf698ba', '送惠補闕', '送惠補闕', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["詔下搜巖野，高人入竹林。","長因抗疏日，便作去官心。","清俸供僧盡，滄洲寄跡深。","東門有歸路，徒自棄華簪。"]', '["詔下搜巖野，高人入竹林。","长因抗疏日，便作去官心。","清俸供僧尽，滄洲寄跡深。","东门有归路，徒自棄华簪。"]', '诗', 'shi', '', NULL, '送惠補闕 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b95b8f-fb3f-4da6-970a-2899304c6646', '和友人賊後', '和友人賊後', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["帶號乞兵急，英雄陷賊圍。","江山猶未靜，魚鳥欲何歸。","城露桑榆盡，時平老幼稀。","書從戰後得，讀徹血盈衣。"]', '["带號乞兵急，英雄陷賊圍。","江山猶未静，鱼鸟欲何归。","城露桑榆尽，时平老幼稀。","书從戰後得，读徹血盈衣。"]', '诗', 'shi', '', NULL, '和友人賊後 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0771bdd1-a9cc-4dd6-b587-f7bbb40e8386', '長安即事', '长安即事', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["暝鼓纔終復曉雞，九門何計出沈迷。","樵童亂打金吾鼓，豪馬爭奔丞相隄。","翡翠鬟欹釵上燕，麒麟衫束海中犀。","須知不是詩人事，空憶泉聲菊畔畦。"]', '["暝鼓纔終复晓雞，九门何計出沈迷。","樵童亂打金吾鼓，豪马爭奔丞相隄。","翡翠鬟欹釵上燕，麒麟衫束海中犀。","須知不是诗人事，空憶泉声菊畔畦。"]', '诗', 'shi', '', NULL, '長安即事 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aea74ae-c174-4462-9bcc-5c764449c5b4', '和周繇校書先輩省中寓直', '和周繇校书先輩省中寓直', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["古木重門掩，幽深秖欠溪。","此中真吏隱，何必更巖棲。","名姓鐫幢記，經書逐庫題。","字隨飛蠹缺，堦與落星齊。","伴直僧談靜，侵霜蛩韻低。","粘塵賀草沒，剝粉薛禽迷。","衰蘚牆千堵，微陽菊半畦。","鼓殘鴉去北，漏在月沈西。","每憶終南雪，幾登雲閣梯。","時因搜句次，那惜一招攜。"]', '["古木重门掩，幽深秖欠溪。","此中真吏隐，何必更巖棲。","名姓鐫幢記，經书逐庫題。","字隨飞蠹缺，堦與落星齊。","伴直僧談静，侵霜蛩韻低。","粘塵賀草沒，剝粉薛禽迷。","衰蘚牆千堵，微陽菊半畦。","鼓殘鴉去北，漏在月沈西。","每憶終南雪，幾登云閣梯。","时因搜句次，那惜一招携。"]', '诗', 'shi', '', NULL, '和周繇校書先輩省中寓直 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('438b2878-c2d7-4309-99a0-cae394614d2c', '苦雨', '苦雨', 'b18e7b3a-6583-4996-a349-708fc2394545', '唐', '["霪霖翳日月，窮巷變溝坑。","驟灑纖枝折，奔傾壞堵平。","蒙[簦]來客絕，躍甃噪蛙獰。","敗屐陰苔積，摧簷濕菌生。","斜飛穿裂瓦，迸落打空鐺。","葉底遲歸蝶，林中滯出鶯。","潤侵書缝黑，冷浸鬢絲明。","牖暗參差影，堦寒斷續聲。","尺薪功比桂，寸粒價高瓊。","遙想管弦裏，無因識此情。"]', '["霪霖翳日月，窮巷变溝坑。","驟灑纖枝折，奔傾壞堵平。","蒙[簦]来客絕，躍甃噪蛙獰。","敗屐陰苔積，摧簷濕菌生。","斜飞穿裂瓦，迸落打空鐺。","葉底遲归蝶，林中滯出鶯。","潤侵书缝黑，冷浸鬢絲明。","牖暗參差影，堦寒斷續声。","尺薪功比桂，寸粒價高瓊。","遙想管弦裏，無因識此情。"]', '诗', 'shi', '', NULL, '苦雨 林寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9186af7-c419-431a-8bcb-612b7cc65031', '翰林作', '翰林作', '2dbd9094-ddcd-41cd-a8a7-406af65f7380', '唐', '["曾是江波垂釣人，自憐深厭九衢塵。","浮生漸老年隨水，往事曾聞淚滿巾。","已覺遠天秋色動，不堪閑夜雨聲頻。","多慚不是相如筆，虛直金鑾接侍臣。"]', '["曾是江波垂釣人，自怜深厭九衢塵。","浮生漸老年隨水，往事曾闻泪满巾。","已覺远天秋色动，不堪闲夜雨声頻。","多慚不是相如笔，虛直金鑾接侍臣。"]', '诗', 'shi', '', NULL, '翰林作 劉鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4af199-f2aa-4f3d-a575-3b7171814288', '待漏院吟', '待漏院吟', '2dbd9094-ddcd-41cd-a8a7-406af65f7380', '唐', '["玉堂簾外獨遲遲，明月初沈勘契時。","閑聽景陽鐘盡後，兩鶯飛上萬年枝。"]', '["玉堂簾外独遲遲，明月初沈勘契时。","闲听景陽鐘尽後，兩鶯飞上万年枝。"]', '诗', 'shi', '', NULL, '待漏院吟 劉鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1a33ed-9e0d-488d-8927-313878fe9d9d', '慧山寺肄業送懷坦上人', '慧山寺肄業送懷坦上人', 'aaa6452d-cbc0-43ab-9ac4-f94a064bb37d', '唐', '["流水何山分，浮雲空中遇。","我生無根株，聚散亦難固。","憶昨鬬龍春，巖棲侶高步。","清懷去羈束，幽境無滓污。","日落九峰明，煙生萬華暮。","茲歡未云隔，前笑倏已故。","四時難信留，百草換霜露。","離襟一成解，悵抱將何諭。","驚泉有餘哀，永日誰與度。","緬思孤帆影，再往重江路。","去去忽悽悲，因風暫回顧。"]', '["流水何山分，浮云空中遇。","我生無根株，聚散亦难固。","憶昨鬬龙春，巖棲侶高步。","清懷去羈束，幽境無滓污。","日落九峰明，煙生万华暮。","茲歡未云隔，前笑倏已故。","四时难信留，百草換霜露。","離襟一成解，悵抱將何諭。","驚泉有餘哀，永日誰與度。","緬思孤帆影，再往重江路。","去去忽悽悲，因风暫回顧。"]', '诗', 'shi', '', NULL, '慧山寺肄業送懷坦上人 李騭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ac9515-a376-42d8-b41a-f1283e7a1bb0', '讀惠山若冰師集因題故院三首 一', '读惠山若冰師集因題故院三首 一', 'aaa6452d-cbc0-43ab-9ac4-f94a064bb37d', '唐', '["五天何處望，心念起皆知。","化塔留今日，泉鳴自昔時。","古苔生石靜，秋草滿山悲。","莫道聲容遠，長歌白雪詞。"]', '["五天何处望，心念起皆知。","化塔留今日，泉鳴自昔时。","古苔生石静，秋草满山悲。","莫道声容远，长歌白雪词。"]', '诗', 'shi', '', NULL, '讀惠山若冰師集因題故院三首 一 李騭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c837b4-c856-4d17-a015-abab1d78c9c4', '讀惠山若冰師集因題故院三首 二', '读惠山若冰師集因題故院三首 二', 'aaa6452d-cbc0-43ab-9ac4-f94a064bb37d', '唐', '["高懷逢異境，佳句想吟頻。","月冷松溪夜，煙濃草寺春。","浮雲將世遠，清聽與名新。","不見開巖日，空爲拜影人。"]', '["高懷逢異境，佳句想吟頻。","月冷松溪夜，煙濃草寺春。","浮云將世远，清听與名新。","不见开巖日，空爲拜影人。"]', '诗', 'shi', '', NULL, '讀惠山若冰師集因題故院三首 二 李騭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be60f00-61f2-435d-948c-6584f9ca0899', '讀惠山若冰師集因題故院三首 三', '读惠山若冰師集因題故院三首 三', 'aaa6452d-cbc0-43ab-9ac4-f94a064bb37d', '唐', '["景物搜求歇，山雲放縱飛。","樹寒煙鶴去，池靜水龍歸。","暗榻塵飄滿，陰簷月到稀。","何年燈焰盡，風動影堂扉。"]', '["景物搜求歇，山云放縱飞。","樹寒煙鹤去，池静水龙归。","暗榻塵飄满，陰簷月到稀。","何年灯焰尽，风动影堂扉。"]', '诗', 'shi', '', NULL, '讀惠山若冰師集因題故院三首 三 李騭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06503ff8-f8e3-4d08-b206-245215944b05', '自惠山至吳下寄酬南徐從事', '自惠山至吳下寄酬南徐從事', 'aaa6452d-cbc0-43ab-9ac4-f94a064bb37d', '唐', '["不接芳晨游，獨此長洲苑。","風顏一成阻，翰墨勞空返。","悠悠汀渚長，杳杳蘋花晚。","如何西府歡，尚念東吳遠。","瑤音動清韻，蘭思芬盈畹。","猶及九峰春，歸吟白雲巘。"]', '["不接芳晨游，独此长洲苑。","风顏一成阻，翰墨勞空返。","悠悠汀渚长，杳杳蘋花晚。","如何西府歡，尚念东吳远。","瑤音动清韻，蘭思芬盈畹。","猶及九峰春，归吟白云巘。"]', '诗', 'shi', '', NULL, '自惠山至吳下寄酬南徐從事 李騭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc450c2f-58f4-4773-a6c1-f80faddd3b2c', '中秋夜戲酬顧道流', '中秋夜戲酬顧道流', 'fd4e149e-8e2e-4ecd-8007-24cba0b7c043', '唐', '["不那此身偏愛月，等閑看月即更深。","仙翁每被嫦娥使，一度逢圓一度吟。"]', '["不那此身偏愛月，等闲看月即更深。","仙翁每被嫦娥使，一度逢圓一度吟。"]', '诗', 'shi', '', NULL, '中秋夜戲酬顧道流 孫蜀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78dfa3e8-2ba4-41e6-9e71-e25c3b71460d', '詠燕上主司鄭愚', '詠燕上主司鄭愚', '71da8614-6b40-402e-93c8-66fb3c173b14', '唐', '["翩翩雙燕畫堂開，送古迎今幾萬回。","長向春秋社前後，爲誰歸去爲誰來。"]', '["翩翩雙燕畫堂开，送古迎今幾万回。","长向春秋社前後，爲誰归去爲誰来。"]', '诗', 'shi', '', NULL, '詠燕上主司鄭愚 歐陽澥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f892662-79f9-444f-9f1c-8e862828e49d', '句', '句', '71da8614-6b40-402e-93c8-66fb3c173b14', '唐', '["黃菊離家十四年，離家已是夢松年。","落日望鄉處，何人知客情。"]', '["黄菊離家十四年，離家已是梦松年。","落日望乡处，何人知客情。"]', '诗', 'shi', '', NULL, '句 歐陽澥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44ded41-fdeb-4051-a798-7da94316110f', '自詠豆花', '自詠豆花', '82f561f9-3edc-4a6c-862c-a4273f36bb9c', '唐', '["玳瑁應難比，斑犀定不加。","天嫌未端正，滿面與妝花。"]', '["玳瑁應难比，斑犀定不加。","天嫌未端正，满面與妝花。"]', '诗', 'shi', '', NULL, '自詠豆花 陳黯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8416388e-8934-4d9f-b5c3-d2f1b7e8b6ac', '雪詩', '雪诗', '2965da63-c004-4441-951d-324aaf46e36c', '唐', '["長安大雪天，鳥雀難相覓。","其中豪貴家，搗椒泥四壁。","到處爇紅爐，周迴下羅冪。","暖手調金絲，蘸甲斟瓊液。","醉唱玉塵飛，困融香汗滴。","豈知飢寒人，手脚生皴劈。"]', '["长安大雪天，鸟雀难相覓。","其中豪貴家，捣椒泥四壁。","到处爇紅爐，周迴下羅冪。","暖手調金絲，蘸甲斟瓊液。","醉唱玉塵飞，困融香汗滴。","豈知飢寒人，手脚生皴劈。"]', '诗', 'shi', '', NULL, '雪詩 張孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494ab0dc-0e87-4fae-a585-bde3c845d165', '句', '句', '2965da63-c004-4441-951d-324aaf46e36c', '唐', '["著牙賣朱紫，斷錢賒舉選。","華山秀作英雄骨，黃河瀉出縱橫才。","夢破青霄春，煙霞無去塵。","若誇郭璞五色筆，江淹却是尋常人。"]', '["著牙賣朱紫，斷錢賒舉選。","华山秀作英雄骨，黄河瀉出縱橫才。","梦破青霄春，煙霞無去塵。","若誇郭璞五色笔，江淹却是尋常人。"]', '诗', 'shi', '', NULL, '句 張孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a401af4-52df-4688-a397-e95c778272d1', '贈妓僊哥', '贈妓僊哥', '5ea9840c-4ab8-408d-ac8c-eb6b58c1a013', '唐', '["嚴吹如何下太清，玉肌無疹六銖輕。","自知不是流霞酌，願聽雲和瑟一聲。"]', '["嚴吹如何下太清，玉肌無疹六銖轻。","自知不是流霞酌，願听云和瑟一声。"]', '诗', 'shi', '', NULL, '贈妓僊哥 鄭仁表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97914716-3075-4de2-b608-8a304f3b7367', '贈妓命洛真', '贈妓命洛真', '5ea9840c-4ab8-408d-ac8c-eb6b58c1a013', '唐', '["巧製新章拍拍新，金罍巡舉助精神。","時時欲得橫波眄，又怕回籌錯指人。"]', '["巧製新章拍拍新，金罍巡舉助精神。","时时欲得橫波眄，又怕回籌錯指人。"]', '诗', 'shi', '', NULL, '贈妓命洛真 鄭仁表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386ed35c-92f8-4adb-bbf7-1e864f2e9ac4', '句', '句', '5ea9840c-4ab8-408d-ac8c-eb6b58c1a013', '唐', '["文章世上爭開路，閥閱山東拄破天。"]', '["文章世上爭开路，閥閱山东拄破天。"]', '诗', 'shi', '', NULL, '句 鄭仁表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba529c1-39a6-4eb7-8906-6c0068d417dd', '杜甫同谷茅茨', '杜甫同谷茅茨', '11158ae1-a9e0-4c93-9223-b528767f5406', '唐', '["工部棲遲後，鄰家大半無。","青羌迷道路，白社寄杯盂。","大雅何人繼，全生此地孤。","孤雲飛鳥什，空勒舊山隅。"]', '["工部棲遲後，鄰家大半無。","青羌迷道路，白社寄杯盂。","大雅何人繼，全生此地孤。","孤云飞鸟什，空勒旧山隅。"]', '诗', 'shi', '', NULL, '杜甫同谷茅茨 趙鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9937fb-3212-4c9c-b56c-7b6dc3a4c2e3', '栗亭', '栗亭', '11158ae1-a9e0-4c93-9223-b528767f5406', '唐', '["杜甫栗亭詩，詩人多在口。","悠悠二甲子，題紀今何有。"]', '["杜甫栗亭诗，诗人多在口。","悠悠二甲子，題紀今何有。"]', '诗', 'shi', '', NULL, '栗亭 趙鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f46697d-ad3e-4929-8465-a99e611b5538', '泥功山', '泥功山', '11158ae1-a9e0-4c93-9223-b528767f5406', '唐', '["立石泥功狀，天然詭怪形。","未嘗私禍福，終不費丹青。"]', '["立石泥功狀，天然詭怪形。","未嘗私禍福，終不費丹青。"]', '诗', 'shi', '', NULL, '泥功山 趙鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a87491-eaca-4717-a459-e4a1ace84f35', '昆明池織女石', '昆明池织女石', 'b9992e46-4a02-45a6-882f-d676daca0656', '唐', '["一片昆明石，千秋織女名。","見人虛脈脈，臨水更盈盈。","苔作輕衣色，波爲促杼聲。","岸雲連鬢濕，沙月對眉生。","有臉蓮同笑，無心鳥不驚。","還如朝鏡裏，形影兩分明。"]', '["一片昆明石，千秋织女名。","见人虛脈脈，臨水更盈盈。","苔作轻衣色，波爲促杼声。","岸云連鬢濕，沙月对眉生。","有臉蓮同笑，無心鸟不驚。","還如朝镜裏，形影兩分明。"]', '诗', 'shi', '', NULL, '昆明池織女石 童翰卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15cf52d4-354c-40a0-98fd-bc5597aba439', '絕句', '絕句', 'b9992e46-4a02-45a6-882f-d676daca0656', '唐', '["大朴逐物盡，哀我天地功。","爭得榮辱心，灑然歸西風。"]', '["大朴逐物尽，哀我天地功。","爭得榮辱心，灑然归西风。"]', '诗', 'shi', '', NULL, '絕句 童翰卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a248d6d9-a8c1-4dd3-9a07-f50a107c3239', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["爣爣皎日，歘麗於天。","厥明御舒，如王出焉。"]', '["爣爣皎日，歘丽於天。","厥明御舒，如王出焉。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60722288-d085-4aee-814a-e741f9c22772', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["爣爣皎日，歘入於地。","厥晦厥貞，如王入焉。"]', '["爣爣皎日，歘入於地。","厥晦厥貞，如王入焉。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1c2256-2fe9-49b3-8e11-c583b7d252b0', '補周禮九夏系文   三', '補周禮九夏系文   三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["出有龍旂，入有珩佩。","勿驅勿馳，惟慎惟戒。"]', '["出有龙旂，入有珩佩。","勿驱勿驰，惟慎惟戒。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ed3248-5872-4541-b94d-877aa3da2af5', '補周禮九夏系文   四', '補周禮九夏系文   四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["出有嘉謀，入有內則。","繄彼臣庶，欽王之式。"]', '["出有嘉謀，入有內則。","繄彼臣庶，欽王之式。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e97062-1a57-424a-982f-4f0bb94f926f', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["愔愔清廟，儀儀象服。","我尸出矣，迎神之穀。"]', '["愔愔清廟，儀儀象服。","我尸出矣，迎神之穀。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dedc2b1f-306e-40db-a328-d53d3f72b958', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["杳杳陰竹，坎坎路鼓。","我尸入矣，得神之祜。"]', '["杳杳陰竹，坎坎路鼓。","我尸入矣，得神之祜。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be53a076-db9e-4ff1-997b-74a10b2a571f', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["有鬱其鬯，有儼其彝。","九變未作，全乘來之。"]', '["有鬱其鬯，有儼其彝。","九变未作，全乘来之。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8477211-b077-420f-9d1b-6a798c184fc0', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["既醑既酢，爰朄爰舞。","象物既降，全乘之去。"]', '["既醑既酢，爰朄爰舞。","象物既降，全乘之去。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8563f2-8e19-4c68-904a-faec1189d8f3', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["麟之儀儀，不縶不維。","樂德而至，如賓之嬉。"]', '["麟之儀儀，不縶不維。","乐德而至，如賓之嬉。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb6f647-2913-47c8-a4ca-c1b4655d67d1', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鳳之愉愉，不篝不笯。","樂德而至，如賓之娛。"]', '["鳳之愉愉，不篝不笯。","乐德而至，如賓之娛。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa65a5d-2f65-4250-a131-b133c9c8d5b9', '補周禮九夏系文   三', '補周禮九夏系文   三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["自筐及筥，我有牢醑。","自筐及篚，我有貨幣。"]', '["自筐及筥，我有牢醑。","自筐及篚，我有貨幣。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f648de04-10ab-4307-a708-87f098c74c1c', '補周禮九夏系文   四', '補周禮九夏系文   四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["我牢不愆，我貨不匱。","碩碩其才，有樂而止。"]', '["我牢不愆，我貨不匱。","碩碩其才，有乐而止。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a98326-3dc3-4d4b-af7b-a95d56738c47', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["王有虎臣，錫之鈇鉞。","征彼不憓，一撲而滅。"]', '["王有虎臣，錫之鈇鉞。","征彼不憓，一撲而滅。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bbf336-5400-428e-b57f-5693b9ee82be', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["王有虎臣，錫之圭瓚。","征彼不享，一烘而泮。"]', '["王有虎臣，錫之圭瓚。","征彼不享，一烘而泮。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3509bec-0b32-40c2-aaac-48c16d1450cc', '補周禮九夏系文   三', '補周禮九夏系文   三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["王有掌訝，遉爾疆理。","王有掌客，饋爾饔餼。"]', '["王有掌訝，遉爾疆理。","王有掌客，饋爾饔餼。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c421e0cd-a6d8-44e5-bdc7-41a384859b1c', '補周禮九夏系文   四', '補周禮九夏系文   四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何以樂之，金石九奏。","何以錫之，龍旂九旒。"]', '["何以乐之，金石九奏。","何以錫之，龙旂九旒。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6259214e-c9ab-4baa-9a47-d45f210e2d25', '補周禮九夏系文', '補周禮九夏系文', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["𤫩𤫩衡笄，翬衣褕翟。","自內而祭，爲君之則。"]', '["𤫩𤫩衡笄，翬衣褕翟。","自內而祭，爲君之則。"]', '诗', 'shi', '', NULL, '補周禮九夏系文 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7801ddbb-644b-4e24-9ded-878b0e852a03', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["洪源誰孕，疏爲江河。","大塊孰埏，播爲山阿。"]', '["洪源誰孕，疏爲江河。","大塊孰埏，播爲山阿。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744878b3-298d-484e-8097-510f474e8f37', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["厥流浩漾，厥勢嵯峨。","今君之酌，慰我實多。"]', '["厥流浩漾，厥勢嵯峨。","今君之酌，慰我實多。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45283a9-7eb5-419d-9871-021a7af0ce46', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["禮酒既酌，嘉賓既厚，牘爲之奏。"]', '["禮酒既酌，嘉賓既厚，牘爲之奏。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b747dbd-3e50-4a74-b33d-e9dd178f1476', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["禮酒既竭，嘉賓既悅，應爲之節。"]', '["禮酒既竭，嘉賓既悅，應爲之節。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c8d9e2-a103-4ea7-84ee-f73d12767990', '補周禮九夏系文   三', '補周禮九夏系文   三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["禮酒既罄，嘉賓既醒，雅爲之行。"]', '["禮酒既罄，嘉賓既醒，雅爲之行。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84e1f53-b20d-443d-ad69-df756f979bf5', '補周禮九夏系文   一', '補周禮九夏系文   一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["桓桓其珪，衮衮其衣。","出作二伯，天子是毗。"]', '["桓桓其珪，衮衮其衣。","出作二伯，天子是毗。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ad8da7-f784-4635-886a-5711ea38fa9f', '補周禮九夏系文   二', '補周禮九夏系文   二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["桓桓其珪，衮衮其服。","入作三孤，國人是福。"]', '["桓桓其珪，衮衮其服。","入作三孤，国人是福。"]', '诗', 'shi', '', NULL, '補周禮九夏系文   二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109074c4-087c-4406-a668-484196330f74', '三羞詩三首', '三羞诗三首', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾聞古君子，介介勵其節。","入門疑儲宮，撫己思鈇鉞。","志者若不退，佞者何由達。","君臣一殽膳，家國共殘殺。","此道見於今，永思心若裂。","王臣方謇謇，佐我無玷缺。","如何以謀計，中道生芽蘗。","憲司遵故典，分道播南越。","蒼惶出班行，家室不容別。","玄鬢行爲霜，清淚立成血。","乘遽劇飛鳥，就傳過風發。","嗟吾何爲者，叨在造士列。","獻文不上第，歸于淮之汭。","蹇蹄可再犇，退羽可後歇。","利則侶軒裳，塞則友松月。","而於方寸內，未有是愁結。","未爲祿食仕，俯不媿粱糲。","未爲冠冕人，死不慙忠烈。","如何有是心，不能叩丹闕。","赫赫負君歸，南山采芝蕨。"]', '["吾闻古君子，介介勵其節。","入门疑儲宮，撫己思鈇鉞。","志者若不退，佞者何由達。","君臣一殽膳，家国共殘殺。","此道见於今，永思心若裂。","王臣方謇謇，佐我無玷缺。","如何以謀計，中道生芽蘗。","憲司遵故典，分道播南越。","蒼惶出班行，家室不容別。","玄鬢行爲霜，清泪立成血。","乘遽劇飞鸟，就傳過风發。","嗟吾何爲者，叨在造士列。","獻文不上第，归于淮之汭。","蹇蹄可再犇，退羽可後歇。","利則侶軒裳，塞則友松月。","而於方寸內，未有是愁結。","未爲祿食仕，俯不媿粱糲。","未爲冠冕人，死不慙忠烈。","如何有是心，不能叩丹闕。","赫赫負君归，南山采芝蕨。"]', '诗', 'shi', '', NULL, '三羞詩三首 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81b414f-2c26-4b9b-bb35-fa468d319ddc', '三羞詩三首', '三羞诗三首', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["南荒不擇吏，致我交阯覆。","緜聯三四年，流爲中夏辱。","懦者鬬即退，武者兵則黷。","軍庸滿天下，戰將多金玉。","刮則齊民癕，分爲猛士祿。","雄健許昌師，忠武冠其族。","去爲萬騎風，住作一川肉。","昨朝殘卒回，千門萬戶哭。","哀聲動閭里，怨氣成山谷。","誰能聽晝鼙，不忍看金鏃。","吾有制勝術，不奈賤碌碌。","貯之胸臆間，慙見許師屬。","自嗟胡爲者，得躡前修躅。","家不出軍租，身不識部曲。","亦衣許師衣，亦食許師粟。","方知古人道，蔭我已爲足。","念此向誰羞，悠悠潁川綠。"]', '["南荒不擇吏，致我交阯覆。","緜聯三四年，流爲中夏辱。","懦者鬬即退，武者兵則黷。","軍庸满天下，戰將多金玉。","刮則齊民癕，分爲猛士祿。","雄健許昌師，忠武冠其族。","去爲万騎风，住作一川肉。","昨朝殘卒回，千门万戶哭。","哀声动閭里，怨氣成山谷。","誰能听晝鼙，不忍看金鏃。","吾有制勝術，不奈賤碌碌。","貯之胸臆间，慙见許師屬。","自嗟胡爲者，得躡前修躅。","家不出軍租，身不識部曲。","亦衣許師衣，亦食許師粟。","方知古人道，蔭我已爲足。","念此向誰羞，悠悠潁川綠。"]', '诗', 'shi', '', NULL, '三羞詩三首 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52e1527-2850-4b7a-8e17-4b895ee1dd98', '三羞詩三首', '三羞诗三首', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["天子丙戌年，淮右民多飢。","就中潁之汭，轉徙何纍纍。","夫婦相顧亡，棄却抱中兒。","兄弟各自散，出門如大癡。","一金易蘆蔔，一縑換鳧茈。","荒村墓鳥樹，空屋野花籬。","兒童齧草根，倚桑空羸羸。","斑白死路傍，枕土皆離離。","方知聖人教，於民良在斯。","厲能去人愛，荒能奪人慈。","如何司牧者，有術皆在茲。","粵吾何爲人，數畝清溪湄。","一寫落第文，一家歡復嬉。","朝食有麥饘，晨起有布衣。","一身既飽暖，一家無怨咨。","家雖有畎畝，手不秉鎡基。","歲雖有札瘥，庖不廢晨炊。","何道以致是，我有明公知。","食之以侯食，衣之以侯衣。","歸時卹金帛，使我奉庭闈。","撫己媿潁民，奚不進德爲。","因茲感知己，盡日空涕洟。"]', '["天子丙戌年，淮右民多飢。","就中潁之汭，轉徙何纍纍。","夫婦相顧亡，棄却抱中兒。","兄弟各自散，出门如大癡。","一金易蘆蔔，一縑換鳧茈。","荒村墓鸟樹，空屋野花籬。","兒童齧草根，倚桑空羸羸。","斑白死路傍，枕土皆離離。","方知聖人教，於民良在斯。","厲能去人愛，荒能奪人慈。","如何司牧者，有術皆在茲。","粵吾何爲人，數畝清溪湄。","一寫落第文，一家歡复嬉。","朝食有麦饘，晨起有布衣。","一身既飽暖，一家無怨咨。","家雖有畎畝，手不秉鎡基。","歲雖有札瘥，庖不廢晨炊。","何道以致是，我有明公知。","食之以侯食，衣之以侯衣。","归时卹金帛，使我奉庭闈。","撫己媿潁民，奚不進德爲。","因茲感知己，尽日空涕洟。"]', '诗', 'shi', '', NULL, '三羞詩三首 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98a6211-a1b2-4955-98fa-f94f052f7949', '七愛詩 房杜二相國', '七愛诗 房杜二相国', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛房與杜，貧賤共聯步。","脫身拋亂世，策杖歸真主。","縱橫握中算，左右天下務。","骯髒無敵才，磊落不世遇。","美矣名公卿，魁然真宰輔。","黃閣三十年，清風一萬古。","巨業照國史，大勳鎮王府。","遂使後世民，至今受陶鑄。","粵吾少有志，敢躡前賢路。","苟得同其時，願爲執鞭豎。"]', '["吾愛房與杜，貧賤共聯步。","脫身拋亂世，策杖归真主。","縱橫握中算，左右天下務。","骯髒無敵才，磊落不世遇。","美矣名公卿，魁然真宰輔。","黄閣三十年，清风一万古。","巨業照国史，大勳鎮王府。","遂使後世民，至今受陶鑄。","粵吾少有志，敢躡前賢路。","苟得同其时，願爲執鞭豎。"]', '诗', 'shi', '', NULL, '七愛詩 房杜二相國 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f87f2a-adab-40f2-93ec-15cccca71f4a', '七愛詩 李太尉', '七愛诗 李太尉', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛李太尉，崛起定中原。","驍雄十萬兵，四面圍國門。","一戰取王畿，一叱散妖氛。","乘輿既反正，兇豎爭亡魂。","巍巍柱天功，蕩蕩蓋世勳。","仁於曹孟德，勇過霍將軍。","丹券入帑藏，青史傳子孫。","所謂大丈夫，動合驚乾坤。","所謂聖天子，難得忠貞臣。","下以契魚水，上以合風雲。","百世必一亂，千年方一人。","吾雖翰墨子，氣概敢不羣。","願以太平頌，題向甘泉春。"]', '["吾愛李太尉，崛起定中原。","驍雄十万兵，四面圍国门。","一戰取王畿，一叱散妖氛。","乘輿既反正，兇豎爭亡魂。","巍巍柱天功，蕩蕩蓋世勳。","仁於曹孟德，勇過霍將軍。","丹券入帑藏，青史傳子孫。","所謂大丈夫，动合驚乾坤。","所謂聖天子，难得忠貞臣。","下以契鱼水，上以合风云。","百世必一亂，千年方一人。","吾雖翰墨子，氣概敢不羣。","願以太平頌，題向甘泉春。"]', '诗', 'shi', '', NULL, '七愛詩 李太尉 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86ea9f2-365a-47d5-9fc5-156790cb510b', '七愛詩 盧徵君', '七愛诗 盧徵君', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛盧徵君，高臥嵩山裏。","百辟未一顧，三徵方暫起。","坦腹對宰相，岸幘揖天子。","建禮門前吟，金鑾殿裏醉。","天下皆餔糟，真君獨潔己。","天下皆樂聞，徵君獨洗耳。","天下皆懷羞，徵君獨多恥。","銀黃不妨懸，赤紱不妨被。","而於心抱中，獨作羲皇地。","籃輿一云返，泥詔褒不已。","再看緱山雲，重酌嵩陽水。","放曠書裏終，逍遙醉中死。","吾謂伊與周，不若徵君貴。","吾謂巢與許，不若徵君義。","高名無階級，逸迹絕涯涘。","萬世唐書中，逸名不可比。","粵吾慕真隱，強以骨肉累。","如教不爲名，敢有徵君志。"]', '["吾愛盧徵君，高臥嵩山裏。","百辟未一顧，三徵方暫起。","坦腹对宰相，岸幘揖天子。","建禮门前吟，金鑾殿裏醉。","天下皆餔糟，真君独潔己。","天下皆乐闻，徵君独洗耳。","天下皆懷羞，徵君独多恥。","銀黄不妨懸，赤紱不妨被。","而於心抱中，独作羲皇地。","籃輿一云返，泥詔褒不已。","再看緱山云，重酌嵩陽水。","放曠书裏終，逍遙醉中死。","吾謂伊與周，不若徵君貴。","吾謂巢與許，不若徵君義。","高名無階級，逸迹絕涯涘。","万世唐书中，逸名不可比。","粵吾慕真隐，強以骨肉累。","如教不爲名，敢有徵君志。"]', '诗', 'shi', '', NULL, '七愛詩 盧徵君 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8add5f-4b86-4ea2-a579-5b94918c316c', '七愛詩 元魯山', '七愛诗 元魯山', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛元紫芝，清介如伯夷。","輦母遠之官，宰邑無玷疵。","三年魯山民，豐稔不暫饑。","三年魯山吏，清慎各自持。","只飲魯山泉，只采魯山薇。","一室冰檗苦，四遠聲光飛。","退歸舊隱來，斗酒入茅茨。","雞黍匪家畜，琴尊常自怡。","盡日一菜食，窮年一布衣。","清似匣中鏡，直如琴上絲。","世無用賢人，青山生白髭。","既臥黔婁衾，空立陳寔碑。","吾無魯山道，空有魯山辭。","所恨不相識，援毫空涕垂。"]', '["吾愛元紫芝，清介如伯夷。","輦母远之官，宰邑無玷疵。","三年魯山民，豐稔不暫饑。","三年魯山吏，清慎各自持。","只饮魯山泉，只采魯山薇。","一室冰檗苦，四远声光飞。","退归旧隐来，斗酒入茅茨。","雞黍匪家畜，琴尊常自怡。","尽日一菜食，窮年一布衣。","清似匣中镜，直如琴上絲。","世無用賢人，青山生白髭。","既臥黔婁衾，空立陳寔碑。","吾無魯山道，空有魯山辞。","所恨不相識，援毫空涕垂。"]', '诗', 'shi', '', NULL, '七愛詩 元魯山 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f60753-f228-4620-8be8-fa2701b3b58d', '七愛詩 李翰林', '七愛诗 李翰林', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛李太白，身是酒星魄。","口吐天上文，迹作人間客。","磥砢千丈林，澄澈萬尋碧。","醉中草樂府，十幅筆一息。","召見承明廬，天子親賜食。","醉曾吐御牀，傲幾觸天澤。","權臣妬逸才，心如斗筲窄。","失恩出內署，海岳甘自適。","刺謁戴接㒿，赴宴著縠屐。","諸侯百步迎，明君九天憶。","竟遭腐脅疾，醉魄歸八極。","大鵬不可籠，大椿不可植。","蓬壺不可見，姑射不可識。","五岳爲辭鋒，四溟作胸臆。","惜哉千萬年，此俊不可得。"]', '["吾愛李太白，身是酒星魄。","口吐天上文，迹作人间客。","磥砢千丈林，澄澈万尋碧。","醉中草乐府，十幅笔一息。","召见承明廬，天子親賜食。","醉曾吐御牀，傲幾觸天澤。","權臣妬逸才，心如斗筲窄。","失恩出內署，海岳甘自適。","刺謁戴接㒿，赴宴著縠屐。","諸侯百步迎，明君九天憶。","竟遭腐脅疾，醉魄归八極。","大鵬不可籠，大椿不可植。","蓬壺不可见，姑射不可識。","五岳爲辞鋒，四溟作胸臆。","惜哉千万年，此俊不可得。"]', '诗', 'shi', '', NULL, '七愛詩 李翰林 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b96252b-751b-410c-85d5-57561fc51174', '七愛詩 白太傅', '七愛诗 白太傅', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾愛白樂天，逸才生自然。","誰謂辭翰器，乃是經綸賢。","歘從浮豔詩，作得典誥篇。","立身百行足，爲文六藝全。","清望逸內署，直聲驚諫垣。","所刺必有思，所臨必可傳。","忘形任詩酒，寄傲徧林泉。","所望標文柄，所希持化權。","何期遇訾毀，中道多左遷。","天下皆汲汲，樂天獨怡然。","天下皆悶悶，樂天獨舍旃。","高吟辭兩掖，清嘯罷三川。","處世似孤鶴，遺榮同脫蟬。","仕若不得志，可爲龜鏡焉。"]', '["吾愛白乐天，逸才生自然。","誰謂辞翰器，乃是經綸賢。","歘從浮豔诗，作得典誥篇。","立身百行足，爲文六藝全。","清望逸內署，直声驚諫垣。","所刺必有思，所臨必可傳。","忘形任诗酒，寄傲徧林泉。","所望標文柄，所希持化權。","何期遇訾毀，中道多左遷。","天下皆汲汲，乐天独怡然。","天下皆悶悶，乐天独舍旃。","高吟辞兩掖，清嘯罷三川。","处世似孤鹤，遺榮同脫蟬。","仕若不得志，可爲龟镜焉。"]', '诗', 'shi', '', NULL, '七愛詩 白太傅 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4500bdbe-1f32-481c-b434-049872d5877c', '正樂府十篇 卒妻怨', '正乐府十篇 卒妻怨', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["河湟戍卒去，一半多不迴。","家有半菽食，身爲一囊灰。","官吏按其籍，伍中斥其妻。","處處魯人髽，家家杞婦哀。","少者任所歸，老者無所攜。","況當札瘥年，米粒如瓊瑰。","纍纍作餓殍，見之心若摧。","其夫死鋒刃，其室委塵埃。","其命即用矣，其賞安在哉。","豈無黔敖恩，救此窮餓骸。","誰知白屋士，念此飜欸欸。"]', '["河湟戍卒去，一半多不迴。","家有半菽食，身爲一囊灰。","官吏按其籍，伍中斥其妻。","处处魯人髽，家家杞婦哀。","少者任所归，老者無所携。","況當札瘥年，米粒如瓊瑰。","纍纍作餓殍，见之心若摧。","其夫死鋒刃，其室委塵埃。","其命即用矣，其賞安在哉。","豈無黔敖恩，救此窮餓骸。","誰知白屋士，念此飜欸欸。"]', '诗', 'shi', '', NULL, '正樂府十篇 卒妻怨 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbc2e12-4880-44b8-930f-bb75ce4bd579', '正樂府十篇 橡媼歎', '正乐府十篇 橡媼歎', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["秋深橡子熟，散落榛蕪岡。","傴傴黃髪媼，拾之踐晨霜。","移時始盈掬，盡日方滿筐。","幾曝復幾蒸，用作三冬糧。","山前有熟稻，紫穗襲人香。","細獲又精舂，粒粒如玉璫。","持之納於官，私室無倉箱。","如何一石餘，只作五斗量。","狡吏不畏刑，貪官不避贓。","農時作私債，農畢歸官倉。","自冬及於春，橡實誑飢腸。","吾聞田成子，詐仁猶自王。","吁嗟逢橡媼，不覺淚霑裳。"]', '["秋深橡子熟，散落榛蕪岡。","傴傴黄髪媼，拾之踐晨霜。","移时始盈掬，尽日方满筐。","幾曝复幾蒸，用作三冬糧。","山前有熟稻，紫穗襲人香。","細獲又精舂，粒粒如玉璫。","持之納於官，私室無倉箱。","如何一石餘，只作五斗量。","狡吏不畏刑，貪官不避贓。","農时作私債，農畢归官倉。","自冬及於春，橡實誑飢腸。","吾闻田成子，詐仁猶自王。","吁嗟逢橡媼，不覺泪霑裳。"]', '诗', 'shi', '', NULL, '正樂府十篇 橡媼歎 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8fd13a-79aa-40a6-b7c3-8e8c89ee5af0', '正樂府十篇 貪官怨', '正乐府十篇 貪官怨', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["國家省闥吏，賞之皆與位。","素來不知書，豈能精吏理。","大者或宰邑，小者皆尉史。","愚者皆混沌，毒者如雄虺。","傷哉堯舜民，肉袒受鞭箠。","吾聞古聖王，天下無遺士。","朝庭及下邑，治者皆仁義。","國家選賢良，定制兼拘忌。","所以用此徒，令之充祿仕。","何不廣取人，何不廣歷試？","下位既賢哉，上位何如矣。","胥徒賞以財，俊造悉爲吏。","天下若不平，吾當甘棄市。"]', '["国家省闥吏，賞之皆與位。","素来不知书，豈能精吏理。","大者或宰邑，小者皆尉史。","愚者皆混沌，毒者如雄虺。","傷哉堯舜民，肉袒受鞭箠。","吾闻古聖王，天下無遺士。","朝庭及下邑，治者皆仁義。","国家選賢良，定制兼拘忌。","所以用此徒，令之充祿仕。","何不廣取人，何不廣歷試？","下位既賢哉，上位何如矣。","胥徒賞以財，俊造悉爲吏。","天下若不平，吾當甘棄市。"]', '诗', 'shi', '', NULL, '正樂府十篇 貪官怨 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2693b5ba-1e9a-4d8b-a415-dfc484c9efa9', '正樂府十篇 農父謠', '正乐府十篇 農父謠', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["農父冤辛苦，向我述其情。","難將一人農，可備十人征。","如何江淮粟，輓漕輸咸京。","黃河水如電，一半沈與傾。","均輸利其事，職司安敢評。","三川豈不農，三輔豈不耕。","奚不車其粟，用以供天兵。","美哉農父言，何計達王程。"]', '["農父冤辛苦，向我述其情。","难將一人農，可備十人征。","如何江淮粟，輓漕輸咸京。","黄河水如電，一半沈與傾。","均輸利其事，職司安敢評。","三川豈不農，三輔豈不耕。","奚不车其粟，用以供天兵。","美哉農父言，何計達王程。"]', '诗', 'shi', '', NULL, '正樂府十篇 農父謠 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb18d12-4851-4903-9317-d6a28b2f754d', '正樂府十篇 路臣恨', '正乐府十篇 路臣恨', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["路臣何方來，去馬真如龍。","行驕不動塵，滿轡金瓏璁。","有人自天來，將避荆棘叢。","獰呼不覺止，推下蒼黃中。","十夫掣鞭策，御之如驚鴻。","日行六七郵，瞥若鷹無蹤。","路臣慎勿愬，愬則刑爾躬。","軍期方似雨，天命正如風。","七雄戰爭時，賓旅猶自通。","如何太平世，動步却途窮。"]', '["路臣何方来，去马真如龙。","行驕不动塵，满轡金瓏璁。","有人自天来，將避荆棘叢。","獰呼不覺止，推下蒼黄中。","十夫掣鞭策，御之如驚鴻。","日行六七郵，瞥若鷹無蹤。","路臣慎勿愬，愬則刑爾躬。","軍期方似雨，天命正如风。","七雄戰爭时，賓旅猶自通。","如何太平世，动步却途窮。"]', '诗', 'shi', '', NULL, '正樂府十篇 路臣恨 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21fdefcf-2c46-461e-9729-1fe9dbd8bdd1', '正樂府十篇 賤貢士', '正乐府十篇 賤貢士', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["南越貢珠璣，西蜀進羅綺。","到京未晨旦，一一見天子。","如何賢與俊，爲貢賤如此。","所知不可求，敢望前席事。","吾聞古聖人，射宮親選士。","不肖盡屏跡，賢能皆得位。","所以謂得人，所以稱多士。","歎息幾編書，時哉又何異。"]', '["南越貢珠璣，西蜀進羅綺。","到京未晨旦，一一见天子。","如何賢與俊，爲貢賤如此。","所知不可求，敢望前席事。","吾闻古聖人，射宮親選士。","不肖尽屏跡，賢能皆得位。","所以謂得人，所以稱多士。","歎息幾編书，时哉又何異。"]', '诗', 'shi', '', NULL, '正樂府十篇 賤貢士 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6923eb3b-f245-42e5-bf3e-30a2a6a28872', '正樂府十篇 頌夷臣', '正乐府十篇 頌夷臣', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夷師本學外，仍善唐文字。","吾人本尚捨，何況夷臣事。","所以不學者，反爲夷臣戲。","所以尸祿人，反爲夷臣忌。","吁嗟華風衰，何嘗不由是。"]', '["夷師本学外，仍善唐文字。","吾人本尚捨，何況夷臣事。","所以不学者，反爲夷臣戲。","所以尸祿人，反爲夷臣忌。","吁嗟华风衰，何嘗不由是。"]', '诗', 'shi', '', NULL, '正樂府十篇 頌夷臣 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b48c16-6454-41b1-9cb5-497b757a3181', '正樂府十篇 惜義鳥', '正乐府十篇 惜義鸟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["商顏多義鳥，義鳥實可嗟。","危巢末纍纍，隱在栲木花。","他巢若有雛，乳之如一家。","他巢若遭捕，投之同一羅。","商人每秋貢，所貴復如何。","飽以稻粱滋，飾以組繡華。","惜哉仁義禽，委戲於宮娥。","吾聞鳳之貴，仁義亦足夸。","所以不遭捕，蓋緣生不多。"]', '["商顏多義鸟，義鸟實可嗟。","危巢末纍纍，隐在栲木花。","他巢若有雛，乳之如一家。","他巢若遭捕，投之同一羅。","商人每秋貢，所貴复如何。","飽以稻粱滋，飾以組繡华。","惜哉仁義禽，委戲於宮娥。","吾闻鳳之貴，仁義亦足夸。","所以不遭捕，蓋緣生不多。"]', '诗', 'shi', '', NULL, '正樂府十篇 惜義鳥 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82f1f95-e9cf-4401-bfe7-461efa41a4fb', '正樂府十篇 誚虛器', '正乐府十篇 誚虛器', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["襄陽作髹器，中有庫露真。","持以遺北虜，紿云生有神。","每歲走其使，所費如雲屯。","吾聞古聖王，修德來遠人。","未聞作巧詐，用欺禽獸君。","吾道尚如此，戎心安足云。","如何漢宣帝，却得呼韓臣。"]', '["襄陽作髹器，中有庫露真。","持以遺北虜，紿云生有神。","每歲走其使，所費如云屯。","吾闻古聖王，修德来远人。","未闻作巧詐，用欺禽獸君。","吾道尚如此，戎心安足云。","如何漢宣帝，却得呼韓臣。"]', '诗', 'shi', '', NULL, '正樂府十篇 誚虛器 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9900796d-e39c-412a-8ace-1b7a1e4f51b4', '正樂府十篇 哀隴民', '正乐府十篇 哀隴民', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["隴山千萬仞，鸚鵡巢其巔。","窮危又極嶮，其山猶不全。","蚩蚩隴之民，懸度如登天。","空中覘其巢，墮者爭紛然。","百禽不得一，十人九死焉。","隴川有戍卒，戍卒亦不閑。","將命提雕籠，直到金臺前。","彼毛不自珍，彼舌不自言。","胡爲輕人命，奉此玩好端。","吾聞古聖王，珍獸皆舍旃。","今此隴民屬，每歲啼漣漣。"]', '["隴山千万仞，鸚鵡巢其巔。","窮危又極嶮，其山猶不全。","蚩蚩隴之民，懸度如登天。","空中覘其巢，墮者爭紛然。","百禽不得一，十人九死焉。","隴川有戍卒，戍卒亦不闲。","將命提雕籠，直到金台前。","彼毛不自珍，彼舌不自言。","胡爲轻人命，奉此玩好端。","吾闻古聖王，珍獸皆舍旃。","今此隴民屬，每歲啼漣漣。"]', '诗', 'shi', '', NULL, '正樂府十篇 哀隴民 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f87dade-1eb1-42c0-bfa1-a1f557799e6d', '奉獻致政裴祕監', '奉獻致政裴祕監', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何胤本徵士，高情動天地。","既無閥閱門，常嫌冠冕累。","宰邑著嘉政，爲郡留高致。","移官在書府，方樂鴛池貴。","玉季牧江西，泣之不忍離。","捨杖隨之去，天下欽高義。","烏帽白絺裘，籃輿竹如意。","黃菊陶潛酒，青山謝公妓。","月檻詠詩情，花溪釣魚戲。","鍾陵既方舟，魏闕將結駟。","甘求白首閑，不爲蒼生起。","優詔加大監，所以符公議。","既爲逍遙公，又作鴟夷子。","安車懸不出，駟馬閑無事。","微雨漢陂舟，殘日終南騎。","富貴盡凌雲，何人能至此。","猜禍皆及身，何復至如是。","賢哉此丈夫，百世一人矣。"]', '["何胤本徵士，高情动天地。","既無閥閱门，常嫌冠冕累。","宰邑著嘉政，爲郡留高致。","移官在书府，方乐鴛池貴。","玉季牧江西，泣之不忍離。","捨杖隨之去，天下欽高義。","烏帽白絺裘，籃輿竹如意。","黄菊陶潛酒，青山謝公妓。","月檻詠诗情，花溪釣鱼戲。","鍾陵既方舟，魏闕將結駟。","甘求白首闲，不爲蒼生起。","優詔加大監，所以符公議。","既爲逍遙公，又作鴟夷子。","安车懸不出，駟马闲無事。","微雨漢陂舟，殘日終南騎。","富貴尽凌云，何人能至此。","猜禍皆及身，何复至如是。","賢哉此丈夫，百世一人矣。"]', '诗', 'shi', '', NULL, '奉獻致政裴祕監 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b363fb7-eaef-4220-8170-f55dc512fa36', '秋夜有懷', '秋夜有懷', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夢裏憂身泣，覺來衣尚濕。","骨肉煎我心，不是謀生急。","如何欲佐主，功名未成立。","處世既孤特，傳家無承襲。","明朝走梁楚，步步出門澀。","如何一寸心，千愁萬愁入。"]', '["梦裏憂身泣，覺来衣尚濕。","骨肉煎我心，不是謀生急。","如何欲佐主，功名未成立。","处世既孤特，傳家無承襲。","明朝走梁楚，步步出门澀。","如何一寸心，千愁万愁入。"]', '诗', 'shi', '', NULL, '秋夜有懷 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57bcca38-d5fe-4816-85dd-d35b7f9b1917', '喜鵲', '喜鵲', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["棄羶在庭際，雙鵲來搖尾。","欲啄怕人驚，喜語晴光裏。","何況佞倖人，微禽解如此。"]', '["棄羶在庭際，雙鵲来搖尾。","欲啄怕人驚，喜語晴光裏。","何況佞倖人，微禽解如此。"]', '诗', 'shi', '', NULL, '喜鵲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232245f7-1235-49da-8f02-c1a362ba59e1', '蚊子', '蚊子', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["隱隱聚若雷，噆膚不知足。","皇天若不平，微物教食肉。","貧士無絳紗，忍苦臥茅屋。","何事覓膏腴，腹無太倉粟。"]', '["隐隐聚若雷，噆膚不知足。","皇天若不平，微物教食肉。","貧士無絳紗，忍苦臥茅屋。","何事覓膏腴，腹無太倉粟。"]', '诗', 'shi', '', NULL, '蚊子 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0c8cae-1140-46b4-8a97-f879184aff12', '鹿門夏日', '鹿门夏日', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["滿院松桂陰，日午却不知。","山人睡一覺，庭鵲立未移。","出檐趁雲去，忘戴白接㒿。","書眼若薄霧，酒腸如漏巵。","身外所勞者，飲食須自持。","何如便絕粒，直使身無爲。"]', '["满院松桂陰，日午却不知。","山人睡一覺，庭鵲立未移。","出檐趁云去，忘戴白接㒿。","书眼若薄霧，酒腸如漏巵。","身外所勞者，饮食須自持。","何如便絕粒，直使身無爲。"]', '诗', 'shi', '', NULL, '鹿門夏日 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f703e5c-9992-4f67-ac48-65b185208c47', '偶書', '偶书', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["女媧掉繩索，絙泥成下人。","至今頑愚者，生如土偶身。","雲物養吾道，天爵高我貧。","大笑猗氏輩，爲富皆不仁。"]', '["女媧掉繩索，絙泥成下人。","至今頑愚者，生如土偶身。","云物養吾道，天爵高我貧。","大笑猗氏輩，爲富皆不仁。"]', '诗', 'shi', '', NULL, '偶書 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aaa87fa-561c-4f53-93b3-0e6c05b4fdee', '讀書', '读书', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["家資是何物，積帙列梁梠。","高齋曉開卷，獨共聖人語。","英賢雖異世，自古心相許。","案頭見蠹魚，猶勝凡儔侶。"]', '["家資是何物，積帙列梁梠。","高斋晓开卷，独共聖人語。","英賢雖異世，自古心相許。","案头见蠹鱼，猶勝凡儔侶。"]', '诗', 'shi', '', NULL, '讀書 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076484f6-5fd4-413d-9f33-9d045753d729', '貧居秋日', '貧居秋日', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["亭午頭未冠，端坐獨愁予。","貧家煙爨稀，竈底陰蟲語。","門小媿車馬，廩空慙雀鼠。","盡室未寒衣，機聲羨鄰女。"]', '["亭午头未冠，端坐独愁予。","貧家煙爨稀，竈底陰蟲語。","门小媿车马，廩空慙雀鼠。","尽室未寒衣，機声羨鄰女。"]', '诗', 'shi', '', NULL, '貧居秋日 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577499d9-da7f-464d-ab0d-b23cad0bb023', '魯望讀襄陽耆舊傳見贈五百言過褒庸材靡有稱是然襄陽曩事歷歷在目夫耆舊傳所未載者漢陽王則宗社元勳孟浩然則文章大匠予次而贊之因而寄荅亦詩人無言不詶之義也次韻', '魯望读襄陽耆旧傳见贈五百言過褒庸材靡有稱是然襄陽曩事歷歷在目夫耆旧傳所未載者漢陽王則宗社元勳孟浩然則文章大匠予次而贊之因而寄荅亦诗人無言不詶之義也次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["漢水碧於天，南荆廓然秀。","廬羅遵古俗，鄢郢迷昔囿。","幽奇無得狀，巉絕不能究。","興替忽矣新，山川悄然舊。","斑斑生造士，一一應玄宿。","巴庸乃嶮岨，屈景實豪右。","是非既自分，涇渭不相就。","粵自靈均來，清才若天漱。","偉哉洞上隱，卓爾隆中耨。","始將麋鹿狎，遂與麒麟鬬。","萬乘不可謁，千鍾固非茂。","爰從景升死，境上多兵候。","檀溪試戈船，峴嶺屯貝胄。","寂莫數百年，質唯包礫琇。","上玄賞唐德，生賢命之授。","是爲漢陽王，帝曰俞爾奏。","巨德聳神鬼，宏才轢前後。","勢端唯金莖，質古乃玉豆。","行葉蔭大椿，詞源吐洪溜。","六成清廟音，一柱明堂構。","在昔房陵遷，圓穹正中漏。","繄王揭然出，上下拓宇宙。","俯視三事者，騃騃若童幼。","低摧護中興，若鳳視其鷇。","遇險必伸足，逢誅將引脰。","既正北極尊，遂治衆星謬。","重聞章陵幸，再見岐陽狩。","日似新刮膜，天如重熨縐。","易政疾似欬，求賢甚於購。","化之未朞年，民安而國富。","翼衛兩舜趨，鉤陳十堯驟。","忽然遺相印，如羿卸其彀。","姦倖却乘釁，播遷遂終壽。","遺廟屹峰崿，功名紛組繡。","開元文物盛，孟子生荆岫。","斯文縱奇巧，秦璽新雕鏤。","甘窮臥牛衣，受辱對狗竇。","思變如易爻，才通似玄首。","祕於龍宮室，怪於天篆籀。","知者競欲戴，嫉者或將詬。","任達且百觚，遂爲當時陋。","既作才鬼終，恐爲仙籍售。","予生二賢末，得作升木狖。","兼濟與獨善，俱敢懷其臭。","江漢稱炳靈，克明嗣清晝。","繼彼欲爲三，如醨如醇酎。","既見陸夫子，駑心却伏廄。","結彼世外交，遇之於邂逅。","兩鶴思競閑，雙松格爭瘦。","唯恐別仙才，漣漣涕襟袖。"]', '["漢水碧於天，南荆廓然秀。","廬羅遵古俗，鄢郢迷昔囿。","幽奇無得狀，巉絕不能究。","兴替忽矣新，山川悄然旧。","斑斑生造士，一一應玄宿。","巴庸乃嶮岨，屈景實豪右。","是非既自分，涇渭不相就。","粵自靈均来，清才若天漱。","偉哉洞上隐，卓爾隆中耨。","始將麋鹿狎，遂與麒麟鬬。","万乘不可謁，千鍾固非茂。","爰從景升死，境上多兵候。","檀溪試戈船，峴嶺屯貝胄。","寂莫數百年，質唯包礫琇。","上玄賞唐德，生賢命之授。","是爲漢陽王，帝曰俞爾奏。","巨德聳神鬼，宏才轢前後。","勢端唯金莖，質古乃玉豆。","行葉蔭大椿，词源吐洪溜。","六成清廟音，一柱明堂構。","在昔房陵遷，圓穹正中漏。","繄王揭然出，上下拓宇宙。","俯視三事者，騃騃若童幼。","低摧護中兴，若鳳視其鷇。","遇險必伸足，逢誅將引脰。","既正北極尊，遂治衆星謬。","重闻章陵幸，再见岐陽狩。","日似新刮膜，天如重熨縐。","易政疾似欬，求賢甚於購。","化之未朞年，民安而国富。","翼衛兩舜趨，鉤陳十堯驟。","忽然遺相印，如羿卸其彀。","姦倖却乘釁，播遷遂終壽。","遺廟屹峰崿，功名紛組繡。","开元文物盛，孟子生荆岫。","斯文縱奇巧，秦璽新雕鏤。","甘窮臥牛衣，受辱对狗竇。","思变如易爻，才通似玄首。","祕於龙宮室，怪於天篆籀。","知者競欲戴，嫉者或將詬。","任達且百觚，遂爲當时陋。","既作才鬼終，恐爲仙籍售。","予生二賢末，得作升木狖。","兼濟與独善，俱敢懷其臭。","江漢稱炳靈，克明嗣清晝。","繼彼欲爲三，如醨如醇酎。","既见陸夫子，駑心却伏廄。","結彼世外交，遇之於邂逅。","兩鹤思競闲，雙松格爭瘦。","唯恐別仙才，漣漣涕襟袖。"]', '诗', 'shi', '', NULL, '魯望讀襄陽耆舊傳見贈五百言過褒庸材靡有稱是然襄陽曩事歷歷在目夫耆舊傳所未載者漢陽王則宗社元勳孟浩然則文章大匠予次而贊之因而寄荅亦詩人無言不詶之義也次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4005be1d-41b2-4deb-816a-e557523330b9', '魯望昨以五百言見貽過有褒美內揣庸陋彌增媿悚因成一千言上述吾唐文物之盛次敘相得之歡亦迭和之微旨也', '魯望昨以五百言见貽過有褒美內揣庸陋彌增媿悚因成一千言上述吾唐文物之盛次敘相得之歡亦迭和之微旨也', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["三辰至精氣，生自蒼頡前。","粵從有文字，精氣銖於緜。","所以楊墨後，文詞縱橫顛。","元狩富材術，建安儼英賢。","厥祀四百餘，作者如排穿。","五馬渡江日，羣魚食蒲年。","大風蕩天地，萬陣黃鬚羶。","縱有命世才，不如一空弮。","後至陳隋世，得之拘且緛。","太浮如瀲灩，太細如蚳蝝。","太亂如靡靡，太輕如芊芊。","流之爲䣱醟，變之爲游畋。","百足雖云衆，不救殺馬蚿。","君臣作降虜，北走如㺦猭。","所以文字妖，致其國朝遷。","吾唐革其弊，取士將科縣。","文星下爲人，洪秀密於緶。","大開紫宸扉，來者皆詳延。","日晏朝不罷，龍姿歡𨌈𨌈。","於焉周道反，由是秦法悛。","射洪陳子昂，其聲亦喧闐。","惜哉不得時，將奮猶拘攣。","玉壘李太白，銅堤孟浩然。","李寬包堪輿，孟澹擬漪漣。","埋骨采石壙，留神鹿門埏。","俾其羇旅死，實覺天地孱。","猗與子美思，不盡如轉輇。","縱爲三十車，一字不可捐。","既作風雅主，遂司歌詠權。","誰知耒陽土，埋却真神仙。","當於李杜際，名輩或泝沿。","良御非異馬，由弓非他弦。","其物無同異，其人有媸妍。","自開元至今，宗社紛如煙。","爽若沆瀣英，高如崑崙巔。","百家囂浮說，諸子率寓篇。","築之爲京觀，解之爲牲牷。","各持天地維，率意東西牽。","競抵元化首，爭扼真宰咽。","或作制誥藪，或爲宮體淵。","或堪被金石，或可投花鈿。","或爲輿隸唱，或被兒童憐。","烏壘虜亦寫，雞林夷爭傳。","披揭覆載樞，捭闔神異鍵。","力拋尾閭立，思軋大塊旋。","降氣或若虹，耀影或如{艹/冖/殘}。","萬象瘡復痏，百靈瘠且{疒}。","謂乎數十公，筆若明堂椽。","其中有擬者，不絕當如綖。","齊驅不讓策，竝駕或爭駢。","所以吾唐風，直將三代甄。","被此文物盛，由乎聲詩宣。","采彼風人謠，輶軒輕似鸇。","麗者固不捨，鄙者亦爲銓。","其中有鑾戒，一一堪雕鐫。","乙夜以觀之，吾君無釋焉。","遂命大司樂，度之如星躔。","播於樂府中，俾爲萬代蠲。","吹彼圓丘竹，誦茲清廟弦。","不惟娛列祖，兼可格上玄。","粵予何爲者，生自江海壖。","騃騃自總角，不甘耕一壥。","諸昆指倉庫，謂我死道邊。","何爲不力農，稽古真可嘕。","遂與襏襫著，兼之籉笠全。","風吹蔓草花，颯颯盈荒田。","老牛瞪不行，力弱誰能鞭。","乃將耒與耜，竝換槧與鉛。","閱彼圖籍肆，致之千百編。","攜將入蘇嶺，不就無出緣。","堆書塞低屋，添硯涸小泉。","對燈任髻爇，馮案從肘研。","苟無切玉刀，難除指上胼。","爾來五寒暑，試藝稱精專。","昌黎道未著，文教如欲騫。","其中有聲病，於我如𦧝𦧴。","是敢驅頹波，歸之於大川。","其文如可用，不敢佞與便。","明水在稾秸，太羹臨豆籩。","將來示時人，䝟貐垂饞涎。","亦或尚華縟，亦曾爲便嬛。","亦能制灝灝，亦解攻翩翩。","唯思逢陣敵，與彼爭後先。","避兵入句吳，窮悴祗自跧。","平原陸夫子，投刺來翩躚。","開卷讀數行，爲之加敬虔。","忽窮一兩首，反顧唯曲拳。","始來遺巾幗，乃敢排戈鋋。","或爲拔幟走，或遭劘壘還。","不能收亂轍，豈暇重爲篿。","雖然未三北，亦可輸千鐉。","向來說文字，爾汝名可聯。","聖人病歿世，不患窮而蹎。","我未九品位，君無一囊錢。","相逢得何事，兩籠酬戲牋。","無顏解媮合，底事居冗員。","方知萬鍾祿，不博五湖船。","夷[險]但明月，死生應白蓮。","吟餘凭几飲，釣罷偎蓑眠。","終拋峴山業，相共此留連。"]', '["三辰至精氣，生自蒼頡前。","粵從有文字，精氣銖於緜。","所以楊墨後，文词縱橫顛。","元狩富材術，建安儼英賢。","厥祀四百餘，作者如排穿。","五马渡江日，羣鱼食蒲年。","大风蕩天地，万陣黄鬚羶。","縱有命世才，不如一空弮。","後至陳隋世，得之拘且緛。","太浮如瀲灩，太細如蚳蝝。","太亂如靡靡，太轻如芊芊。","流之爲䣱醟，变之爲游畋。","百足雖云衆，不救殺马蚿。","君臣作降虜，北走如㺦猭。","所以文字妖，致其国朝遷。","吾唐革其弊，取士將科縣。","文星下爲人，洪秀密於緶。","大开紫宸扉，来者皆詳延。","日晏朝不罷，龙姿歡𨌈𨌈。","於焉周道反，由是秦法悛。","射洪陳子昂，其声亦喧闐。","惜哉不得时，將奮猶拘攣。","玉壘李太白，銅堤孟浩然。","李寬包堪輿，孟澹擬漪漣。","埋骨采石壙，留神鹿门埏。","俾其羇旅死，實覺天地孱。","猗與子美思，不尽如轉輇。","縱爲三十车，一字不可捐。","既作风雅主，遂司歌詠權。","誰知耒陽土，埋却真神仙。","當於李杜際，名輩或泝沿。","良御非異马，由弓非他弦。","其物無同異，其人有媸妍。","自开元至今，宗社紛如煙。","爽若沆瀣英，高如崑崙巔。","百家囂浮说，諸子率寓篇。","築之爲京观，解之爲牲牷。","各持天地維，率意东西牽。","競抵元化首，爭扼真宰咽。","或作制誥藪，或爲宮體淵。","或堪被金石，或可投花鈿。","或爲輿隸唱，或被兒童怜。","烏壘虜亦寫，雞林夷爭傳。","披揭覆載樞，捭闔神異鍵。","力拋尾閭立，思軋大塊旋。","降氣或若虹，耀影或如{艹/冖/殘}。","万象瘡复痏，百靈瘠且{疒}。","謂乎數十公，笔若明堂椽。","其中有擬者，不絕當如綖。","齊驱不讓策，竝駕或爭駢。","所以吾唐风，直將三代甄。","被此文物盛，由乎声诗宣。","采彼风人謠，輶軒轻似鸇。","丽者固不捨，鄙者亦爲銓。","其中有鑾戒，一一堪雕鐫。","乙夜以观之，吾君無釋焉。","遂命大司乐，度之如星躔。","播於乐府中，俾爲万代蠲。","吹彼圓丘竹，誦茲清廟弦。","不惟娛列祖，兼可格上玄。","粵予何爲者，生自江海壖。","騃騃自總角，不甘耕一壥。","諸昆指倉庫，謂我死道邊。","何爲不力農，稽古真可嘕。","遂與襏襫著，兼之籉笠全。","风吹蔓草花，颯颯盈荒田。","老牛瞪不行，力弱誰能鞭。","乃將耒與耜，竝換槧與鉛。","閱彼圖籍肆，致之千百編。","携將入蘇嶺，不就無出緣。","堆书塞低屋，添硯涸小泉。","对灯任髻爇，馮案從肘研。","苟無切玉刀，难除指上胼。","爾来五寒暑，試藝稱精專。","昌黎道未著，文教如欲騫。","其中有声病，於我如𦧝𦧴。","是敢驱頹波，归之於大川。","其文如可用，不敢佞與便。","明水在稾秸，太羹臨豆籩。","將来示时人，䝟貐垂饞涎。","亦或尚华縟，亦曾爲便嬛。","亦能制灝灝，亦解攻翩翩。","唯思逢陣敵，與彼爭後先。","避兵入句吳，窮悴祗自跧。","平原陸夫子，投刺来翩躚。","开卷读數行，爲之加敬虔。","忽窮一兩首，反顧唯曲拳。","始来遺巾幗，乃敢排戈鋋。","或爲拔幟走，或遭劘壘還。","不能收亂轍，豈暇重爲篿。","雖然未三北，亦可輸千鐉。","向来说文字，爾汝名可聯。","聖人病歿世，不患窮而蹎。","我未九品位，君無一囊錢。","相逢得何事，兩籠酬戲牋。","無顏解媮合，底事居冗員。","方知万鍾祿，不博五湖船。","夷[險]但明月，死生應白蓮。","吟餘凭几饮，釣罷偎蓑眠。","終拋峴山業，相共此留連。"]', '诗', 'shi', '', NULL, '魯望昨以五百言見貽過有褒美內揣庸陋彌增媿悚因成一千言上述吾唐文物之盛次敘相得之歡亦迭和之微旨也 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4db4777-c2bf-4eb9-b82f-823e39a6d517', '吳中苦雨因書一百韻寄魯望', '吳中苦雨因书一百韻寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["全吳臨巨溟，百里到滬瀆。","海物競駢羅，水怪爭滲漉。","狂蜃吐其氣，千尋勃然蹙。","一刷半天墨，架爲欹危屋。","怒鯨瞪相向，吹浪山轂轂。","倏忽腥杳冥，須臾坼崖谷。","帝命有嚴程，慈物有潛伏。","噓之爲玄雲，彌亙千萬幅。","直拔倚天劒，又建橫海纛。","化之爲暴雨，潨潨射平陸。","如將月窟寫，似把天河撲。","著樹勝戟支，中人過箭鏃。","龍光倏閃照，虯角搊琤觸。","此時一千里，平下天台瀑。","雷公恣其志，䃸磹裂電目。","蹋破霹靂車，折却三四輻。","雨工避罪者，必在蚊睫宿。","狂發鏗訇音，不得懈怠僇。","頃刻勢稍止，尚自傾蔌蔌。","不敢履洿處，恐蹋爛地軸。","自爾凡十日，茫然晦林麓。","只是遇滂沱，少曾逢霢霂。","伊余之廨宇，古製拙卜築。","頹檐倒菌黃，破砌頑莎綠。","只有方丈居，其中蹐且跼。","朽處或似醉，漏時又如沃。","階前平汎濫，牆下起趢趚。","唯堪著籉笠，復可乘𦨧宿。","雞犬竝淋漓，兒童但咿噢。","勃勃生濕氣，人人牢於鋦。","鬚眉漬將斷，肝膈蒸欲熟。","當庭死蘭芷，四垣盛薋菉。","解帙展斷書，拂牀安壞櫝。","跳梁老蛙黽，直向牀前浴。","蹲前但相聒，似把白丁辱。","空廚方欲炊，漬米未離䉛。","薪蒸濕不著，白晝須然燭。","汙萊既已濘，買魚不獲䱙。","竟未成麥饘，安能得粱肉。","更有陸先生，荒林抱窮蹙。","壞宅四五舍，病篠三兩束。","蓋檐低礙首，蘚地滑澾足。","注欲透承塵，濕難庇廚簏。","低摧在圭竇，索漠拋偏裻。","手指既已胼，肌膚亦將瘯。","一苞勢欲陊，將撐乏寸木。","盡日欠束薪，經時無寸粟。","[螔]蝓將入甑，蟚蜞已臨鍑。","嬌兒未十歲，枵然自啼哭。","一錢買粔籹，數里走病僕。","破碎舊鶴籠，狼籍晚蠶蔟。","千卷素書外，此外無餘蓄。","著處紵衣裂，戴次紗帽醭。","惡陰潛過午，未及烹葵菽。","吳中銅臭戶，七萬沸如臛。","嗇止甘蟹䱬，侈唯僭車服。","皆希尉吏旨，盡怕里胥錄。","低眉事庸奴，開顏納金玉。","唯到陸先生，不能分一斛。","先生之志氣，薄漢如鴻鵠。","遇善必擎跽，見才輒馳逐。","廉不受一芥，其餘安可黷。","如何鄉里輩，見之乃蝟縮。","粵予苦心者，師仰但踖踧。","受易既可注，請玄又堪卜。","百家皆搜蕩，六藝盡飜覆。","似餒見太牢，如迷遇華燭。","半年得酬唱，一日屢往復。","三秀間稂莠，九成雜巴濮。","奔命既不暇，乞降但相續。","吟詩口吻噅，把筆指節瘃。","君才既不窮，吾道由是篤。","所益諒弘多，厥交過親族。","相逢似丹漆，相望如朓肭。","論業敢並驅，量分合繼躅。","相違始兩日，忡忡想華縟。","出門泥漫漶，恨無直轅輦。","十錢賃一輪，逢上鳴斛觫。","赤脚枕書帙，訪予穿詰曲。","入門且抵掌，大噱時碌碌。","茲淋既浹旬，無乃害九穀。","予惟餓不死，得非道之福。","手中捉詩卷，語快還共讀。","解帶似歸來，脫巾若沐浴。","疎如松間篁，野甚麋對鹿。","行譚弄書籤，臥話枕棊局。","呼童具盤餐，擫衣換雞鶩。","或蒸一升麻，或煠兩把菊。","用以閱幽奇，豈能資口腹。","十分煎臯盧，半榼挽醽醁。","高談繄無盡，晝漏何太促。","我公大司諫，一切從民欲。","梅潤侵束杖，和氣生空獄。","而民當斯時，不覺有煩溽。","念澇爲之災，拜神再三告。","太陰霍然收，天地一澄肅。","燔炙既芬芬，威儀乃毣毣。","須權元化柄，用拯中夏酷。","我願薦先生，左右輔司牧。","茲雨何足云，唯思舉顏歜。"]', '["全吳臨巨溟，百里到滬瀆。","海物競駢羅，水怪爭滲漉。","狂蜃吐其氣，千尋勃然蹙。","一刷半天墨，架爲欹危屋。","怒鯨瞪相向，吹浪山轂轂。","倏忽腥杳冥，須臾坼崖谷。","帝命有嚴程，慈物有潛伏。","噓之爲玄云，彌亙千万幅。","直拔倚天劒，又建橫海纛。","化之爲暴雨，潨潨射平陸。","如將月窟寫，似把天河撲。","著樹勝戟支，中人過箭鏃。","龙光倏閃照，虯角搊琤觸。","此时一千里，平下天台瀑。","雷公恣其志，䃸磹裂電目。","蹋破霹靂车，折却三四輻。","雨工避罪者，必在蚊睫宿。","狂發鏗訇音，不得懈怠僇。","頃刻勢稍止，尚自傾蔌蔌。","不敢履洿处，恐蹋爛地軸。","自爾凡十日，茫然晦林麓。","只是遇滂沱，少曾逢霢霂。","伊余之廨宇，古製拙卜築。","頹檐倒菌黄，破砌頑莎綠。","只有方丈居，其中蹐且跼。","朽处或似醉，漏时又如沃。","階前平汎濫，牆下起趢趚。","唯堪著籉笠，复可乘𦨧宿。","雞犬竝淋漓，兒童但咿噢。","勃勃生濕氣，人人牢於鋦。","鬚眉漬將斷，肝膈蒸欲熟。","當庭死蘭芷，四垣盛薋菉。","解帙展斷书，拂牀安壞櫝。","跳梁老蛙黽，直向牀前浴。","蹲前但相聒，似把白丁辱。","空廚方欲炊，漬米未離䉛。","薪蒸濕不著，白晝須然燭。","汙萊既已濘，買鱼不獲䱙。","竟未成麦饘，安能得粱肉。","更有陸先生，荒林抱窮蹙。","壞宅四五舍，病篠三兩束。","蓋檐低礙首，蘚地滑澾足。","注欲透承塵，濕难庇廚簏。","低摧在圭竇，索漠拋偏裻。","手指既已胼，肌膚亦將瘯。","一苞勢欲陊，將撐乏寸木。","尽日欠束薪，經时無寸粟。","[螔]蝓將入甑，蟚蜞已臨鍑。","嬌兒未十歲，枵然自啼哭。","一錢買粔籹，數里走病僕。","破碎旧鹤籠，狼籍晚蠶蔟。","千卷素书外，此外無餘蓄。","著处紵衣裂，戴次紗帽醭。","惡陰潛過午，未及烹葵菽。","吳中銅臭戶，七万沸如臛。","嗇止甘蟹䱬，侈唯僭车服。","皆希尉吏旨，尽怕里胥錄。","低眉事庸奴，开顏納金玉。","唯到陸先生，不能分一斛。","先生之志氣，薄漢如鴻鵠。","遇善必擎跽，见才輒驰逐。","廉不受一芥，其餘安可黷。","如何乡里輩，见之乃蝟縮。","粵予苦心者，師仰但踖踧。","受易既可注，請玄又堪卜。","百家皆搜蕩，六藝尽飜覆。","似餒见太牢，如迷遇华燭。","半年得酬唱，一日屢往复。","三秀间稂莠，九成杂巴濮。","奔命既不暇，乞降但相續。","吟诗口吻噅，把笔指節瘃。","君才既不窮，吾道由是篤。","所益諒弘多，厥交過親族。","相逢似丹漆，相望如朓肭。","論業敢並驱，量分合繼躅。","相違始兩日，忡忡想华縟。","出门泥漫漶，恨無直轅輦。","十錢賃一輪，逢上鳴斛觫。","赤脚枕书帙，訪予穿詰曲。","入门且抵掌，大噱时碌碌。","茲淋既浹旬，無乃害九穀。","予惟餓不死，得非道之福。","手中捉诗卷，語快還共读。","解带似归来，脫巾若沐浴。","疎如松间篁，野甚麋对鹿。","行譚弄书籤，臥話枕棊局。","呼童具盤餐，擫衣換雞鶩。","或蒸一升麻，或煠兩把菊。","用以閱幽奇，豈能資口腹。","十分煎臯盧，半榼挽醽醁。","高談繄無尽，晝漏何太促。","我公大司諫，一切從民欲。","梅潤侵束杖，和氣生空獄。","而民當斯时，不覺有煩溽。","念澇爲之災，拜神再三告。","太陰霍然收，天地一澄肅。","燔炙既芬芬，威儀乃毣毣。","須權元化柄，用拯中夏酷。","我願薦先生，左右輔司牧。","茲雨何足云，唯思舉顏歜。"]', '诗', 'shi', '', NULL, '吳中苦雨因書一百韻寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d61ff8f-f4cb-48be-8200-cff2e88690ab', '初夏即事寄魯望', '初夏即事寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夏景恬且曠，遠人疾初平。","黃鳥語方熟，紫桐陰正清。","廨宇有幽處，私游無定程。","歸來閉雙關，亦忘枯與榮。","土室作深谷，蘚垣爲干城。","𢼮杉突杝架，迸筍支檐楹。","片石共坐穩，病鶴同喜晴。","癭木四五器，筇杖一兩莖。","泉爲葛天味，松作羲皇聲。","或看名畫徹，或吟閑詩成。","忽枕素琴睡，時把仙書行。","自然寡儔侶，莫說更紛爭。","具區包地髓，震澤含天英。","粵從三讓來，俊造紛然生。","顧予客茲地，薄我皆爲傖。","唯有陸夫子，盡力提客卿。","各負出俗才，俱懷超世情。","駐我一棧車，啜君數藜羹。","敲門若我訪，倒屣欣逢迎。","胡餅蒸甚熟，貊盤舉尤輕。","茗脆不禁炙，酒肥或難傾。","掃除就藤下，移榻尋虛明。","唯共陸夫子，醉與天壤幷。"]', '["夏景恬且曠，远人疾初平。","黄鸟語方熟，紫桐陰正清。","廨宇有幽处，私游無定程。","归来閉雙关，亦忘枯與榮。","土室作深谷，蘚垣爲干城。","𢼮杉突杝架，迸筍支檐楹。","片石共坐穩，病鹤同喜晴。","癭木四五器，筇杖一兩莖。","泉爲葛天味，松作羲皇声。","或看名畫徹，或吟闲诗成。","忽枕素琴睡，时把仙书行。","自然寡儔侶，莫说更紛爭。","具區包地髓，震澤含天英。","粵從三讓来，俊造紛然生。","顧予客茲地，薄我皆爲傖。","唯有陸夫子，尽力提客卿。","各負出俗才，俱懷超世情。","駐我一棧车，啜君數藜羹。","敲门若我訪，倒屣欣逢迎。","胡餅蒸甚熟，貊盤舉尤轻。","茗脆不禁炙，酒肥或难傾。","掃除就藤下，移榻尋虛明。","唯共陸夫子，醉與天壤幷。"]', '诗', 'shi', '', NULL, '初夏即事寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05735ce-598a-44ee-9a0b-0c060db02f62', '二遊詩 徐詩', '二游诗 徐诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["東莞爲著姓，奕代皆雋喆。","強學取科第，名聲盡孤揭。","自爲方州來，清操稱凜冽。","唯寫墳籍多，必云清俸絕。","宣毫利若風，剡紙光於月。","札吏指欲胼，萬通排未闋。","樓船若夏屋，欲載如垤㙞。","轉徙入吳都，縱橫礙門闑。","縹囊輕似霧，緗帙殷於血。","以此爲基構，將斯用貽厥。","重於通侯印，貴却全師節。","我愛參卿道，承家能介潔。","潮田五萬步，草屋十餘楶。","微宦不能去，歸來坐如刖。","保茲萬卷書，守慎如羈紲。","念我曾苦心，相逢無間別。","引之看祕寶，任得窮披閱。","軸閑翠鈿剝，籤古紅牙折。","帙解帶芸香，卷開和桂屑。","枕兼石鋒刃，榻共松瘡癤。","一臥寂無諠，數編看盡徹。","或攜歸廨宇，或把穿林樾。","挈過太湖風，抱宿支硎雪。","如斯未星紀，悉得分毫末。","翦除幽僻藪，滌蕩玄微窟。","學海正狂波，予頭向中𭮷。","聖人患不學，垂誡尤爲切。","苟昧古與今，何殊瘖共{目闋}。","昔之慕經史，有以傭筆札。","何況遇斯文，借之不曾輟。","吾衣任縠纑，吾食甘糠覈。","其道苟可光，斯文那自伐。","何竹青堪殺，何蒲重好截。","如能盈兼兩，便足酬飢渴。","有此競苟榮，聞之兼可噦。","東臯耨煙雨，南嶺提薇蕨。","何以謝徐君，公車不聞設。"]', '["东莞爲著姓，奕代皆雋喆。","強学取科第，名声尽孤揭。","自爲方州来，清操稱凜冽。","唯寫墳籍多，必云清俸絕。","宣毫利若风，剡紙光於月。","札吏指欲胼，万通排未闋。","楼船若夏屋，欲載如垤㙞。","轉徙入吳都，縱橫礙门闑。","縹囊轻似霧，緗帙殷於血。","以此爲基構，將斯用貽厥。","重於通侯印，貴却全師節。","我愛參卿道，承家能介潔。","潮田五万步，草屋十餘楶。","微宦不能去，归来坐如刖。","保茲万卷书，守慎如羈紲。","念我曾苦心，相逢無间別。","引之看祕寶，任得窮披閱。","軸闲翠鈿剝，籤古紅牙折。","帙解带芸香，卷开和桂屑。","枕兼石鋒刃，榻共松瘡癤。","一臥寂無諠，數編看尽徹。","或携归廨宇，或把穿林樾。","挈過太湖风，抱宿支硎雪。","如斯未星紀，悉得分毫末。","翦除幽僻藪，滌蕩玄微窟。","学海正狂波，予头向中𭮷。","聖人患不学，垂誡尤爲切。","苟昧古與今，何殊瘖共{目闋}。","昔之慕經史，有以傭笔札。","何況遇斯文，借之不曾輟。","吾衣任縠纑，吾食甘糠覈。","其道苟可光，斯文那自伐。","何竹青堪殺，何蒲重好截。","如能盈兼兩，便足酬飢渴。","有此競苟榮，闻之兼可噦。","东臯耨煙雨，南嶺提薇蕨。","何以謝徐君，公车不闻設。"]', '诗', 'shi', '', NULL, '二遊詩 徐詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9aaba6f-783b-4ca5-af11-b09bc9f40d2b', '二遊詩 任詩', '二游诗 任诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["任君恣高放，斯道能寡合。","一宅閑林泉，終身遠囂雜。","嘗聞佐浩穰，散性多儑𠉤。","歘爾解其綬，遺之如棄靸。","歸來鄉黨內，却與親朋洽。","開溪未讓丁，列第方稱甲。","入門約百步，古木聲霎霎。","廣檻小山欹，斜廊怪石夾。","白蓮倚闌楯，翠鳥緣簾押。","地勢似五瀉，巖形若三峽。","猿眠但膃肭，鳧食時啑唼。","撥荇下文竿，結藤縈桂檝。","門留醫樹客，壁倚栽花鍤。","度歲止褐衣，經旬唯白㡊。","多君方閉戶，顧我能倒屧。","請題在茅棟，留坐於石榻。","魂從清景遛，衣任煙霞裛。","階墀龜任上，枕席鷗方狎。","沼[似]頗黎[鏡]，當中見魚眨。","杯杓悉杉瘤，盤筵盡荷葉。","閑斟不置罰，閑弈無爭劫。","閑日不整冠，閑風不用箑。","以斯爲思慮，吾道寧疲薾。","衮衣競璀璨，鼓吹爭鞺鞳。","欲者解擠排，詬者能詀讘。","權豪暫飜覆，刑禍相填壓。","此時一圭竇，不肯饒閶闔。","有第可棲息，有書可漁獵。","吾欲與任君，終身以斯愜。"]', '["任君恣高放，斯道能寡合。","一宅闲林泉，終身远囂杂。","嘗闻佐浩穰，散性多儑𠉤。","歘爾解其綬，遺之如棄靸。","归来乡黨內，却與親朋洽。","开溪未讓丁，列第方稱甲。","入门約百步，古木声霎霎。","廣檻小山欹，斜廊怪石夾。","白蓮倚闌楯，翠鸟緣簾押。","地勢似五瀉，巖形若三峽。","猿眠但膃肭，鳧食时啑唼。","撥荇下文竿，結藤縈桂檝。","门留醫樹客，壁倚栽花鍤。","度歲止褐衣，經旬唯白㡊。","多君方閉戶，顧我能倒屧。","請題在茅棟，留坐於石榻。","魂從清景遛，衣任煙霞裛。","階墀龟任上，枕席鷗方狎。","沼[似]頗黎[镜]，當中见鱼眨。","杯杓悉杉瘤，盤筵尽荷葉。","闲斟不置罰，闲弈無爭劫。","闲日不整冠，闲风不用箑。","以斯爲思慮，吾道寧疲薾。","衮衣競璀璨，鼓吹爭鞺鞳。","欲者解擠排，詬者能詀讘。","權豪暫飜覆，刑禍相填壓。","此时一圭竇，不肯饒閶闔。","有第可棲息，有书可漁獵。","吾欲與任君，終身以斯愜。"]', '诗', 'shi', '', NULL, '二遊詩 任詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc6dc1d-ddd6-4e02-95dd-5f7a4ebb925c', '追和虎丘寺清遠道士詩', '追和虎丘寺清远道士诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["成道自衰周，避世窮炎漢。","荆杞雖云梗，煙霞尚容竄。","茲岑信靈異，吾懷愜流玩。","石澀古鐵鉎，嵐重輕埃漫。","松膏膩幽徑，蘋沫著孤岸。","諸蘿幄幕暗，衆鳥陶匏亂。","巖罅地中心，海光天一半。","玄猨行列歸，白雲次第散。","蟾蜍生夕景，沆瀣餘清旦。","風日采幽什，墨客學靈翰。","嗟予慕斯文，一詠復三歎。","顯晦雖不同，茲吟粗堪贊。"]', '["成道自衰周，避世窮炎漢。","荆杞雖云梗，煙霞尚容竄。","茲岑信靈異，吾懷愜流玩。","石澀古鐵鉎，嵐重轻埃漫。","松膏膩幽徑，蘋沫著孤岸。","諸蘿幄幕暗，衆鸟陶匏亂。","巖罅地中心，海光天一半。","玄猨行列归，白云次第散。","蟾蜍生夕景，沆瀣餘清旦。","风日采幽什，墨客学靈翰。","嗟予慕斯文，一詠复三歎。","显晦雖不同，茲吟粗堪贊。"]', '诗', 'shi', '', NULL, '追和虎丘寺清遠道士詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff2829e-24c7-409e-8013-c09f0c25cb1e', '追和幽獨君詩次韻 一', '追和幽独君诗次韻 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["念爾風雅魄，幽咽猶能文。","空令傷魂鳥，啼破山邊墳。"]', '["念爾风雅魄，幽咽猶能文。","空令傷魂鸟，啼破山邊墳。"]', '诗', 'shi', '', NULL, '追和幽獨君詩次韻 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5204c7b6-d771-4e57-b808-8ba53f8edf96', '追和幽獨君詩次韻 二', '追和幽独君诗次韻 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["恨劇但埋土，聲幽難放哀。","墳古春自晚，愁緒空崔嵬。","白楊老無花，枯根侵夜臺。","天高有時裂，川去何時迴？","雙睫不能濡，六藏無可摧。","不聞搴蓬事，何必深悲哉。"]', '["恨劇但埋土，声幽难放哀。","墳古春自晚，愁緒空崔嵬。","白楊老無花，枯根侵夜台。","天高有时裂，川去何时迴？","雙睫不能濡，六藏無可摧。","不闻搴蓬事，何必深悲哉。"]', '诗', 'shi', '', NULL, '追和幽獨君詩次韻 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aefc220d-ad6e-4f1b-95c7-b5f02b848cf9', '奉和魯望讀陰符經見寄', '奉和魯望读陰符經见寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["三百八十言，出自伊[祁]氏。","上以生神仙，次云立仁義。","玄機一以發，五賊紛然起。","結爲日月精，融作天地髓。","不測似陰陽，難名若鬼神。","得之升高天，失之沈厚地。","具茨雲木老，大塊煙霞委。","自顓頊以降，賊爲聖人軌。","堯乃一庶人，得之賊帝摯。","摯見其德尊，脫身授其位。","舜唯一鰥民，冗冗作什器。","得之賊帝堯，白丁作天子。","禹本刑人後，以功繼其嗣。","得之賊帝舜，用以平洚水。","自禹及文武，天機𢟉然弛。","姬公樹其綱，賊之爲聖智。","聲詩川競大，禮樂山爭峙。","爰從幽厲餘，宸極若孩穉。","九伯真犬彘，諸侯實虎兕。","五星合其耀，白日下闕里。","由是聖人生，於焉當亂紀。","黃帝之五賊，拾之若青紫。","高揮春秋筆，不可刊一字。","賊子虐甚斨，姦臣痛於箠。","至今千餘年，蚩蚩受其賜。","時代更復改，刑政崩且陊。","予將賊其道，所動多訾毀。","叔孫與臧倉，賢聖多如此。","如何黃帝機，吾得多坎躓。","縱失生前祿，亦多身後利。","我欲賊其名，垂之千萬祀。"]', '["三百八十言，出自伊[祁]氏。","上以生神仙，次云立仁義。","玄機一以發，五賊紛然起。","結爲日月精，融作天地髓。","不測似陰陽，难名若鬼神。","得之升高天，失之沈厚地。","具茨云木老，大塊煙霞委。","自顓頊以降，賊爲聖人軌。","堯乃一庶人，得之賊帝摯。","摯见其德尊，脫身授其位。","舜唯一鰥民，冗冗作什器。","得之賊帝堯，白丁作天子。","禹本刑人後，以功繼其嗣。","得之賊帝舜，用以平洚水。","自禹及文武，天機𢟉然弛。","姬公樹其綱，賊之爲聖智。","声诗川競大，禮乐山爭峙。","爰從幽厲餘，宸極若孩穉。","九伯真犬彘，諸侯實虎兕。","五星合其耀，白日下闕里。","由是聖人生，於焉當亂紀。","黄帝之五賊，拾之若青紫。","高揮春秋笔，不可刊一字。","賊子虐甚斨，姦臣痛於箠。","至今千餘年，蚩蚩受其賜。","时代更复改，刑政崩且陊。","予將賊其道，所动多訾毀。","叔孫與臧倉，賢聖多如此。","如何黄帝機，吾得多坎躓。","縱失生前祿，亦多身後利。","我欲賊其名，垂之千万祀。"]', '诗', 'shi', '', NULL, '奉和魯望讀陰符經見寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670c5810-3b22-45ed-a321-a519e6d751fe', '初夏遊楞伽精舍', '初夏游楞伽精舍', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["越舼輕似萍，漾漾出煙郭。","人聲漸疎曠，天氣忽寥廓。","伊予愜斯志，有似劀{疒}瘼。","遇勝即夷猶，逢幽且淹泊。","俄然櫂深處，虛無倚巖崿。","霜毫一道人，引我登龍閣。","當中見壽象，欲禮光紛箔。","珠幡時相鏗，恐是諸天樂。","樹杪見觚稜，林端逢赭堊。","千尋井猶在，萬祀靈不涸。","下通蛟人道，水色黮而惡。","欲照六藏驚，將窺百骸愕。","朅去山南嶺，其險如邛笮。","悠然放吾興，欲把青天摸。","紫藤垂罽珥，紅荔懸纓絡。","蘚厚滑似漦，峰尖利如鍔。","斯須到絕頂，似愈漸離㸌。","一片太湖光，只驚天漢落。","梅風脫綸帽，乳水透芒屩。","嵐姿與波彩，不動渾相著。","既不暇供應，將何以酬酢。","却來穿竹徑，似入青油幕。","穴恐水君開，龕如鬼工鑿。","窮幽入茲院，前楯臨巨壑。","遺畫龍奴獰，殘香蟲篆薄。","褫魂窺玉鏡，澄慮聞金鐸。","雲態共縈留，鳥言相許諾。","古木勢如虺，近之恐相蠚。","怒泉聲似激，聞之意爭博。","時禽倏已嘿，衆籟蕭然作。","遂令不羈性，戀此如纏縛。","念彼上人者，將生付寂寞。","曾無膚撓事，肯把心源度。","胡爲儒家流，沒齒勤且恪。","沐猴本不冠，未是謀生錯。","言行既異調，棲遲亦同託。","願力儻不遺，請作華林鶴。"]', '["越舼轻似萍，漾漾出煙郭。","人声漸疎曠，天氣忽寥廓。","伊予愜斯志，有似劀{疒}瘼。","遇勝即夷猶，逢幽且淹泊。","俄然櫂深处，虛無倚巖崿。","霜毫一道人，引我登龙閣。","當中见壽象，欲禮光紛箔。","珠幡时相鏗，恐是諸天乐。","樹杪见觚稜，林端逢赭堊。","千尋井猶在，万祀靈不涸。","下通蛟人道，水色黮而惡。","欲照六藏驚，將窺百骸愕。","朅去山南嶺，其險如邛笮。","悠然放吾兴，欲把青天摸。","紫藤垂罽珥，紅荔懸纓絡。","蘚厚滑似漦，峰尖利如鍔。","斯須到絕頂，似愈漸離㸌。","一片太湖光，只驚天漢落。","梅风脫綸帽，乳水透芒屩。","嵐姿與波彩，不动渾相著。","既不暇供應，將何以酬酢。","却来穿竹徑，似入青油幕。","穴恐水君开，龕如鬼工鑿。","窮幽入茲院，前楯臨巨壑。","遺畫龙奴獰，殘香蟲篆薄。","褫魂窺玉镜，澄慮闻金鐸。","云態共縈留，鸟言相許諾。","古木勢如虺，近之恐相蠚。","怒泉声似激，闻之意爭博。","时禽倏已嘿，衆籟蕭然作。","遂令不羈性，戀此如纏縛。","念彼上人者，將生付寂寞。","曾無膚撓事，肯把心源度。","胡爲儒家流，沒齒勤且恪。","沐猴本不冠，未是謀生錯。","言行既異調，棲遲亦同託。","願力儻不遺，請作华林鹤。"]', '诗', 'shi', '', NULL, '初夏遊楞伽精舍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7fbe91-076e-4157-9c92-ed58052c3f11', '公齋四詠 小松', '公斋四詠 小松', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["婆娑只三尺，移來白雲徑。","亭亭向空意，已解凌遼敻。","葉健似虯鬚，枝脆如鶴脛。","清音猶未成，紺彩空不定。","陰圓小芝蓋，鱗澀修荷柄。","先愁被鷃搶，預恐遭蝸病。","結根幸得地，且免離離映。","磥砢不難遇，在保晚成性。","一日造明堂，爲君當畢命。"]', '["婆娑只三尺，移来白云徑。","亭亭向空意，已解凌遼敻。","葉健似虯鬚，枝脆如鹤脛。","清音猶未成，紺彩空不定。","陰圓小芝蓋，鱗澀修荷柄。","先愁被鷃搶，預恐遭蝸病。","結根幸得地，且免離離映。","磥砢不难遇，在保晚成性。","一日造明堂，爲君當畢命。"]', '诗', 'shi', '', NULL, '公齋四詠 小松 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69632692-4e6d-48f8-91b7-652706e57d81', '公齋四詠 小桂', '公斋四詠 小桂', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一子落天上，生此青璧枝。","歘從山之幽，斸斷雲根移。","勁挺隱珪質，盤珊緹油姿。","葉彩碧髓融，花狀白毫蕤。","稜層立翠節，偃蹇樛青螭。","影澹雪霽後，香汎風和時。","吾祖在月竁，孤貞能見怡。","願老君子地，不敢辭喧卑。"]', '["一子落天上，生此青璧枝。","歘從山之幽，斸斷云根移。","勁挺隐珪質，盤珊緹油姿。","葉彩碧髓融，花狀白毫蕤。","稜層立翠節，偃蹇樛青螭。","影澹雪霽後，香汎风和时。","吾祖在月竁，孤貞能见怡。","願老君子地，不敢辞喧卑。"]', '诗', 'shi', '', NULL, '公齋四詠 小桂 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0d6fe8-c591-4099-bd8e-a9a196170245', '公齋四詠 新竹', '公斋四詠 新竹', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["笠澤多異竹，移之植後楹。","一架三百本，綠沈森冥冥。","圓緊珊瑚節，釤利翡翠翎。","儼若青帝仗，矗如紫姑屏。","槭槭微風度，漠漠輕靄生。","如神語鈞天，似樂奏洞庭。","一玩九藏冷，再聞百骸醒。","有根可以執，有𥳇可以馨。","願稟君子操，不敢先凋零。"]', '["笠澤多異竹，移之植後楹。","一架三百本，綠沈森冥冥。","圓緊珊瑚節，釤利翡翠翎。","儼若青帝仗，矗如紫姑屏。","槭槭微风度，漠漠轻靄生。","如神語鈞天，似乐奏洞庭。","一玩九藏冷，再闻百骸醒。","有根可以執，有𥳇可以馨。","願稟君子操，不敢先凋零。"]', '诗', 'shi', '', NULL, '公齋四詠 新竹 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ccbcba-402e-456d-99ad-9b3cdd21e57d', '公齋四詠 鶴屏', '公斋四詠 鹤屏', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["三幅吹空縠，孰寫仙禽狀。","䯔耳側以聽，赤精曠如望。","引吭看雲勢，翹足臨池樣。","頗似近蓐席，還如入方丈。","盡日空不鳴，窮年但相向。","未許子晉乘，難教道林放。","貌既合羽儀，骨亦符法相。","願升君子堂，不必思崑閬。"]', '["三幅吹空縠，孰寫仙禽狀。","䯔耳側以听，赤精曠如望。","引吭看云勢，翹足臨池樣。","頗似近蓐席，還如入方丈。","尽日空不鳴，窮年但相向。","未許子晉乘，难教道林放。","貌既合羽儀，骨亦符法相。","願升君子堂，不必思崑閬。"]', '诗', 'shi', '', NULL, '公齋四詠 鶴屏 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a337e6-827c-48b5-90fd-7018dc94d40c', '奉酬崔璐進士見寄次韻', '奉酬崔璐進士见寄次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["伊余幼且賤，所稟自以殊。","弱歲謬知道，有心匡皇符。","意超海上鷹，運跼轅下駒。","縱性作古文，所謂皆自如。","但恐才格劣，敢誇詞彩敷。","句句考事實，篇篇窮玄虛。","誰能變羊質，競不獲驪珠。","粵有造化手，曾開天地鑪。","文章鄴下秀，氣貌淹中儒。","展我此志業，期君持中樞。","蒼生眼穿望，勿作磻谿謨。"]', '["伊余幼且賤，所稟自以殊。","弱歲謬知道，有心匡皇符。","意超海上鷹，運跼轅下駒。","縱性作古文，所謂皆自如。","但恐才格劣，敢誇词彩敷。","句句考事實，篇篇窮玄虛。","誰能变羊質，競不獲驪珠。","粵有造化手，曾开天地鑪。","文章鄴下秀，氣貌淹中儒。","展我此志業，期君持中樞。","蒼生眼穿望，勿作磻谿謨。"]', '诗', 'shi', '', NULL, '奉酬崔璐進士見寄次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80da79e-f25c-4c88-9d4b-cfa156716170', '太湖詩 初入太湖', '太湖诗 初入太湖', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["聞有太湖名，十年未曾識。","今朝得遊汎，大笑稱平昔。","一舍行胥塘，盡日到震澤。","三萬六千頃，千頃頗黎色。","連空澹無纇，照野平絕隟。","好放青翰舟，堪弄白玉笛。","疎岑七十二，𡾼𡾼露矛戟。","悠然嘯傲去，天上搖畫艗。","西風乍獵獵，驚波罨涵碧。","倏忽雷陣吼，須臾玉崖坼。","樹動爲蜃尾，山浮似鼇脊。","落照射鴻溶，清輝蕩拋𢶉。","雲輕似可染，霞爛如堪摘。","漸暝無處泊，挽帆從所適。","枕下聞澎湃，肌上生瘮𤶬。","討異足邅迴，尋幽多阻隔。","願風與良便，吹入神仙宅。","甘將一蘊書，永事嵩山伯。"]', '["闻有太湖名，十年未曾識。","今朝得游汎，大笑稱平昔。","一舍行胥塘，尽日到震澤。","三万六千頃，千頃頗黎色。","連空澹無纇，照野平絕隟。","好放青翰舟，堪弄白玉笛。","疎岑七十二，𡾼𡾼露矛戟。","悠然嘯傲去，天上搖畫艗。","西风乍獵獵，驚波罨涵碧。","倏忽雷陣吼，須臾玉崖坼。","樹动爲蜃尾，山浮似鼇脊。","落照射鴻溶，清輝蕩拋𢶉。","云轻似可染，霞爛如堪摘。","漸暝無处泊，挽帆從所適。","枕下闻澎湃，肌上生瘮𤶬。","討異足邅迴，尋幽多阻隔。","願风與良便，吹入神仙宅。","甘將一蘊书，永事嵩山伯。"]', '诗', 'shi', '', NULL, '太湖詩 初入太湖 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6526a1c-8a89-4e43-8fee-6216d8b438b7', '太湖詩 曉次神景宮', '太湖诗 晓次神景宮', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夜半幽夢中，扁舟似鳧躍。","曉來到何許，俄倚包山脚。","三百六十丈，攢空利如削。","遐瞻但徙倚，欲上先矍鑠。","濃露濕莎裳，淺泉漸草屩。","行行未一里，節境轉寂寞。","靜徑侵泬寥，仙扉傍巖崿。","松聲正清絕，海日方照灼。","歘臨幽虛天，萬想皆擺落。","壇靈有芝菌，殿聖無鳥雀。","瓊幃自迴旋，錦旌空粲錯。","鼎氣爲龍虎，香煙混丹雘。","凝看出次雲，默聽語時鶴。","綠書不可注，雲笈應無鑰。","晴來鳥思喜，崦裏花光弱。","天籟如擊琴，泉聲似摐鐸。","清齋洞前院，敢負玄科約。","空中悉羽章，地上皆靈藥。","金醴可酣暢，玉豉堪咀嚼。","存心服燕胎，叩齒讀龍蹻。","福地七十二，茲焉永堪託。","在獸乏虎貙，於蟲不毒蠚。","嘗聞擇骨錄，仙誌非可作。","綠腸既朱髓，青肝復紫絡。","伊余乏此相，天與形貌惡。","每嗟原憲瘇，常苦齊侯瘧。","終然合委頓，剛亦慕寥廓。","三茅亦常住，竟與珪組薄。","欲問包山神，來賒少巖壑。"]', '["夜半幽梦中，扁舟似鳧躍。","晓来到何許，俄倚包山脚。","三百六十丈，攢空利如削。","遐瞻但徙倚，欲上先矍鑠。","濃露濕莎裳，淺泉漸草屩。","行行未一里，節境轉寂寞。","静徑侵泬寥，仙扉傍巖崿。","松声正清絕，海日方照灼。","歘臨幽虛天，万想皆擺落。","壇靈有芝菌，殿聖無鸟雀。","瓊幃自迴旋，錦旌空粲錯。","鼎氣爲龙虎，香煙混丹雘。","凝看出次云，默听語时鹤。","綠书不可注，云笈應無鑰。","晴来鸟思喜，崦裏花光弱。","天籟如擊琴，泉声似摐鐸。","清斋洞前院，敢負玄科約。","空中悉羽章，地上皆靈藥。","金醴可酣暢，玉豉堪咀嚼。","存心服燕胎，叩齒读龙蹻。","福地七十二，茲焉永堪託。","在獸乏虎貙，於蟲不毒蠚。","嘗闻擇骨錄，仙誌非可作。","綠腸既朱髓，青肝复紫絡。","伊余乏此相，天與形貌惡。","每嗟原憲瘇，常苦齊侯瘧。","終然合委頓，剛亦慕寥廓。","三茅亦常住，竟與珪組薄。","欲问包山神，来賒少巖壑。"]', '诗', 'shi', '', NULL, '太湖詩 曉次神景宮 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14eca7bb-1703-48a5-ad74-8e7f7b2dd114', '太湖詩 入林屋洞', '太湖诗 入林屋洞', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["齋心已三日，筋骨如煙輕。","腰下佩金獸，手中持火鈴。","幽塘四百里，中有日月精。","連亙三十六，各各爲玉京。","自非心至誠，必被神物烹。","顧余慕大道，不能惜微生。","遂招放曠侶，同作幽憂行。","其門纔函丈，初若盤薄硎。","洞氣黑昳𥄴，苔髮紅鬇鬡。","試足值坎窞，低頭避崢嶸。","攀緣不知倦，怪異焉敢驚。","匍匐一百步，稍稍策可橫。","忽然白蝙蝠，來撲松炬明。","人語散澒洞，石響高玲玎。","脚底龍蛇氣，頭上波濤聲。","有時若服匿，偪仄如見繃。","俄爾造平澹，豁然逢光晶。","金堂似鐫出，玉座如琢成。","前有方丈沼，凝碧融人[睛]。","雲漿湛不動，璚露涵而馨。","漱之恐減算，酌之必延齡。","愁爲三官責，不敢攜一{賏/缶|瓦}。","昔云夏后氏，於此藏真經。","刻之以紫琳，祕之以丹瓊。","期之以萬祀，守之以百靈。","焉得彼丈人，竊之不加刑。","石匱一以出，左神俄不扃。","禹書既云得，吳國由是傾。","蘚縫纔半尺，中有怪物腥。","欲去既嚄唶，將迴又伶俜。","却遵舊時道，半日出杳冥。","屨泥惹石髓，衣濕霑雲英。","玄籙乏仙骨，青文無絳名。","雖然入陰宮，不得朝上清。","對彼神仙窟，自厭濁俗形。","却憎造物者，遣我騎文星。"]', '["斋心已三日，筋骨如煙轻。","腰下佩金獸，手中持火鈴。","幽塘四百里，中有日月精。","連亙三十六，各各爲玉京。","自非心至誠，必被神物烹。","顧余慕大道，不能惜微生。","遂招放曠侶，同作幽憂行。","其门纔函丈，初若盤薄硎。","洞氣黑昳𥄴，苔髮紅鬇鬡。","試足值坎窞，低头避崢嶸。","攀緣不知倦，怪異焉敢驚。","匍匐一百步，稍稍策可橫。","忽然白蝙蝠，来撲松炬明。","人語散澒洞，石响高玲玎。","脚底龙蛇氣，头上波濤声。","有时若服匿，偪仄如见繃。","俄爾造平澹，豁然逢光晶。","金堂似鐫出，玉座如琢成。","前有方丈沼，凝碧融人[睛]。","云漿湛不动，璚露涵而馨。","漱之恐減算，酌之必延齡。","愁爲三官責，不敢携一{賏/缶|瓦}。","昔云夏后氏，於此藏真經。","刻之以紫琳，祕之以丹瓊。","期之以万祀，守之以百靈。","焉得彼丈人，竊之不加刑。","石匱一以出，左神俄不扃。","禹书既云得，吳国由是傾。","蘚縫纔半尺，中有怪物腥。","欲去既嚄唶，將迴又伶俜。","却遵旧时道，半日出杳冥。","屨泥惹石髓，衣濕霑云英。","玄籙乏仙骨，青文無絳名。","雖然入陰宮，不得朝上清。","对彼神仙窟，自厭濁俗形。","却憎造物者，遣我騎文星。"]', '诗', 'shi', '', NULL, '太湖詩 入林屋洞 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b292bd8c-131c-4b63-b09e-d82bbe23a65a', '太湖詩 雨中遊包山精舍', '太湖诗 雨中游包山精舍', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["松門亙五里，彩碧高下絢。","幽人共躋攀，勝事頗清便。","翣翣林上雨，隱隱湖中電。","薜帶輕束腰，荷笠低遮面。","濕屨黏煙霧，穿衣落霜霰。","笑次度巖壑，困中遇臺殿。","老僧三四人，梵字十數卷。","施稀無夏屋，境僻乏朝膳。","散髪抵泉流，支頤數雲片。","坐石忽忘起，捫蘿不知倦。","異蝶時似錦，幽禽或如鈿。","篥簩還戛刃，栟櫚自搖扇。","俗態既斗藪，野情空眷戀。","道人摘芝菌，爲予備午饌。","渴興石榴羹，飢愜胡麻飯。","如何事于役，茲遊急於傳。","却將塵土衣，一任瀑絲濺。"]', '["松门亙五里，彩碧高下絢。","幽人共躋攀，勝事頗清便。","翣翣林上雨，隐隐湖中電。","薜带轻束腰，荷笠低遮面。","濕屨黏煙霧，穿衣落霜霰。","笑次度巖壑，困中遇台殿。","老僧三四人，梵字十數卷。","施稀無夏屋，境僻乏朝膳。","散髪抵泉流，支頤數云片。","坐石忽忘起，捫蘿不知倦。","異蝶时似錦，幽禽或如鈿。","篥簩還戛刃，栟櫚自搖扇。","俗態既斗藪，野情空眷戀。","道人摘芝菌，爲予備午饌。","渴兴石榴羹，飢愜胡麻飯。","如何事于役，茲游急於傳。","却將塵土衣，一任瀑絲濺。"]', '诗', 'shi', '', NULL, '太湖詩 雨中遊包山精舍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9252b016-2f84-4b09-97e8-2f2c348f595b', '太湖詩 遊毛公壇', '太湖诗 游毛公壇', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["却上南山路，松行儼如廡。","松根礙幽徑，孱顏不能斧。","擺履跨亂雲，傾巾蹲怪樹。","三休且半日，始到毛公塢。","兩水合一澗，潨崖却爲浦。","相敵百千戟，共攂十萬鼓。","噴散日月精，射破神仙府。","唯愁絕地脈，又恐折天柱。","一窺耳目眩，耳聽雲髪豎。","次到鍊丹井，井幹翳宿莽。","下有蘂剛丹，勺之百疾愈。","凝於白獺髓，湛似桐馬乳。","黃露醒齒牙，碧黏甘胏腑。","檜異松復怪，枯疎互撐拄。","乾蛟一百丈，髐然半天舞。","下有毛公壇，壇方不盈畝。","當時雲龍篆，一片苔蘚古。","時時仙禽來，忽忽祥煙聚。","我愛周息元，忽起應明主。","三諫却歸來，迴頭唾圭組。","伊余何不幸，斯人不復覩。","如何大開口，與世爭枯腐。","將山待夸娥，以肉投䝟貐。","歘坐侵桂陰，不知已與午。","茲地足靈境，他年終結宇。","敢道萬石君，輕於一絲縷。"]', '["却上南山路，松行儼如廡。","松根礙幽徑，孱顏不能斧。","擺履跨亂云，傾巾蹲怪樹。","三休且半日，始到毛公塢。","兩水合一澗，潨崖却爲浦。","相敵百千戟，共攂十万鼓。","噴散日月精，射破神仙府。","唯愁絕地脈，又恐折天柱。","一窺耳目眩，耳听云髪豎。","次到鍊丹井，井幹翳宿莽。","下有蘂剛丹，勺之百疾愈。","凝於白獺髓，湛似桐马乳。","黄露醒齒牙，碧黏甘胏腑。","檜異松复怪，枯疎互撐拄。","乾蛟一百丈，髐然半天舞。","下有毛公壇，壇方不盈畝。","當时云龙篆，一片苔蘚古。","时时仙禽来，忽忽祥煙聚。","我愛周息元，忽起應明主。","三諫却归来，迴头唾圭組。","伊余何不幸，斯人不复覩。","如何大开口，與世爭枯腐。","將山待夸娥，以肉投䝟貐。","歘坐侵桂陰，不知已與午。","茲地足靈境，他年終結宇。","敢道万石君，轻於一絲縷。"]', '诗', 'shi', '', NULL, '太湖詩 遊毛公壇 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808bbc9f-0a70-49ce-ae59-adbf8e4e7c99', '太湖詩 三宿神景宮', '太湖诗 三宿神景宮', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["古觀岑且寂，幽人情自怡。","一來包天下，三宿湖之湄。","況此深夏夕，不逢清月姿。","玉泉浣衣後，金殿添香時。","客省高且敞，客牀蟠復奇。","石枕冷入腦，筍席寒侵肌。","氣清寐不著，起坐臨階墀。","松陰忽微照，獨見螢火芝。","素鶴警微露，白蓮明暗池。","窗櫺帶乳蘚，壁縫含雲蕤。","聞磬走魍魎，見燭奔羈雌。","沆瀣欲滴瀝，芭蕉未離披。","五更山蟬響，醒發如吹篪。","杉風忽然起，飄破步虛詞。","道客巾屨樣，上清朝禮儀。","明發作此事，豈復甘趨馳。"]', '["古观岑且寂，幽人情自怡。","一来包天下，三宿湖之湄。","況此深夏夕，不逢清月姿。","玉泉浣衣後，金殿添香时。","客省高且敞，客牀蟠复奇。","石枕冷入腦，筍席寒侵肌。","氣清寐不著，起坐臨階墀。","松陰忽微照，独见螢火芝。","素鹤警微露，白蓮明暗池。","窗櫺带乳蘚，壁縫含云蕤。","闻磬走魍魎，见燭奔羈雌。","沆瀣欲滴瀝，芭蕉未離披。","五更山蟬响，醒發如吹篪。","杉风忽然起，飄破步虛词。","道客巾屨樣，上清朝禮儀。","明發作此事，豈复甘趨驰。"]', '诗', 'shi', '', NULL, '太湖詩 三宿神景宮 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc39c77-49ee-41cb-a07a-3ce8e30b1e50', '太湖詩 以毛公泉一缾獻上諫議因寄', '太湖诗 以毛公泉一缾獻上諫議因寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["劉根昔成道，茲塢四百年。","毿毿被其體，號爲綠毛仙。","因思清[泠]汲，鑿彼岝𡿃巔。","五色既鍊矣，一勺方鏗然。","既用文武火，俄窮雌雄篇。","赤鹽撲紅霧，白華飛素煙。","服之生羽翼，倏爾沖玄天。","真隱尚有迹，厥祀將近千。","我來討靈勝，到此期終焉。","滴苦破竇淨，蘚深餘甃圓。","澄如玉髓潔，汎如金精鮮。","顏色半帶乳，氣味全和鉛。","飲之融痞蹇，濯之伸拘攣。","有時玩者觸，倏忽風雷顛。","素綆絲不短，越罌腹甚便。","汲時月液動，擔處玉漿旋。","敢獻大司諫，置之鈴閣前。","清如介潔性，滌比埽蕩權。","炙背野人興，亦思侯伯憐。","也知飲冰苦，願受一缾泉。"]', '["劉根昔成道，茲塢四百年。","毿毿被其體，號爲綠毛仙。","因思清[泠]汲，鑿彼岝𡿃巔。","五色既鍊矣，一勺方鏗然。","既用文武火，俄窮雌雄篇。","赤鹽撲紅霧，白华飞素煙。","服之生羽翼，倏爾沖玄天。","真隐尚有迹，厥祀將近千。","我来討靈勝，到此期終焉。","滴苦破竇淨，蘚深餘甃圓。","澄如玉髓潔，汎如金精鲜。","顏色半带乳，氣味全和鉛。","饮之融痞蹇，濯之伸拘攣。","有时玩者觸，倏忽风雷顛。","素綆絲不短，越罌腹甚便。","汲时月液动，擔处玉漿旋。","敢獻大司諫，置之鈴閣前。","清如介潔性，滌比埽蕩權。","炙背野人兴，亦思侯伯怜。","也知饮冰苦，願受一缾泉。"]', '诗', 'shi', '', NULL, '太湖詩 以毛公泉一缾獻上諫議因寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68860ea-63fe-4389-887d-39dddd20d5a6', '太湖詩 縹緲峰', '太湖诗 縹緲峰', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["頭戴華陽帽，手拄大夏筇。","清晨陪道侶，來上縹緲峰。","帶露齅藥蔓，和雲尋鹿蹤。","時驚𪕍𪕌鼠，飛上千丈松。","翠壁內有室，叩之虛䃔䃧。","古穴下徹海，視之寒鴻濛。","遇歇有佳思，緣危無倦容。","須臾到絕頂，似鳥穿樊籠。","恐足蹈海日，疑身凌天風。","衆岫點巨浸，四方接圓穹。","似將青螺髻，撒在明月中。","片白作越分，孤嵐爲吳宮。","一陣靉靆氣，隱隱生湖東。","激雷與波起，狂電將日紅。","礊礊雨點大，金髇轟下空。","暴光隔雲閃，髣髴亙天龍。","連拳百丈尾，下拔湖之洪。","捽爲一雪山，欲與昭回通。","移時却𢷈下，細碎衡與嵩。","神物諒不測，絕境尤難窮。","杖策下返照，漸聞仙觀鐘。","煙波濆肌骨，雲壑闐心胸。","竟死愛未足，當生且歡逢。","不然把天爵，自拜太湖公。"]', '["头戴华陽帽，手拄大夏筇。","清晨陪道侶，来上縹緲峰。","带露齅藥蔓，和云尋鹿蹤。","时驚𪕍𪕌鼠，飞上千丈松。","翠壁內有室，叩之虛䃔䃧。","古穴下徹海，視之寒鴻濛。","遇歇有佳思，緣危無倦容。","須臾到絕頂，似鸟穿樊籠。","恐足蹈海日，疑身凌天风。","衆岫点巨浸，四方接圓穹。","似將青螺髻，撒在明月中。","片白作越分，孤嵐爲吳宮。","一陣靉靆氣，隐隐生湖东。","激雷與波起，狂電將日紅。","礊礊雨点大，金髇轟下空。","暴光隔云閃，髣髴亙天龙。","連拳百丈尾，下拔湖之洪。","捽爲一雪山，欲與昭回通。","移时却𢷈下，細碎衡與嵩。","神物諒不測，絕境尤难窮。","杖策下返照，漸闻仙观鐘。","煙波濆肌骨，云壑闐心胸。","竟死愛未足，當生且歡逢。","不然把天爵，自拜太湖公。"]', '诗', 'shi', '', NULL, '太湖詩 縹緲峰 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f14dbfb-b79f-4412-96cc-1830b490191c', '太湖詩 桃花塢', '太湖诗 桃花塢', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夤緣度南嶺，盡日穿林樾。","窮深到茲塢，逸興轉超忽。","塢名雖然在，不見桃花發。","恐是武陵溪，自閉仙日月。","倚峰小精舍，當嶺殘耕垡。","將洞任迴環，把雲恣披拂。","閑禽啼叫窱，險狖眠硉矹。","微風吹重嵐，碧埃輕勃勃。","清陰減鶴睡，秀色治人渴。","敲竹鬬錚摐，弄泉爭咽嗢。","空齋蒸柏葉，野飯調石髪。","空羨塢中人，終身無履韤。"]', '["夤緣度南嶺，尽日穿林樾。","窮深到茲塢，逸兴轉超忽。","塢名雖然在，不见桃花發。","恐是武陵溪，自閉仙日月。","倚峰小精舍，當嶺殘耕垡。","將洞任迴环，把云恣披拂。","闲禽啼叫窱，險狖眠硉矹。","微风吹重嵐，碧埃轻勃勃。","清陰減鹤睡，秀色治人渴。","敲竹鬬錚摐，弄泉爭咽嗢。","空斋蒸柏葉，野飯調石髪。","空羨塢中人，終身無履韤。"]', '诗', 'shi', '', NULL, '太湖詩 桃花塢 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84cecfb3-ecc3-46a3-8f38-54c694839241', '太湖詩 明月灣', '太湖诗 明月灣', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["曉景澹無際，孤舟恣迴環。","試問最幽處，號爲明月灣。","半巖翡翠巢，望見不可攀。","柳弱下絲網，藤深垂花鬘。","松癭忽似狖，石文或如虥。","釣壇兩三處，苔老腥斒斑。","沙雨幾處霽，水禽相向閑。","野人波濤上，白屋幽深間。","曉培橘栽去，暮作魚梁還。","清泉出石砌，好樹臨柴關。","對此老且死，不知憂與患。","好境無處住，好處無境刪。","赧然不自適，脈脈當湖山。"]', '["晓景澹無際，孤舟恣迴环。","試问最幽处，號爲明月灣。","半巖翡翠巢，望见不可攀。","柳弱下絲網，藤深垂花鬘。","松癭忽似狖，石文或如虥。","釣壇兩三处，苔老腥斒斑。","沙雨幾处霽，水禽相向闲。","野人波濤上，白屋幽深间。","晓培橘栽去，暮作鱼梁還。","清泉出石砌，好樹臨柴关。","对此老且死，不知憂與患。","好境無处住，好处無境刪。","赧然不自適，脈脈當湖山。"]', '诗', 'shi', '', NULL, '太湖詩 明月灣 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc5a351-0865-4e34-be2a-ba8575dba221', '太湖詩 練瀆', '太湖诗 練瀆', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吳王厭得國，所玩終不足。","一上姑蘇臺，猶自嫌局促。","艅艎六宮鬧，艨衝後軍肅。","一陣水麝風，空中蕩平淥。","鳥困避錦帆，龍跧防鐵軸。","流蘇惹煙浪，羽葆飄巖谷。","靈境太蹂踐，因茲塞林屋。","空闊嫌太湖，崎嶇開練瀆。","三尋齾石齒，數里穿山腹。","底靜似金膏，礫碎如丹粟。","波殿鄭妲醉，蟾閣西施宿。","幾轉含煙舟，一唱來雲曲。","不知闌楯上，夜有越人鏃。","君王掩面死，嬪御不敢哭。","豔魄逐波濤，荒宮養麋鹿。","國破溝亦淺，代變草空綠。","白鳥都不知，朝眠還暮浴。"]', '["吳王厭得国，所玩終不足。","一上姑蘇台，猶自嫌局促。","艅艎六宮鬧，艨衝後軍肅。","一陣水麝风，空中蕩平淥。","鸟困避錦帆，龙跧防鐵軸。","流蘇惹煙浪，羽葆飄巖谷。","靈境太蹂踐，因茲塞林屋。","空闊嫌太湖，崎嶇开練瀆。","三尋齾石齒，數里穿山腹。","底静似金膏，礫碎如丹粟。","波殿鄭妲醉，蟾閣西施宿。","幾轉含煙舟，一唱来云曲。","不知闌楯上，夜有越人鏃。","君王掩面死，嬪御不敢哭。","豔魄逐波濤，荒宮養麋鹿。","国破溝亦淺，代变草空綠。","白鸟都不知，朝眠還暮浴。"]', '诗', 'shi', '', NULL, '太湖詩 練瀆 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67770afe-cef8-4758-aa46-bb4f73dfa2e0', '太湖詩 投龍潭', '太湖诗 投龙潭', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["龜山下最深，惡氣何洋溢。","涎水瀑龍巢，腥風卷蛟室。","曉來林岑靜，獰色如怒日。","氣涌撲炱煤，波澄埽純漆。","下有水君府，貝闕光比櫛。","左右列介臣，縱橫守鱗卒。","月中珠母見，煙際楓人出。","生犀不敢燒，水怪恐摧捽。","時有慕道者，作彼投龍術。","端巖持碧簡，齋戒揮紫筆。","兼以金蜿蜒，投之光焌律。","琴高坐赤鯉，何許縱仙逸。","我願與之遊，茲焉託靈質。"]', '["龟山下最深，惡氣何洋溢。","涎水瀑龙巢，腥风卷蛟室。","晓来林岑静，獰色如怒日。","氣涌撲炱煤，波澄埽純漆。","下有水君府，貝闕光比櫛。","左右列介臣，縱橫守鱗卒。","月中珠母见，煙際楓人出。","生犀不敢燒，水怪恐摧捽。","时有慕道者，作彼投龙術。","端巖持碧簡，斋戒揮紫笔。","兼以金蜿蜒，投之光焌律。","琴高坐赤鯉，何許縱仙逸。","我願與之游，茲焉託靈質。"]', '诗', 'shi', '', NULL, '太湖詩 投龍潭 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8732befc-eae5-4d91-bb65-215588938875', '太湖詩 孤園寺', '太湖诗 孤园寺', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["艇子小且兀，緣湖蕩白芷。","縈紆泊一碕，宛到孤園寺。","蘿島凝清陰，松門湛虛翠。","寒泉飛碧螭，古木鬬蒼兕。","鐘梵在水魄，樓臺入雲肆。","巖邊足鳴𧔢，樹杪多飛鸓。","香莎滿院落，風汎金靃靡。","靜鶴啄柏蠹，閑猱弄榅䗁。","小殿熏陸香，古經貝多紙。","老僧方瞑坐，見客還強起。","指茲正險絕，何以來到此。","先言洞壑數，次話真如理。","磬韻醒閑心，茶香凝皓齒。","巾之劫貝布，饌以栴檀餌。","數刻得清淨，終身欲依止。","可憐陶侍讀，身列丹臺位。","雅號曰勝力，亦聞師佛氏。","今日到孤園，何妨稱弟子。"]', '["艇子小且兀，緣湖蕩白芷。","縈紆泊一碕，宛到孤园寺。","蘿島凝清陰，松门湛虛翠。","寒泉飞碧螭，古木鬬蒼兕。","鐘梵在水魄，楼台入云肆。","巖邊足鳴𧔢，樹杪多飞鸓。","香莎满院落，风汎金靃靡。","静鹤啄柏蠹，闲猱弄榅䗁。","小殿熏陸香，古經貝多紙。","老僧方瞑坐，见客還強起。","指茲正險絕，何以来到此。","先言洞壑數，次話真如理。","磬韻醒闲心，茶香凝皓齒。","巾之劫貝布，饌以栴檀餌。","數刻得清淨，終身欲依止。","可怜陶侍读，身列丹台位。","雅號曰勝力，亦闻師佛氏。","今日到孤园，何妨稱弟子。"]', '诗', 'shi', '', NULL, '太湖詩 孤園寺 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d57904e1-45cd-4723-af05-0b5604cd41ba', '太湖詩 上真觀', '太湖诗 上真观', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["徑盤在山肋，繚繞窮雲端。","摘菌杖頭紫，緣崖屐齒刓。","半日到上真，洞宮知造難。","雙戶啓真景，齋心方可觀。","天鈞鳴響亮，天祿行蹣跚。","琪樹夾一徑，萬條青琅玕。","兩松峙庭際，怪狀吁可歎。","大螾騰共結，修蛇飛相盤。","皮膚坼甲胄，枝節擒貙犴。","罅處似天裂，朽中如井眢。","襹褷風聲㾌，跁跒地力痑。","根上露鉗釱，空中狂波瀾。","合時若莽蒼，闢處如轘轅。","儼對無霸陣，靜問嚴陵灘。","靈飛一以護，山都焉敢干。","兩廊潔寂歷，中殿高巑岏。","靜架九色節，閑懸十絕幡。","微風時一吹，百寶清闌珊。","昔有葉道士，位當升靈官。","欲箋紫微志，唯食虹影丹。","既逐隱龍去，道風由此殘。","猶聞絳目草，往往生空壇。","羽客兩三人，石上譚泥丸。","謂我或龍胄，粲然與之歡。","衣巾紫華冷，食次白芝寒。","自覺有真氣，恐隨風力摶。","明朝若更往，必擬隳儒冠。"]', '["徑盤在山肋，繚繞窮云端。","摘菌杖头紫，緣崖屐齒刓。","半日到上真，洞宮知造难。","雙戶啓真景，斋心方可观。","天鈞鳴响亮，天祿行蹣跚。","琪樹夾一徑，万條青琅玕。","兩松峙庭際，怪狀吁可歎。","大螾腾共結，修蛇飞相盤。","皮膚坼甲胄，枝節擒貙犴。","罅处似天裂，朽中如井眢。","襹褷风声㾌，跁跒地力痑。","根上露鉗釱，空中狂波瀾。","合时若莽蒼，闢处如轘轅。","儼对無霸陣，静问嚴陵灘。","靈飞一以護，山都焉敢干。","兩廊潔寂歷，中殿高巑岏。","静架九色節，闲懸十絕幡。","微风时一吹，百寶清闌珊。","昔有葉道士，位當升靈官。","欲箋紫微志，唯食虹影丹。","既逐隐龙去，道风由此殘。","猶闻絳目草，往往生空壇。","羽客兩三人，石上譚泥丸。","謂我或龙胄，粲然與之歡。","衣巾紫华冷，食次白芝寒。","自覺有真氣，恐隨风力摶。","明朝若更往，必擬隳儒冠。"]', '诗', 'shi', '', NULL, '太湖詩 上真觀 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0279b891-b2ed-416d-b992-6a29b0199b0f', '太湖詩 銷夏灣', '太湖诗 銷夏灣', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["太湖有曲處，其門爲兩崖。","當中數十頃，別如一天池。","號爲銷夏灣，此名無所私。","赤日莫斜照，清風多遙吹。","沙嶼埽粉墨，松竹調塤篪。","山果紅靺鞨，水苔青髬髵。","木陰厚若瓦，嚴磴滑如飴。","我來此遊息，夏景方赫曦。","一坐盤石上，肅肅寒生肌。","小艖或可汎，短策或可支。","行驚翠羽起，坐見白蓮披。","斂袖弄輕浪，解巾敵涼颸。","但有水雲見，更餘沙禽知。","京洛往來客，暍死緣奔馳。","此中便可老，焉用名利爲。"]', '["太湖有曲处，其门爲兩崖。","當中數十頃，別如一天池。","號爲銷夏灣，此名無所私。","赤日莫斜照，清风多遙吹。","沙嶼埽粉墨，松竹調塤篪。","山果紅靺鞨，水苔青髬髵。","木陰厚若瓦，嚴磴滑如飴。","我来此游息，夏景方赫曦。","一坐盤石上，肅肅寒生肌。","小艖或可汎，短策或可支。","行驚翠羽起，坐见白蓮披。","斂袖弄轻浪，解巾敵涼颸。","但有水云见，更餘沙禽知。","京洛往来客，暍死緣奔驰。","此中便可老，焉用名利爲。"]', '诗', 'shi', '', NULL, '太湖詩 銷夏灣 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60857d60-dcbd-45e9-936d-322ca0252c60', '太湖詩 包山祠', '太湖诗 包山祠', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["白雲最深處，像設盈巖堂。","村祭足茗粣，水奠多桃槳。","䇹䉦突古砌，薜荔繃頹牆。","爐灰寂不然，風送杉桂香。","積雨晦州里，流波漂稻粱。","恭惟大司諫，憫此如發狂。","命予傳明禱，祗事實不遑。","一奠若肸蠁，再祝如激揚。","出廟未半日，隔雲逢澹光。","𡾼𡾼雨點少，漸收羽林槍。","忽然山家犬，起吠白日傍。","公心與神志，相向如玄黃。","我願作一疏，奏之於穹蒼。","留神千萬祀，永福吳封疆。"]', '["白云最深处，像設盈巖堂。","村祭足茗粣，水奠多桃槳。","䇹䉦突古砌，薜荔繃頹牆。","爐灰寂不然，风送杉桂香。","積雨晦州里，流波漂稻粱。","恭惟大司諫，憫此如發狂。","命予傳明禱，祗事實不遑。","一奠若肸蠁，再祝如激揚。","出廟未半日，隔云逢澹光。","𡾼𡾼雨点少，漸收羽林槍。","忽然山家犬，起吠白日傍。","公心與神志，相向如玄黄。","我願作一疏，奏之於穹蒼。","留神千万祀，永福吳封疆。"]', '诗', 'shi', '', NULL, '太湖詩 包山祠 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2b8b8a-d4fe-4016-9534-d2cc502db923', '太湖詩 聖姑廟', '太湖诗 聖姑廟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["洛神有靈逸，古廟臨空渚。","暴雨駁丹青，荒蘿繞梁梠。","野風旋芝蓋，飢烏銜椒糈。","寂寂落楓花，時時鬬鼯鼠。","常云三五夕，盡會妍神侶。","月下留紫姑，霜中召青女。","俄然響環珮，倏爾鳴機杼。","樂至有聞時，香來無定處。","目瞪如有待，魂斷空無語。"]', '["洛神有靈逸，古廟臨空渚。","暴雨駁丹青，荒蘿繞梁梠。","野风旋芝蓋，飢烏銜椒糈。","寂寂落楓花，时时鬬鼯鼠。","常云三五夕，尽會妍神侶。","月下留紫姑，霜中召青女。","俄然响环珮，倏爾鳴機杼。","乐至有闻时，香来無定处。","目瞪如有待，魂斷空無語。"]', '诗', 'shi', '', NULL, '太湖詩 聖姑廟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('862c83e5-2a5b-49a1-922a-6f428f121bfe', '太湖詩 太湖石', '太湖诗 太湖石', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["茲山有石岸，抵浪如受屠。","雪陣千萬戰，蘚巖高下刳。","乃是天詭怪，信非人功夫。","白丁一云取，難甚網珊瑚。","厥狀復若何，鬼工不可圖。","或拳若虺蜴，或蹲如虎貙。","連絡若鉤鏁，重疊如萼跗。","或若巨人骼，或如太帝符。","胮肛篔簹筍，格磔琅玕株。","斷處露海眼，移來和沙鬚。","求之煩耄倪，載之勞舳艫。","通侯一以眄，貴却驪龍珠。","厚賜以賝賮，遠去窮京都。","五侯土山下，要爾添嵒齬。","賞玩若稱意，爵祿行斯須。","苟有王佐士，崛起於太湖。","試問欲西笑，得如茲石無。"]', '["茲山有石岸，抵浪如受屠。","雪陣千万戰，蘚巖高下刳。","乃是天詭怪，信非人功夫。","白丁一云取，难甚網珊瑚。","厥狀复若何，鬼工不可圖。","或拳若虺蜴，或蹲如虎貙。","連絡若鉤鏁，重叠如萼跗。","或若巨人骼，或如太帝符。","胮肛篔簹筍，格磔琅玕株。","斷处露海眼，移来和沙鬚。","求之煩耄倪，載之勞舳艫。","通侯一以眄，貴却驪龙珠。","厚賜以賝賮，远去窮京都。","五侯土山下，要爾添嵒齬。","賞玩若稱意，爵祿行斯須。","苟有王佐士，崛起於太湖。","試问欲西笑，得如茲石無。"]', '诗', 'shi', '', NULL, '太湖詩 太湖石 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083ae792-72f4-4c2a-9452-cd34520eafd5', '太湖詩 崦裏', '太湖诗 崦裏', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["崦裏何幽奇，膏腴二十頃。","風吹稻花香，直過龜山頂。","青苗細膩臥，白羽悠溶靜。","塍畔起鸊鵜，田中通舴艋。","幾家傍潭洞，孤戍當林嶺。","罷釣時煑菱，停繰或焙茗。","峭然八十翁，生計於此永。","苦力供征賦，怡顏過朝暝。","洞庭取異事，包山極幽景。","念爾飽得知，亦是遺民幸。"]', '["崦裏何幽奇，膏腴二十頃。","风吹稻花香，直過龟山頂。","青苗細膩臥，白羽悠溶静。","塍畔起鸊鵜，田中通舴艋。","幾家傍潭洞，孤戍當林嶺。","罷釣时煑菱，停繰或焙茗。","峭然八十翁，生計於此永。","苦力供征賦，怡顏過朝暝。","洞庭取異事，包山極幽景。","念爾飽得知，亦是遺民幸。"]', '诗', 'shi', '', NULL, '太湖詩 崦裏 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25964eb-bede-47fb-8e0b-86b43abd2c8b', '太湖詩 石板', '太湖诗 石板', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["翠石數百步，如板漂不流。","空疑水妃意，浮出青玉洲。","中若瑩龍劒，外唯疊蛇矛。","狂波忽然死，浩氣清且浮。","似將翠黛色，抹破太湖秋。","安得三五夕，攜酒櫂扁舟。","召取月夫人，嘯歌於上頭。","又恐霄景闊，虛皇拜仙侯。","欲建九錫碑，當立十二樓。","瓊文忽然下，石板誰能留。","此事少知者，唯應波上鷗。"]', '["翠石數百步，如板漂不流。","空疑水妃意，浮出青玉洲。","中若瑩龙劒，外唯叠蛇矛。","狂波忽然死，浩氣清且浮。","似將翠黛色，抹破太湖秋。","安得三五夕，携酒櫂扁舟。","召取月夫人，嘯歌於上头。","又恐霄景闊，虛皇拜仙侯。","欲建九錫碑，當立十二楼。","瓊文忽然下，石板誰能留。","此事少知者，唯應波上鷗。"]', '诗', 'shi', '', NULL, '太湖詩 石板 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac491c06-6a76-4924-b368-b4a6d74e0f5c', '奉和魯望漁具十五詠 網', '奉和魯望漁具十五詠 網', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["晚挂溪上網，暎空如霧縠。","閑來發其機，旋旋沈平綠。","下處若煙雨，牽時似崖谷。","必若遇鯤鮞，從教通一目。"]', '["晚挂溪上網，暎空如霧縠。","闲来發其機，旋旋沈平綠。","下处若煙雨，牽时似崖谷。","必若遇鯤鮞，從教通一目。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 網 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924460aa-5dba-4976-b36f-6ee7f3af2e7d', '奉和魯望漁具十五詠 罩', '奉和魯望漁具十五詠 罩', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["芒鞋下葑中，步步沈輕罩。","既爲菱浪颭，亦爲蓮泥膠。","人立獨無聲，魚煩似相抄。","滿手搦霜鱗，思歸舉輕櫂。"]', '["芒鞋下葑中，步步沈轻罩。","既爲菱浪颭，亦爲蓮泥膠。","人立独無声，鱼煩似相抄。","满手搦霜鱗，思归舉轻櫂。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 罩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0923f820-c11f-40af-a5b7-650efba21ce7', '奉和魯望漁具十五詠 𦊔', '奉和魯望漁具十五詠 𦊔', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["煙雨晚來好，東塘下𦊔去。","網小正星𣞷，舟輕欲騰翥。","誰知荇深後，恰值魚多處。","浦口更有人，停橈一延竚。"]', '["煙雨晚来好，东塘下𦊔去。","網小正星𣞷，舟轻欲腾翥。","誰知荇深後，恰值鱼多处。","浦口更有人，停橈一延竚。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 𦊔 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6f81e5-ca0c-49a6-acd4-9f75697068f1', '奉和魯望漁具十五詠 釣筒', '奉和魯望漁具十五詠 釣筒', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["籠籦截數尺，標置能幽絕。","從浮笠澤煙，任臥桐江月。","絲隨碧波漫，餌逐清灘發。","好是趁筒時，秋聲正清越。"]', '["籠籦截數尺，標置能幽絕。","從浮笠澤煙，任臥桐江月。","絲隨碧波漫，餌逐清灘發。","好是趁筒时，秋声正清越。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 釣筒 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8219492a-63cc-40c5-88a8-de401bfd8b95', '奉和魯望漁具十五詠 釣車', '奉和魯望漁具十五詠 釣车', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["得樂湖海志，不厭華輈小。","月中拋一聲，驚起灘上鳥。","心將潭底測，手把波文褭。","何處覓奔車，平波今渺渺。"]', '["得乐湖海志，不厭华輈小。","月中拋一声，驚起灘上鸟。","心將潭底測，手把波文褭。","何处覓奔车，平波今渺渺。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 釣車 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd77ec17-84d4-453e-a248-fb8221d41492', '奉和魯望漁具十五詠 漁梁', '奉和魯望漁具十五詠 漁梁', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["波際插翠筠，離離似清籞。","遊鱗到溪口，入此無逃所。","斜臨楊柳津，靜下鸕鷀侶。","編此欲何之，終焉富春渚。"]', '["波際插翠筠，離離似清籞。","游鱗到溪口，入此無逃所。","斜臨楊柳津，静下鸕鷀侶。","編此欲何之，終焉富春渚。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 漁梁 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7aeaee8-5e06-4c0e-8113-8329de82a04e', '奉和魯望漁具十五詠 叉魚', '奉和魯望漁具十五詠 叉鱼', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["列炬春溪口，平潭如不流。","照見遊泳魚，一一如清晝。","中目碎瓊碧，毀鱗殷組繡。","樂此何太荒，居然媿川后。"]', '["列炬春溪口，平潭如不流。","照见游泳鱼，一一如清晝。","中目碎瓊碧，毀鱗殷組繡。","乐此何太荒，居然媿川后。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 叉魚 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fdadc69-3539-4766-a5c5-7f85a777b079', '奉和魯望漁具十五詠 射魚', '奉和魯望漁具十五詠 射鱼', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["注矢寂不動，澄潭晴轉烘。","下窺見魚樂，怳若翔在空。","驚羽決凝碧，傷鱗浮殷紅。","堪將指杯術，授與太湖公。"]', '["注矢寂不动，澄潭晴轉烘。","下窺见鱼乐，怳若翔在空。","驚羽決凝碧，傷鱗浮殷紅。","堪將指杯術，授與太湖公。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 射魚 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50338747-2cfb-4be3-b847-4f3e2795d4bd', '奉和魯望漁具十五詠 鳴桹', '奉和魯望漁具十五詠 鳴桹', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["盡日平湖上，鳴桹仍動槳。","丁丁入波心，澄澈和清響。","鷺聽獨寂寞，魚驚昧來往。","盡水無所逃，川中有鉤黨。"]', '["尽日平湖上，鳴桹仍动槳。","丁丁入波心，澄澈和清响。","鷺听独寂寞，鱼驚昧来往。","尽水無所逃，川中有鉤黨。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 鳴桹 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd685a3-22c5-41ea-bf92-93211e08c742', '奉和魯望漁具十五詠 滬', '奉和魯望漁具十五詠 滬', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["波中植甚固，磔磔如鰕鬚。","濤頭倏爾過，數頃跳鯆䱐。","不是細羅密，自爲朝夕驅。","空憐指魚命，遣出海邊租。"]', '["波中植甚固，磔磔如鰕鬚。","濤头倏爾過，數頃跳鯆䱐。","不是細羅密，自爲朝夕驱。","空怜指鱼命，遣出海邊租。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 滬 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5352e489-b5fe-4b75-8a63-f22b5e3d957f', '奉和魯望漁具十五詠 {𥫗/穇}', '奉和魯望漁具十五詠 {𥫗/穇}', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["伐彼槎蘗枝，放於冰雪浦。","遊魚趁暖處，忽爾來相聚。","徒爲棲託心，不問庇庥主。","一旦懸鼎鑊，禍機真自取。"]', '["伐彼槎蘗枝，放於冰雪浦。","游鱼趁暖处，忽爾来相聚。","徒爲棲託心，不问庇庥主。","一旦懸鼎鑊，禍機真自取。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 {𥫗/穇} 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5693f81-8e08-4c72-8da2-0fb07de451b2', '奉和魯望漁具十五詠 種魚', '奉和魯望漁具十五詠 種鱼', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["移土湖岸邊，一半和魚子。","池中得春雨，點點活如蟻。","一月便翠鱗，終年必頳尾。","借問兩綬人，誰知種魚利。"]', '["移土湖岸邊，一半和鱼子。","池中得春雨，点点活如蟻。","一月便翠鱗，終年必頳尾。","借问兩綬人，誰知種鱼利。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 種魚 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca421c15-0402-445f-ae90-b5524996663f', '奉和魯望漁具十五詠 藥魚', '奉和魯望漁具十五詠 藥鱼', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吾無竭澤心，何用藥魚藥。","見說放溪上，點點波光惡。","食時競夷猶，死者爭紛泊。","何必重傷魚，毒涇猶可作。"]', '["吾無竭澤心，何用藥鱼藥。","见说放溪上，点点波光惡。","食时競夷猶，死者爭紛泊。","何必重傷鱼，毒涇猶可作。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 藥魚 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36c5e06-fdc7-4660-960f-f85f24a5d97b', '奉和魯望漁具十五詠 舴艋', '奉和魯望漁具十五詠 舴艋', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["闊處只三尺，翛然足吾事。","低篷挂釣車，枯蚌盛魚餌。","只好攜橈坐，唯堪蓋蓑睡。","若遣遂平生，艅艎不如是。"]', '["闊处只三尺，翛然足吾事。","低篷挂釣车，枯蚌盛鱼餌。","只好携橈坐，唯堪蓋蓑睡。","若遣遂平生，艅艎不如是。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 舴艋 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7c7c19-61f6-479e-bb53-3224a1b473e0', '奉和魯望漁具十五詠 笭箵', '奉和魯望漁具十五詠 笭箵', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["朝空笭箵去，暮實笭箵歸。","歸來倒卻魚，挂在幽窗扉。","但聞鰕蜆氣，欲生蘋藻衣。","十年佩此處，煙雨苦霏霏。"]', '["朝空笭箵去，暮實笭箵归。","归来倒卻鱼，挂在幽窗扉。","但闻鰕蜆氣，欲生蘋藻衣。","十年佩此处，煙雨苦霏霏。"]', '诗', 'shi', '', NULL, '奉和魯望漁具十五詠 笭箵 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07236cfa-77ae-46ff-9008-8bccf39e8cfd', '添魚具詩 魚菴', '添鱼具诗 鱼菴', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["菴中只方丈，恰稱幽人住。","枕上悉漁經，門前空釣具。","束竿時倚壁，曬網還侵戶。","上浻有楊顒，須留往來路。"]', '["菴中只方丈，恰稱幽人住。","枕上悉漁經，门前空釣具。","束竿时倚壁，曬網還侵戶。","上浻有楊顒，須留往来路。"]', '诗', 'shi', '', NULL, '添魚具詩 魚菴 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97522408-7b61-4fb6-a4d3-2c5c4fef4bb7', '添魚具詩 釣磯', '添鱼具诗 釣磯', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["盤灘一片石，置我山居足。","窪處著筣笓，竅中維[𦨧]䑿。","多逢沙鳥污，愛彼潭雲觸。","狂奴臥此多，所以蹋帝腹。"]', '["盤灘一片石，置我山居足。","窪处著筣笓，竅中維[𦨧]䑿。","多逢沙鸟污，愛彼潭云觸。","狂奴臥此多，所以蹋帝腹。"]', '诗', 'shi', '', NULL, '添魚具詩 釣磯 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc482b1-4b6f-4c9a-a661-042e99f97444', '添魚具詩 蓑衣', '添鱼具诗 蓑衣', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一領蓑正新，著來沙塢中。","隔溪遙望見，疑是綠毛翁。","襟色裛䐑靄，袖香䙰褷風。","前頭不施衮，何以爲三公。"]', '["一領蓑正新，著来沙塢中。","隔溪遙望见，疑是綠毛翁。","襟色裛䐑靄，袖香䙰褷风。","前头不施衮，何以爲三公。"]', '诗', 'shi', '', NULL, '添魚具詩 蓑衣 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f93aa0-6043-4c79-ac62-f2d7ac2db615', '添魚具詩 篛笠', '添鱼具诗 篛笠', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["圓似寫月魂，輕如織煙翠。","涔涔向上雨，不亂窺魚思。","攜來沙日微，挂處江風起。","縱帶二梁冠，終身不忘爾。"]', '["圓似寫月魂，轻如织煙翠。","涔涔向上雨，不亂窺鱼思。","携来沙日微，挂处江风起。","縱带二梁冠，終身不忘爾。"]', '诗', 'shi', '', NULL, '添魚具詩 篛笠 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c93a65-c66f-4f31-9f58-94ffdcbd0642', '添魚具詩 背篷', '添鱼具诗 背篷', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["儂家背篷樣，似箇大龜甲。","雨中跼蹐時，一向聽霎霎。","甘從魚不見，亦任鷗相狎。","深擁竟無言，空成睡齁䶎。"]', '["儂家背篷樣，似箇大龟甲。","雨中跼蹐时，一向听霎霎。","甘從鱼不见，亦任鷗相狎。","深擁竟無言，空成睡齁䶎。"]', '诗', 'shi', '', NULL, '添魚具詩 背篷 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317643c0-649e-4e9e-8dea-ea2c05b6b53d', '奉和魯望樵人十詠 樵谿', '奉和魯望樵人十詠 樵谿', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何時有此谿，應便生幽木。","橡實養山禽，藤花蒙澗鹿。","不止產蒸薪，願當歌棫樸。","君知天意無，以此安吾族。"]', '["何时有此谿，應便生幽木。","橡實養山禽，藤花蒙澗鹿。","不止產蒸薪，願當歌棫樸。","君知天意無，以此安吾族。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵谿 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551e2d03-94a5-4966-990f-47d8a4da474d', '奉和魯望樵人十詠 樵家', '奉和魯望樵人十詠 樵家', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["空山最深處，太古兩三家。","雲蘿共夙世，猨鳥同生涯。","衣服濯春泉，盤餐烹野花。","居茲老復老，不解歎年華。"]', '["空山最深处，太古兩三家。","云蘿共夙世，猨鸟同生涯。","衣服濯春泉，盤餐烹野花。","居茲老复老，不解歎年华。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵家 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3119c886-e65e-4d5a-9ee1-916135428063', '奉和魯望樵人十詠 樵叟', '奉和魯望樵人十詠 樵叟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["不曾照青鏡，豈解傷華髪。","至老未息肩，至今無病骨。","家風是林嶺，世祿爲薇蕨。","所以兩大夫，天年自爲伐。"]', '["不曾照青镜，豈解傷华髪。","至老未息肩，至今無病骨。","家风是林嶺，世祿爲薇蕨。","所以兩大夫，天年自爲伐。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵叟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c528323-f4f5-426c-8bb4-b0f3866af9f4', '奉和魯望樵人十詠 樵子', '奉和魯望樵人十詠 樵子', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["相約晚樵去，跳踉上山路。","將花餌鹿麛，以果投猨父。","束薪白雲濕，負擔春日暮。","何不壽童烏，果爲玄所誤。"]', '["相約晚樵去，跳踉上山路。","將花餌鹿麛，以果投猨父。","束薪白云濕，負擔春日暮。","何不壽童烏，果爲玄所誤。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵子 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c94d26-6b15-4aed-9875-04c17cd5277c', '奉和魯望樵人十詠 樵徑', '奉和魯望樵人十詠 樵徑', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蒙蘢中一徑，繞在千峰裏。","歇處遇松根，危中值石齒。","花穿枲衣落，雲拂芒鞋起。","自古行此途，不聞顛與墜。"]', '["蒙蘢中一徑，繞在千峰裏。","歇处遇松根，危中值石齒。","花穿枲衣落，云拂芒鞋起。","自古行此途，不闻顛與墜。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵徑 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733668b7-7ddb-4b28-ba14-12377e0a1e91', '奉和魯望樵人十詠 樵斧', '奉和魯望樵人十詠 樵斧', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["腰間插大柯，直入深谿裏。","空林伐一聲，幽鳥相呼起。","倒樹去李父，傾巢啼木魅。","不知仗鉞者，除害誰如此。"]', '["腰间插大柯，直入深谿裏。","空林伐一声，幽鸟相呼起。","倒樹去李父，傾巢啼木魅。","不知仗鉞者，除害誰如此。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵斧 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2ddf3c-aeb4-472a-aee5-16646073492c', '奉和魯望樵人十詠 樵擔', '奉和魯望樵人十詠 樵擔', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["不敢量樵重，唯知益薪束。","軋軋下山時，彎彎向身曲。","清泉洗得潔，翠靄侵來綠。","看取荷戈人，誰能似吾屬。"]', '["不敢量樵重，唯知益薪束。","軋軋下山时，彎彎向身曲。","清泉洗得潔，翠靄侵来綠。","看取荷戈人，誰能似吾屬。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵擔 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59874232-4f7c-49fe-a539-f76a57d6337a', '奉和魯望樵人十詠 樵風', '奉和魯望樵人十詠 樵风', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["野船渡樵客，來往平波中。","縱橫清飆吹，旦暮歸期同。","蘋光惹衣白，蓮影涵薪紅。","吾當請封爾，直作鏡湖公。"]', '["野船渡樵客，来往平波中。","縱橫清飆吹，旦暮归期同。","蘋光惹衣白，蓮影涵薪紅。","吾當請封爾，直作镜湖公。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵風 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b2bb4c1-f4a6-4de2-9678-ad73944df316', '奉和魯望樵人十詠 樵火', '奉和魯望樵人十詠 樵火', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["山客地爐裏，然薪如陽輝。","松膏作𣺫瀡，杉子爲珠璣。","響誤擊刺鬧，燄疑彗孛飛。","傍邊煖白酒，不覺瀑冰垂。"]', '["山客地爐裏，然薪如陽輝。","松膏作𣺫瀡，杉子爲珠璣。","响誤擊刺鬧，燄疑彗孛飞。","傍邊煖白酒，不覺瀑冰垂。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵火 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62723f3d-40a0-4599-8ba6-3bba6dbf8ad2', '奉和魯望樵人十詠 樵歌', '奉和魯望樵人十詠 樵歌', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["此曲太古音，由來無管奏。","多云採樵樂，或說林泉候。","一唱凝閑雲，再謠悲顧獸。","若遇採詩人，誣辭收鄙陋。"]', '["此曲太古音，由来無管奏。","多云採樵乐，或说林泉候。","一唱凝闲云，再謠悲顧獸。","若遇採诗人，誣辞收鄙陋。"]', '诗', 'shi', '', NULL, '奉和魯望樵人十詠 樵歌 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32520991-203d-43ca-b5dd-c4e4635d7f49', '酒中十詠 酒星', '酒中十詠 酒星', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["誰遣酒旗耀，天文列其位。","彩微嘗似酣，芒弱偏如醉。","唯憂犯帝座，只恐騎天駟。","若遇卷舌星，讒君應墮地。"]', '["誰遣酒旗耀，天文列其位。","彩微嘗似酣，芒弱偏如醉。","唯憂犯帝座，只恐騎天駟。","若遇卷舌星，讒君應墮地。"]', '诗', 'shi', '', NULL, '酒中十詠 酒星 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7e2e071-b2f5-41ef-9246-9842db2b879d', '酒中十詠 酒泉', '酒中十詠 酒泉', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["羲皇有玄酒，滋味何太薄。","玉液是澆漓，金沙乃糟粕。","春從野鳥沽，晝仍閑猨酌。","我願葬茲泉，醉魂似鳧躍。"]', '["羲皇有玄酒，滋味何太薄。","玉液是澆漓，金沙乃糟粕。","春從野鸟沽，晝仍闲猨酌。","我願葬茲泉，醉魂似鳧躍。"]', '诗', 'shi', '', NULL, '酒中十詠 酒泉 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9e2678-2618-4b8e-b5c6-87bab6c9a356', '酒中十詠 酒篘', '酒中十詠 酒篘', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["翠{𥫗/筏}初織來，或如古魚器。","新從山下買，靜向甔中試。","輕可網金醅，疎能容玉蟻。","自此好成功，無貽我罍恥。"]', '["翠{𥫗/筏}初织来，或如古鱼器。","新從山下買，静向甔中試。","轻可網金醅，疎能容玉蟻。","自此好成功，無貽我罍恥。"]', '诗', 'shi', '', NULL, '酒中十詠 酒篘 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6fc5420-ad3b-4086-bc6b-f79bcc49253e', '酒中十詠 酒牀', '酒中十詠 酒牀', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["糟牀帶松節，酒膩肥如羜。","滴滴連有聲，空疑杜康語。","開眉既壓後，染指偷嘗處。","自此得公田，不過渾種黍。"]', '["糟牀带松節，酒膩肥如羜。","滴滴連有声，空疑杜康語。","开眉既壓後，染指偷嘗处。","自此得公田，不過渾種黍。"]', '诗', 'shi', '', NULL, '酒中十詠 酒牀 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e5501e-090e-4bed-a356-a302ce1edc3c', '酒中十詠 酒壚', '酒中十詠 酒壚', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["紅壚高幾尺，頗稱幽人意。","火作縹醪香，灰爲冬醷氣。","有鎗盡龍頭，有主皆犢鼻。","倘得作杜根，傭保何足媿。"]', '["紅壚高幾尺，頗稱幽人意。","火作縹醪香，灰爲冬醷氣。","有鎗尽龙头，有主皆犢鼻。","倘得作杜根，傭保何足媿。"]', '诗', 'shi', '', NULL, '酒中十詠 酒壚 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b577461c-313a-465c-996c-0dfe80636c70', '酒中十詠 酒樓', '酒中十詠 酒楼', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鉤楯跨通衢，喧鬧當九市。","金罍瀲灩後，玉斝紛綸起。","舞蝶傍應酣，啼鶯聞亦醉。","野客莫登臨，相讎多失意。"]', '["鉤楯跨通衢，喧鬧當九市。","金罍瀲灩後，玉斝紛綸起。","舞蝶傍應酣，啼鶯闻亦醉。","野客莫登臨，相讎多失意。"]', '诗', 'shi', '', NULL, '酒中十詠 酒樓 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b2bcb6e-f0c9-468f-8b76-8f046f9a62e0', '酒中十詠 酒旗', '酒中十詠 酒旗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["青幟闊數尺，懸於往來道。","多爲風所颺，時見酒名號。","拂拂野橋幽，翻翻江市好。","雙眸復何事，終竟望君老。"]', '["青幟闊數尺，懸於往来道。","多爲风所颺，时见酒名號。","拂拂野橋幽，翻翻江市好。","雙眸复何事，終竟望君老。"]', '诗', 'shi', '', NULL, '酒中十詠 酒旗 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a88ca38-b14b-47c3-ade0-23735290db46', '酒中十詠 酒樽', '酒中十詠 酒樽', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["犧樽一何古，我抱期幽客。","少恐消醍醐，滿擬烘琥珀。","猨窺曾撲瀉，鳥蹋經攲仄。","度度醒來看，皆如死生隔。"]', '["犧樽一何古，我抱期幽客。","少恐消醍醐，满擬烘琥珀。","猨窺曾撲瀉，鸟蹋經攲仄。","度度醒来看，皆如死生隔。"]', '诗', 'shi', '', NULL, '酒中十詠 酒樽 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7f7667-995b-4968-9d3b-3ff30f07a508', '酒中十詠 酒城', '酒中十詠 酒城', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬仞峻爲城，沈酣浸其俗。","香侵井幹過，味染濠波淥。","朝傾踰百榼，暮壓幾千斛。","吾將隸此中，但爲閽者足。"]', '["万仞峻爲城，沈酣浸其俗。","香侵井幹過，味染濠波淥。","朝傾踰百榼，暮壓幾千斛。","吾將隸此中，但爲閽者足。"]', '诗', 'shi', '', NULL, '酒中十詠 酒城 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a23c9a-4517-48b2-b75e-c4f8694719e6', '酒中十詠 酒鄉', '酒中十詠 酒乡', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何人置此鄉，杳在天皇外。","有事忘哀樂，有時忘顯晦。","如尋罔象歸，似與希夷會。","從此共君遊，無煩用冠帶。"]', '["何人置此乡，杳在天皇外。","有事忘哀乐，有时忘显晦。","如尋罔象归，似與希夷會。","從此共君游，無煩用冠带。"]', '诗', 'shi', '', NULL, '酒中十詠 酒鄉 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1853477b-9f34-463b-9b58-07f7d4391f74', '奉和添酒中六詠 酒池', '奉和添酒中六詠 酒池', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["八齊競奔注，不知深幾丈。","竹葉島紆徐，鳧花波蕩漾。","醺應爛地軸，浸可柔天壤。","以此獻吾君，願銘於[几]杖。"]', '["八齊競奔注，不知深幾丈。","竹葉島紆徐，鳧花波蕩漾。","醺應爛地軸，浸可柔天壤。","以此獻吾君，願銘於[几]杖。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒池 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8905612-cdb1-4a87-aae0-d8b78b63d8f2', '奉和添酒中六詠 酒龍', '奉和添酒中六詠 酒龙', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["銅爲蚴蟉鱗，鑄作鱙𬵩角。","吐處百里雷，瀉時千丈壑。","初疑潛苑囿，忽似拏寥廓。","遂使銅雀臺，香消野花落。"]', '["銅爲蚴蟉鱗，鑄作鱙𬵩角。","吐处百里雷，瀉时千丈壑。","初疑潛苑囿，忽似拏寥廓。","遂使銅雀台，香消野花落。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒龍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100b8969-f87d-4282-ada2-63ac4dd1a2fc', '奉和添酒中六詠 酒甕', '奉和添酒中六詠 酒甕', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["堅淨不苦窳，陶於醉封疆。","臨溪刷舊痕，隔屋聞新香。","移來近麴室，倒處臨糟牀。","所嗟無比鄰，余亦能偷嘗。"]', '["堅淨不苦窳，陶於醉封疆。","臨溪刷旧痕，隔屋闻新香。","移来近麴室，倒处臨糟牀。","所嗟無比鄰，余亦能偷嘗。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒甕 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2517bc7-4894-471b-876b-290258033dd6', '奉和添酒中六詠 酒船', '奉和添酒中六詠 酒船', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["剡桂復刳蘭，陶陶任行樂。","但知涵泳好，不計風濤惡。","嘗行麴封內，稍繫糟丘泊。","東海如可傾，乘之就斟酌。"]', '["剡桂复刳蘭，陶陶任行乐。","但知涵泳好，不計风濤惡。","嘗行麴封內，稍繫糟丘泊。","东海如可傾，乘之就斟酌。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒船 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece2a87b-53be-450c-a653-09c733bb85fa', '奉和添酒中六詠 酒鎗', '奉和添酒中六詠 酒鎗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["象鼎格仍高，其中不烹餁。","唯將煮濁醪，用以資酣飲。","偏宜旋樵火，稍近餘酲枕。","若得伴琴書，吾將著閑品。"]', '["象鼎格仍高，其中不烹餁。","唯將煮濁醪，用以資酣饮。","偏宜旋樵火，稍近餘酲枕。","若得伴琴书，吾將著闲品。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒鎗 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d1a9a4-23a1-427e-b414-23f78992c4e1', '奉和添酒中六詠 酒杯', '奉和添酒中六詠 酒杯', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["昔有嵇氏子，龍章而鳳姿。","手揮五弦罷，聊復一樽持。","但取性澹泊，不知味醇醨。","茲器不復見，家家唯玉巵。"]', '["昔有嵇氏子，龙章而鳳姿。","手揮五弦罷，聊复一樽持。","但取性澹泊，不知味醇醨。","茲器不复见，家家唯玉巵。"]', '诗', 'shi', '', NULL, '奉和添酒中六詠 酒杯 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6531a82b-78e5-4182-b59d-01cb0031652f', '茶中雜詠 茶塢', '茶中杂詠 茶塢', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["閑尋堯氏山，遂入深深塢。","種荈已成園，栽葭寧記畝。","石窪泉似掬，巖罅雲如縷。","好是夏初時，白花滿煙雨。"]', '["闲尋堯氏山，遂入深深塢。","種荈已成园，栽葭寧記畝。","石窪泉似掬，巖罅云如縷。","好是夏初时，白花满煙雨。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶塢 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bb2b2e-a58b-4ec4-9a06-a3bead15f31d', '茶中雜詠 茶人', '茶中杂詠 茶人', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["生於顧渚山，老在漫石塢。","語氣爲茶荈，衣香是煙霧。","庭從𣟤子遮，果任獳師虜。","日晚相笑歸，腰間佩輕蔞。"]', '["生於顧渚山，老在漫石塢。","語氣爲茶荈，衣香是煙霧。","庭從𣟤子遮，果任獳師虜。","日晚相笑归，腰间佩轻蔞。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶人 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a693bd-67ff-4859-878b-dccb248a932f', '茶中雜詠 茶筍', '茶中杂詠 茶筍', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["褎然三五寸，生必依巖洞。","寒恐結紅鉛，暖疑銷紫汞。","圓如玉軸光，脆似瓊英凍。","每爲遇之疎，南山挂幽夢。"]', '["褎然三五寸，生必依巖洞。","寒恐結紅鉛，暖疑銷紫汞。","圓如玉軸光，脆似瓊英凍。","每爲遇之疎，南山挂幽梦。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶筍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aad6a19-a3f0-4b7b-96e4-ca60577a02a2', '茶中雜詠 茶籯', '茶中杂詠 茶籯', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["筤篣曉攜去，驀箇山桑塢。","開時送紫茗，負處沾清露。","歇把傍雲泉，歸將挂煙樹。","滿此是生涯，黃金何足數。"]', '["筤篣晓携去，驀箇山桑塢。","开时送紫茗，負处沾清露。","歇把傍云泉，归將挂煙樹。","满此是生涯，黄金何足數。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶籯 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1abdf29-11c6-4c11-9f7a-7d4748cecbc1', '茶中雜詠 茶舍', '茶中杂詠 茶舍', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["陽崖枕白屋，幾口嬉嬉活。","棚上汲紅泉，焙前蒸紫蕨。","乃翁研茗後，中婦拍茶歇。","相向掩柴扉，清香滿山月。"]', '["陽崖枕白屋，幾口嬉嬉活。","棚上汲紅泉，焙前蒸紫蕨。","乃翁研茗後，中婦拍茶歇。","相向掩柴扉，清香满山月。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶舍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d40753-e7b5-40fb-92f5-4e3a14d3c97d', '茶中雜詠 茶竈', '茶中杂詠 茶竈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["南山茶事動，竈起巖根傍。","水煮石髪氣，薪然杉脂香。","青瓊蒸後凝，綠髓炊來光。","如何重辛苦，一一輸膏粱。"]', '["南山茶事动，竈起巖根傍。","水煮石髪氣，薪然杉脂香。","青瓊蒸後凝，綠髓炊来光。","如何重辛苦，一一輸膏粱。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶竈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a7fd54e-7707-499a-8084-a4d21c94bfad', '茶中雜詠 茶焙', '茶中杂詠 茶焙', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鑿彼碧巖下，恰應深二尺。","泥易帶雲根，燒難礙石脉。","初能燥金餅，漸見乾瓊液。","九里共杉林，相望在山側。"]', '["鑿彼碧巖下，恰應深二尺。","泥易带云根，燒难礙石脉。","初能燥金餅，漸见乾瓊液。","九里共杉林，相望在山側。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶焙 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7899d0fd-0839-4e00-a03f-c45376fad617', '茶中雜詠 茶鼎', '茶中杂詠 茶鼎', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["龍舒有良匠，鑄此佳樣成。","立作菌蠢勢，煎爲潺湲聲。","草堂暮雲陰，松窗殘雪明。","此時勺複茗，野語知逾清。"]', '["龙舒有良匠，鑄此佳樣成。","立作菌蠢勢，煎爲潺湲声。","草堂暮云陰，松窗殘雪明。","此时勺複茗，野語知逾清。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶鼎 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc40a1fe-6eae-45aa-b5fd-71025c3eef81', '茶中雜詠 茶甌', '茶中杂詠 茶甌', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["邢客與越人，皆能造茲器。","圓似月魂墮，輕如雲魄起。","棗花勢旋眼，蘋沫香沾齒。","松下時一看，支公亦如此。"]', '["邢客與越人，皆能造茲器。","圓似月魂墮，轻如云魄起。","棗花勢旋眼，蘋沫香沾齒。","松下时一看，支公亦如此。"]', '诗', 'shi', '', NULL, '茶中雜詠 茶甌 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f8f8b4-40f4-4288-8f64-840ffb20fb09', '茶中雜詠 煑茶', '茶中杂詠 煑茶', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["香泉一合乳，煎作連珠沸。","時看蟹目濺，乍見魚鱗起。","聲疑松帶雨，餑恐生煙翠。","尚把瀝中山，必無千日醉。"]', '["香泉一合乳，煎作連珠沸。","时看蟹目濺，乍见鱼鱗起。","声疑松带雨，餑恐生煙翠。","尚把瀝中山，必無千日醉。"]', '诗', 'shi', '', NULL, '茶中雜詠 煑茶 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22f093a-6cc6-4af0-9445-fe3e1fdea6fa', '石榴歌', '石榴歌', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蟬噪秋枝槐葉黃，石榴香老愁寒霜。","流霞包染紫鸚粟，黃蠟紙裹紅瓠房。","玉刻冰壺含露濕，斕斑似帶湘娥泣。","蕭孃初嫁嗜甘酸，嚼破水精千萬粒。"]', '["蟬噪秋枝槐葉黄，石榴香老愁寒霜。","流霞包染紫鸚粟，黄蠟紙裹紅瓠房。","玉刻冰壺含露濕，斕斑似带湘娥泣。","蕭孃初嫁嗜甘酸，嚼破水精千万粒。"]', '诗', 'shi', '', NULL, '石榴歌 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9b684e-9e1e-4d82-b0b0-8e76bd209d02', '奉和魯望四明山九題 石窗', '奉和魯望四明山九題 石窗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["窗開自真宰，四達見蒼涯。","苔染渾成綺，雲漫便當紗。","櫺中空吐月，扉際不扃霞。","未會通何處，應憐玉女家。"]', '["窗开自真宰，四達见蒼涯。","苔染渾成綺，云漫便當紗。","櫺中空吐月，扉際不扃霞。","未會通何处，應怜玉女家。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 石窗 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9baba1b-a54b-4feb-a0a4-5eb9aea75d07', '奉和魯望四明山九題 過雲', '奉和魯望四明山九題 過云', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["粉洞二十里，當中幽客行。","片時迷鹿迹，寸步隔人聲。","以杖探虛翠，將襟惹薄明。","經時未過得，恐是入層城。"]', '["粉洞二十里，當中幽客行。","片时迷鹿迹，寸步隔人声。","以杖探虛翠，將襟惹薄明。","經时未過得，恐是入層城。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 過雲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b74dbb59-cd92-4eda-b4e2-982602fbc12d', '奉和魯望四明山九題 雲南', '奉和魯望四明山九題 云南', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雲南背一川，無雁到峰前。","墟里生紅藥，人家發白泉。","兒童皆似古，婚嫁盡如仙。","共作真官戶，無由稅石田。"]', '["云南背一川，無雁到峰前。","墟里生紅藥，人家發白泉。","兒童皆似古，婚嫁尽如仙。","共作真官戶，無由稅石田。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 雲南 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf864b37-32a6-458f-969e-d01bbfa0752a', '奉和魯望四明山九題 雲北', '奉和魯望四明山九題 云北', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雲北晝冥冥，空疑背壽星。","犬能諳藥氣，人解寫芝形。","野歇遇松蓋，醉書逢石屏。","焚香住此地，應得入金庭。"]', '["云北晝冥冥，空疑背壽星。","犬能諳藥氣，人解寫芝形。","野歇遇松蓋，醉书逢石屏。","焚香住此地，應得入金庭。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 雲北 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a849f6ab-75ff-4f19-b10c-a646a285687a', '奉和魯望四明山九題 鹿亭', '奉和魯望四明山九題 鹿亭', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鹿羣多此住，因構白雲楣。","待侶傍花久，引麛穿竹遲。","經時掊玉澗，盡日嗅金芝。","爲在石窗下，成仙自不知。"]', '["鹿羣多此住，因構白云楣。","待侶傍花久，引麛穿竹遲。","經时掊玉澗，尽日嗅金芝。","爲在石窗下，成仙自不知。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 鹿亭 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('493bda0b-6e9e-4200-bc73-43bc5d431050', '奉和魯望四明山九題 樊榭', '奉和魯望四明山九題 樊榭', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["主人成列仙，故榭獨依然。","石洞鬨人笑，松聲驚鹿眠。","井香爲大藥，和語是靈篇。","欲買重棲隱，雲峰不售錢。"]', '["主人成列仙，故榭独依然。","石洞鬨人笑，松声驚鹿眠。","井香爲大藥，和語是靈篇。","欲買重棲隐，云峰不售錢。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 樊榭 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76daf61a-1ddd-437b-a6c9-acbfdfd1eeba', '奉和魯望四明山九題 潺湲洞', '奉和魯望四明山九題 潺湲洞', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["陰宮何處淵，到此洞潺湲。","敲碎一輪月，鎔銷半段天。","響高吹谷動，勢急歕雲旋。","料得深秋夜，臨流盡古仙。"]', '["陰宮何处淵，到此洞潺湲。","敲碎一輪月，鎔銷半段天。","响高吹谷动，勢急歕云旋。","料得深秋夜，臨流尽古仙。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 潺湲洞 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c62b41a-b3a8-4258-b69d-9534a99d7312', '奉和魯望四明山九題 青櫺子', '奉和魯望四明山九題 青櫺子', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["山風熟異果，應是供真仙。","味似雲腴美，形如玉腦圓。","銜來多野鶴，落處半靈泉。","必共玄都柰，花開不記年。"]', '["山风熟異果，應是供真仙。","味似云腴美，形如玉腦圓。","銜来多野鹤，落处半靈泉。","必共玄都柰，花开不記年。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 青櫺子 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('096d9c8d-2e80-4c69-ac8e-7f2193a89d85', '奉和魯望四明山九題 鞠侯', '奉和魯望四明山九題 鞠侯', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["堪羨鞠侯國，碧巖千萬重。","煙蘿爲印綬，雲壑是隄封。","泉遣狙公護，果教𤟤子供。","爾徒如不死，應得躡玄蹤。"]', '["堪羨鞠侯国，碧巖千万重。","煙蘿爲印綬，云壑是隄封。","泉遣狙公護，果教𤟤子供。","爾徒如不死，應得躡玄蹤。"]', '诗', 'shi', '', NULL, '奉和魯望四明山九題 鞠侯 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd8167d-1057-4fdb-a360-208c42c32851', '五貺詩 五瀉舟', '五貺诗 五瀉舟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何事有青錢，因人買釣船。","闊容兼餌坐，深許共蓑眠。","短好隨朱鷺，輕堪倚白蓮。","自知無用處，卻寄五湖仙。"]', '["何事有青錢，因人買釣船。","闊容兼餌坐，深許共蓑眠。","短好隨朱鷺，轻堪倚白蓮。","自知無用处，卻寄五湖仙。"]', '诗', 'shi', '', NULL, '五貺詩 五瀉舟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d0188a8-2300-4858-8e15-fb0f67c325db', '五貺詩 華頂杖', '五貺诗 华頂杖', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["金庭仙樹枝，道客自攜持。","探洞求丹粟，挑雲覓白芝。","量泉將濯足，闌鶴把支頤。","以此將爲贈，惟君盡得知。"]', '["金庭仙樹枝，道客自携持。","探洞求丹粟，挑云覓白芝。","量泉將濯足，闌鹤把支頤。","以此將爲贈，惟君尽得知。"]', '诗', 'shi', '', NULL, '五貺詩 華頂杖 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6faf0a2-4c5d-4edf-a9d3-85c1b44cb556', '五貺詩 太湖硯', '五貺诗 太湖硯', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["求於花石間，怪狀乃天然。","中瑩五寸劒，外[差]千疊蓮。","月融還似洗，雲濕便堪研。","寄與先生後，應添內外篇。"]', '["求於花石间，怪狀乃天然。","中瑩五寸劒，外[差]千叠蓮。","月融還似洗，云濕便堪研。","寄與先生後，應添內外篇。"]', '诗', 'shi', '', NULL, '五貺詩 太湖硯 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeff2163-9d33-409d-ab1a-5049201eb653', '五貺詩 烏龍養和', '五貺诗 烏龙養和', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["壽木拳數尺，天生形狀幽。","把疑傷虺節，用恐破蛇瘤。","置合月觀內，買須雲肆頭。","料君攜去處，煙雨太湖舟。"]', '["壽木拳數尺，天生形狀幽。","把疑傷虺節，用恐破蛇瘤。","置合月观內，買須云肆头。","料君携去处，煙雨太湖舟。"]', '诗', 'shi', '', NULL, '五貺詩 烏龍養和 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d8bd31a-b6a1-44b8-9c1d-923131cee6b5', '五貺詩 訶陵樽', '五貺诗 訶陵樽', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一片鱟魚殼，其中生翠波。","買須能紫貝，用合對紅螺。","盡瀉判狂藥，禁敲任浩歌。","明朝與君後，爭那玉山何。"]', '["一片鱟鱼殼，其中生翠波。","買須能紫貝，用合对紅螺。","尽瀉判狂藥，禁敲任浩歌。","明朝與君後，爭那玉山何。"]', '诗', 'shi', '', NULL, '五貺詩 訶陵樽 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13a06d77-8ea3-413d-b7e6-6fcb6d5a2215', '早春病中書事寄魯望', '早春病中书事寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["眼暈見雲母，耳虛聞海濤。","惜春狂似蝶，養病躁於猱。","案靜方書古，堂空藥氣高。","可憐真宰意，偏解困吾曹。"]', '["眼暈见云母，耳虛闻海濤。","惜春狂似蝶，養病躁於猱。","案静方书古，堂空藥氣高。","可怜真宰意，偏解困吾曹。"]', '诗', 'shi', '', NULL, '早春病中書事寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab272c10-d5b9-47bc-80b5-1a42ff18e560', '又寄次前韻', '又寄次前韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["病根冬養得，春到一時生。","眼暗憐晨慘，心寒怯夜清。","妻仍嫌酒癖，醫只禁詩情。","應被高人笑，憂身不似名。"]', '["病根冬養得，春到一时生。","眼暗怜晨慘，心寒怯夜清。","妻仍嫌酒癖，醫只禁诗情。","應被高人笑，憂身不似名。"]', '诗', 'shi', '', NULL, '又寄次前韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad6f7dc-a532-4b55-ba40-af021f9e0789', '秋晚留題魯望郊居二首 一', '秋晚留題魯望郊居二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["竹樹冷濩落，入門神已清。","寒蛩傍枕響，秋菜上牆生。","黃犬病仍吠，白驢飢不鳴。","唯將一杯酒，盡日慰劉楨。"]', '["竹樹冷濩落，入门神已清。","寒蛩傍枕响，秋菜上牆生。","黄犬病仍吠，白驢飢不鳴。","唯將一杯酒，尽日慰劉楨。"]', '诗', 'shi', '', NULL, '秋晚留題魯望郊居二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330ead2f-24bf-4eda-a4b0-d0a5de6b020e', '秋晚留題魯望郊居二首 二', '秋晚留題魯望郊居二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["冷臥空齋內，餘酲夕未消。","秋花如有恨，寒蝶似無憀。","簷上落鬬雀，籬根生晚潮。","若輪羈旅事，猶自勝臯橋。"]', '["冷臥空斋內，餘酲夕未消。","秋花如有恨，寒蝶似無憀。","簷上落鬬雀，籬根生晚潮。","若輪羈旅事，猶自勝臯橋。"]', '诗', 'shi', '', NULL, '秋晚留題魯望郊居二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e86a5cf-40e6-42e9-b677-fee81e88805b', '初冬章上人院', '初冬章上人院', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寒到無妨睡，僧吟不廢禪。","尚關經病鶴，猶濾欲枯泉。","靜案貝多紙，閑爐波律煙。","清譚兩三句，相向自翛然。"]', '["寒到無妨睡，僧吟不廢禪。","尚关經病鹤，猶濾欲枯泉。","静案貝多紙，闲爐波律煙。","清譚兩三句，相向自翛然。"]', '诗', 'shi', '', NULL, '初冬章上人院 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0348bc-f356-4e00-8220-a210664a0a80', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 一', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一方蕭灑地，之子獨深居。","繞屋親栽竹，堆牀手寫書。","高風翔砌鳥，暴雨失池魚。","暗識歸山計，村邊買鹿車。"]', '["一方蕭灑地，之子独深居。","繞屋親栽竹，堆牀手寫书。","高风翔砌鸟，暴雨失池鱼。","暗識归山計，村邊買鹿车。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f03002-8549-4bcd-bce0-23899db1eb46', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 二', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["籬疎從綠槿，簷亂任黃茅。","壓酒移谿石，煎茶拾野巢。","靜窗懸雨笠，閑壁挂煙匏。","支遁今無骨，誰爲世外交。"]', '["籬疎從綠槿，簷亂任黄茅。","壓酒移谿石，煎茶拾野巢。","静窗懸雨笠，闲壁挂煙匏。","支遁今無骨，誰爲世外交。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b4f510-01b5-4dae-ab76-0e3f4aa64c86', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 三', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["繭稀初上簇，醅盡未乾牀。","盡日留蠶母，移時祭麴王。","趁泉澆竹急，候雨種蓮忙。","更葺園中景，應爲顧辟疆。"]', '["繭稀初上簇，醅尽未乾牀。","尽日留蠶母，移时祭麴王。","趁泉澆竹急，候雨種蓮忙。","更葺园中景，應爲顧辟疆。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59fff3b0-11ac-484a-ba34-fcade2cb0b7f', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 四', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["靜僻無人到，幽深每自知。","鶴來添口數，琴到益家資。","壞塹生魚沫，頹簷落燕兒。","空將綠蕉葉，來往寄閑詩。"]', '["静僻無人到，幽深每自知。","鹤来添口數，琴到益家資。","壞塹生鱼沫，頹簷落燕兒。","空將綠蕉葉，来往寄闲诗。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbbdf41f-25c2-438d-8b12-7a7cf9679b11', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 五', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 五', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["夏過無擔石，日高開板扉。","僧雖與筒簟，人不典蕉衣。","鶴靜共眠覺，鷺馴同釣歸。","生公石上月，何夕約譚微。"]', '["夏過無擔石，日高开板扉。","僧雖與筒簟，人不典蕉衣。","鹤静共眠覺，鷺馴同釣归。","生公石上月，何夕約譚微。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 五 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ed71ce-a134-47d6-9061-3b2f285be913', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 六', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 六', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["經歲岸烏紗，讀書三十車。","水痕侵病竹，蛛網上衰花。","詩任傳漁客，衣從遞酒家。","知君秋晚事，白幘刈胡麻。"]', '["經歲岸烏紗，读书三十车。","水痕侵病竹，蛛網上衰花。","诗任傳漁客，衣從遞酒家。","知君秋晚事，白幘刈胡麻。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 六 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1706193-2de8-4892-a6e2-60456426b3d4', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 七', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 七', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寂歷秋懷動，蕭條夏思殘。","久貧空酒庫，多病束魚竿。","玄想凝鶴扇，清齋拂鹿冠。","夢魂無俗事，夜夜到金壇。"]', '["寂歷秋懷动，蕭條夏思殘。","久貧空酒庫，多病束鱼竿。","玄想凝鹤扇，清斋拂鹿冠。","梦魂無俗事，夜夜到金壇。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 七 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbc271b-967f-4209-9121-5e5cfcb152d2', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 八', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 八', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["閉門無一事，安穩臥涼天。","砌下翹飢鶴，庭陰落病蟬。","倚杉閑把易，燒朮靜論玄。","賴有包山客，時時寄紫泉。"]', '["閉门無一事，安穩臥涼天。","砌下翹飢鹤，庭陰落病蟬。","倚杉闲把易，燒朮静論玄。","賴有包山客，时时寄紫泉。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 八 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cb355b-e1ea-4697-864b-f822a72b02c0', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 九', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 九', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["病起扶靈壽，翛然強到門。","與杉除敗葉，爲石整危根。","薜蔓任遮壁，蓮莖臥枕盆。","明朝有忙事，召客斵桐孫。"]', '["病起扶靈壽，翛然強到门。","與杉除敗葉，爲石整危根。","薜蔓任遮壁，蓮莖臥枕盆。","明朝有忙事，召客斵桐孫。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 九 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b7d4c6-9128-4d29-9c93-3309eee6f97f', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 十', '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 十', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["緩頰稱無利，低眉號不能。","世情都太薄，俗意就中憎。","雲態不知驟，鶴情非會徵。","畫臣誰奉詔，來此寫姜肱。"]', '["緩頰稱無利，低眉號不能。","世情都太薄，俗意就中憎。","云態不知驟，鹤情非會徵。","畫臣誰奉詔，来此寫姜肱。"]', '诗', 'shi', '', NULL, '臨頓爲吳中偏勝之地陸魯望居之不出郛郭曠若郊墅余每相訪欵然惜去因成五言十首奉題屋壁 十 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a23d64f0-cdf8-4b61-bec5-c37faa431bd5', '遊棲霞寺', '游棲霞寺', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["不見明居士，空山但寂寥。","白蓮吟次缺，青靄坐來銷。","泉冷無三伏，松枯有六朝。","何時石上月，相對論逍遙。"]', '["不见明居士，空山但寂寥。","白蓮吟次缺，青靄坐来銷。","泉冷無三伏，松枯有六朝。","何时石上月，相对論逍遙。"]', '诗', 'shi', '', NULL, '遊棲霞寺 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8044d094-982d-4eb1-8fbf-ef98567e4d9e', '旅舍除夜', '旅舍除夜', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["永夜誰能守，羈心不放眠。","挑燈猶故歲，聽角已新年。","出谷空嗟晚，銜杯尚媿先。","晚來辭逆旅，雪涕野槐天。"]', '["永夜誰能守，羈心不放眠。","挑灯猶故歲，听角已新年。","出谷空嗟晚，銜杯尚媿先。","晚来辞逆旅，雪涕野槐天。"]', '诗', 'shi', '', NULL, '旅舍除夜 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c96018f6-6fcc-482e-a2e4-7d9ec93db9a5', '魯望示廣文先生吳門二章情格高散可醒俗態因追想山中風度次韻屬和存於詩編魯望之命也 一', '魯望示廣文先生吳门二章情格高散可醒俗態因追想山中风度次韻屬和存於诗編魯望之命也 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["我見先生道，休思鄭廣文。","鶴翻希作伴，鷗却覓爲羣。","逸好冠清月，高宜著白雲。","朝廷未無事，爭任醉醺醺。"]', '["我见先生道，休思鄭廣文。","鹤翻希作伴，鷗却覓爲羣。","逸好冠清月，高宜著白云。","朝廷未無事，爭任醉醺醺。"]', '诗', 'shi', '', NULL, '魯望示廣文先生吳門二章情格高散可醒俗態因追想山中風度次韻屬和存於詩編魯望之命也 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86e531fc-37aa-4172-b226-87b4662d8582', '魯望示廣文先生吳門二章情格高散可醒俗態因追想山中風度次韻屬和存於詩編魯望之命也 二', '魯望示廣文先生吳门二章情格高散可醒俗態因追想山中风度次韻屬和存於诗編魯望之命也 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["能諳肉芝樣，解講隱書文。","終古神仙窟，窮年麋鹿羣。","行廚煮白石，臥具拂青雲。","應在雷平上，支頤復半醺。"]', '["能諳肉芝樣，解講隐书文。","終古神仙窟，窮年麋鹿羣。","行廚煮白石，臥具拂青云。","應在雷平上，支頤复半醺。"]', '诗', 'shi', '', NULL, '魯望示廣文先生吳門二章情格高散可醒俗態因追想山中風度次韻屬和存於詩編魯望之命也 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9f938e-0c23-4abd-8057-1f602dbc5a13', '虎丘寺殿前有古杉一本形狀醜怪圖之不盡況百卉競媚若妬若媢娼唯此杉死抱奇節髐然闖然不知雨露之可生也風霜之可瘁也乃造化者方外之材乎遂賦三百言以見志', '虎丘寺殿前有古杉一本形狀醜怪圖之不尽況百卉競媚若妬若媢娼唯此杉死抱奇節髐然闖然不知雨露之可生也风霜之可瘁也乃造化者方外之材乎遂賦三百言以见志', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["種日應逢晉，枯來必自隋。","鰐狂將立處，螭鬬未開時。","卓犖擲槍幹，叉牙束戟枝。","初驚蟉篆活，復訝獝狂癡。","勁質如堯瘦，貞容學舜黴。","勢能擒土伯，醜可駭山祇。","虎爪拏巖穩，虬身脫浪欹。","槎頭禿似刷，枿觜利於錐。","突兀方相脛，鱗皴夏氏胝。","根應藏鬼血，柯欲漏龍漦。","抝似神荼怒，呀如猰貐飢。","朽癰難可吮，枯瘇不堪治。","一炷玄雲拔，三尋黑矟奇。","狼頭㪍窣豎，蠆尾掘攣垂。","目燥那逢爟，心開豈中鈹。","任苔爲疥癬，從蠹作瘡痍。","品格齊遼鶴，年齡等寶龜。","將懷縮地力，欲負拔山姿。","未倒防風骨，初僵負貳屍。","漆書明古本，鐵室抗全師。","碨礧還無極，伶俜又莫持。","堅應敵駿骨，文定寫甝皮。","蟠屈愁凌剎，騰驤恐攫池。","搶煙寒嶱𡾲，披蔦靜䙰褷。","威仰誠難識，句芒恐不知。","好燒胡律看，堪共達多期。","寡色諸芳笑，無聲衆籟疑。","終添八柱位，未要一繩維。","盡日來唯我，當春翫更誰。","他年如入用，直構太平基。"]', '["種日應逢晉，枯来必自隋。","鰐狂將立处，螭鬬未开时。","卓犖擲槍幹，叉牙束戟枝。","初驚蟉篆活，复訝獝狂癡。","勁質如堯瘦，貞容学舜黴。","勢能擒土伯，醜可駭山祇。","虎爪拏巖穩，虬身脫浪欹。","槎头禿似刷，枿觜利於錐。","突兀方相脛，鱗皴夏氏胝。","根應藏鬼血，柯欲漏龙漦。","抝似神荼怒，呀如猰貐飢。","朽癰难可吮，枯瘇不堪治。","一炷玄云拔，三尋黑矟奇。","狼头㪍窣豎，蠆尾掘攣垂。","目燥那逢爟，心开豈中鈹。","任苔爲疥癬，從蠹作瘡痍。","品格齊遼鹤，年齡等寶龟。","將懷縮地力，欲負拔山姿。","未倒防风骨，初僵負貳屍。","漆书明古本，鐵室抗全師。","碨礧還無極，伶俜又莫持。","堅應敵駿骨，文定寫甝皮。","蟠屈愁凌剎，腾驤恐攫池。","搶煙寒嶱𡾲，披蔦静䙰褷。","威仰誠难識，句芒恐不知。","好燒胡律看，堪共達多期。","寡色諸芳笑，無声衆籟疑。","終添八柱位，未要一繩維。","尽日来唯我，當春翫更誰。","他年如入用，直構太平基。"]', '诗', 'shi', '', NULL, '虎丘寺殿前有古杉一本形狀醜怪圖之不盡況百卉競媚若妬若媢娼唯此杉死抱奇節髐然闖然不知雨露之可生也風霜之可瘁也乃造化者方外之材乎遂賦三百言以見志 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d151fb9-d93b-4d0a-930b-f4915ef4a1fe', '新秋言懷寄魯望三十韻', '新秋言懷寄魯望三十韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["新秋入破宅，疎澹若平郊。","戶牖深如窟，詩書亂似巢。","移牀驚蟋蟀，拂匣動蠨蛸。","靜把泉華掬，閑拈乳管敲。","檜身渾箇矮，石面得能䫜。","小桂如拳葉，新松似手梢。","鶴鳴轉清角，鶻下撲金𩩉。","合藥還慵服，爲文亦嬾抄。","煩心入夜醒，疾首帶涼抓。","杉葉尖如鏃，藤絲靭似鞘。","僨田含紫芋，低蔓隱青匏。","老柏渾如疥，陰苔忽似膠。","王餘落敗塹，胡孟入空庖。","度日忘冠帶，經時憶酒肴。","有心同木偶，無舌並金鐃。","興欲添玄測，狂將換易爻。","達人唯落落，俗士自譊譊。","底力將排難，何顏用解嘲。","欲銷毀後骨，空轉坐來胞。","猶豫應難抱，狐疑不易包。","等閑逢毒蠚，容易遇咆哮。","時事方千蝎，公途正二崤。","名微甘世棄，性拙任時拋。","白日須投分，青雲合定交。","仕應同五柳，歸莫捨三茅。","澗鹿從來去，煙蘿任溷殽。","狙公鬧後戲，雲母病來𦾱。","從此居方丈，終非競斗筲。","道窮應鬼遣，性拙必天教。","無限疎慵事，憑君解一瓟。"]', '["新秋入破宅，疎澹若平郊。","戶牖深如窟，诗书亂似巢。","移牀驚蟋蟀，拂匣动蠨蛸。","静把泉华掬，闲拈乳管敲。","檜身渾箇矮，石面得能䫜。","小桂如拳葉，新松似手梢。","鹤鳴轉清角，鶻下撲金𩩉。","合藥還慵服，爲文亦嬾抄。","煩心入夜醒，疾首带涼抓。","杉葉尖如鏃，藤絲靭似鞘。","僨田含紫芋，低蔓隐青匏。","老柏渾如疥，陰苔忽似膠。","王餘落敗塹，胡孟入空庖。","度日忘冠带，經时憶酒肴。","有心同木偶，無舌並金鐃。","兴欲添玄測，狂將換易爻。","達人唯落落，俗士自譊譊。","底力將排难，何顏用解嘲。","欲銷毀後骨，空轉坐来胞。","猶豫應难抱，狐疑不易包。","等闲逢毒蠚，容易遇咆哮。","时事方千蝎，公途正二崤。","名微甘世棄，性拙任时拋。","白日須投分，青云合定交。","仕應同五柳，归莫捨三茅。","澗鹿從来去，煙蘿任溷殽。","狙公鬧後戲，云母病来𦾱。","從此居方丈，終非競斗筲。","道窮應鬼遣，性拙必天教。","無限疎慵事，憑君解一瓟。"]', '诗', 'shi', '', NULL, '新秋言懷寄魯望三十韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b568851d-e84b-4356-bbdb-764fdc43e885', '奉和魯望秋日遣懷次韻', '奉和魯望秋日遣懷次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["高蹈爲時背，幽懷是事兼。","神仙君可致，江海我能淹。","共守庚申夜，同看乙巳占。","藥囊除紫蠹，丹竈拂紅鹽。","與物深無競，於生亦太廉。","鴻災因足警，魚禍爲稀潛。","筆硯秋光洗，衣巾夏蘚霑。","酒甔香竹院，魚籠挂茅簷。","琴忘因拋譜，詩存爲致籤。","茶旗經雨展，石笋帶雲尖。","鶴共心情慢，烏同面色黔。","向陽裁白帢，終歲憶貂襜。","取嶺爲山障，將泉作水簾。","溪晴多晚鷺，池廢足秋蟾。","破衲雖云補，閑齋未辦苫。","共君還有役，竟夕得厭厭。"]', '["高蹈爲时背，幽懷是事兼。","神仙君可致，江海我能淹。","共守庚申夜，同看乙巳占。","藥囊除紫蠹，丹竈拂紅鹽。","與物深無競，於生亦太廉。","鴻災因足警，鱼禍爲稀潛。","笔硯秋光洗，衣巾夏蘚霑。","酒甔香竹院，鱼籠挂茅簷。","琴忘因拋譜，诗存爲致籤。","茶旗經雨展，石笋带云尖。","鹤共心情慢，烏同面色黔。","向陽裁白帢，終歲憶貂襜。","取嶺爲山障，將泉作水簾。","溪晴多晚鷺，池廢足秋蟾。","破衲雖云補，闲斋未辦苫。","共君還有役，竟夕得厭厭。"]', '诗', 'shi', '', NULL, '奉和魯望秋日遣懷次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4fc275-0b29-4d42-b047-258b308cf667', '江南書情二十韻寄秘閣韋校書貽之商洛宋先輩垂文二同年', '江南书情二十韻寄秘閣韋校书貽之商洛宋先輩垂文二同年', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["四載加前字，今來未改銜。","君批鳳尾詔，我住虎頭巖。","季氏唯謀逐，臧倉只擬讒。","時訛輕五羖，俗淺重三緘。","瘦去形如鶴，憂來態似獑。","才非師趙壹，直欲效陳咸。","孤竹寧收笛，黃琮未作瑊。","作羊寧免狠，爲兔即須毚。","枕戶槐從亞，侵堦草嬾芟。","壅泉教咽咽，壘石放巉巉。","掣釣隨心動，抽書任意杴。","茶教弩父摘，酒遣僰童監。","默坐看山困，清齋飲水嚴。","蘚生天竺屐，煙外洞庭帆。","病久新烏帽，閑多著白衫。","藥苞陳[雨]匼，詩草蠹雲函。","遣客呼林狖，辭人寄海𧍧。","室唯搜古器，錢只買秋杉。","寡合無深契，相期有至諴。","他年如訪問，煙蔦暗髟髟。"]', '["四載加前字，今来未改銜。","君批鳳尾詔，我住虎头巖。","季氏唯謀逐，臧倉只擬讒。","时訛轻五羖，俗淺重三緘。","瘦去形如鹤，憂来態似獑。","才非師趙壹，直欲效陳咸。","孤竹寧收笛，黄琮未作瑊。","作羊寧免狠，爲兔即須毚。","枕戶槐從亞，侵堦草嬾芟。","壅泉教咽咽，壘石放巉巉。","掣釣隨心动，抽书任意杴。","茶教弩父摘，酒遣僰童監。","默坐看山困，清斋饮水嚴。","蘚生天竺屐，煙外洞庭帆。","病久新烏帽，闲多著白衫。","藥苞陳[雨]匼，诗草蠹云函。","遣客呼林狖，辞人寄海𧍧。","室唯搜古器，錢只買秋杉。","寡合無深契，相期有至諴。","他年如訪问，煙蔦暗髟髟。"]', '诗', 'shi', '', NULL, '江南書情二十韻寄秘閣韋校書貽之商洛宋先輩垂文二同年 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d0effe-f79c-42f7-a17d-6e6da5d9c8de', '憶洞庭觀步十韻', '憶洞庭观步十韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["前時登觀步，暑雨正錚摐。","上戍看綿蕝，登村度石矼。","崦花時有蔟，溪鳥不成雙。","遠樹點黑矟，遙峰露碧幢。","巖根瘦似殼，杉破腹如腔。","䘨𧘈漁人服，筕篖野店窗。","多攜白木鍤，愛買紫泉缸。","仙犬聲音古，遺民意緒厖。","何文堪緯地，底策可經邦。","自此將妻子，歸山不姓龐。"]', '["前时登观步，暑雨正錚摐。","上戍看綿蕝，登村度石矼。","崦花时有蔟，溪鸟不成雙。","远樹点黑矟，遙峰露碧幢。","巖根瘦似殼，杉破腹如腔。","䘨𧘈漁人服，筕篖野店窗。","多携白木鍤，愛買紫泉缸。","仙犬声音古，遺民意緒厖。","何文堪緯地，底策可經邦。","自此將妻子，归山不姓龐。"]', '诗', 'shi', '', NULL, '憶洞庭觀步十韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d372fa7-aef1-4768-9c5a-b9c338be6043', '諫議以罷郡將歸以六韻賜示因佇詶獻', '諫議以罷郡將归以六韻賜示因佇詶獻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["欲下持衡詔，先容解印歸。","露濃春後澤，霜薄霽來威。","舊化堪治疾，餘恩可療飢。","隔花攀去櫂，穿柳挽行衣。","佐理能無取，酬知力甚微。","空將千感淚，異日拜黃扉。"]', '["欲下持衡詔，先容解印归。","露濃春後澤，霜薄霽来威。","旧化堪治疾，餘恩可療飢。","隔花攀去櫂，穿柳挽行衣。","佐理能無取，酬知力甚微。","空將千感泪，異日拜黄扉。"]', '诗', 'shi', '', NULL, '諫議以罷郡將歸以六韻賜示因佇詶獻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71dd1555-ee74-4084-8227-4089bb48d6fb', '過雲居院玄福上人舊居', '過云居院玄福上人旧居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["重到雲居獨悄然，隔窗窺影尚疑禪。","不逢野老來聽法，猶見鄰僧爲引泉。","龕上已生新石耳，壁間空帶舊茶煙。","南宗弟子時時到，泣把山花奠几筵。"]', '["重到云居独悄然，隔窗窺影尚疑禪。","不逢野老来听法，猶见鄰僧爲引泉。","龕上已生新石耳，壁间空带旧茶煙。","南宗弟子时时到，泣把山花奠几筵。"]', '诗', 'shi', '', NULL, '過雲居院玄福上人舊居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b5f0e61-f098-4ae6-b4fd-8da44bdcfb30', '陪江西裴公遊襄州延慶寺', '陪江西裴公游襄州延慶寺', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["丹霄路上歇征輪，勝地偷閑一日身。","不署前驅驚野鳥，唯將後乘載詩人。","巖邊候吏雲遮却，竹下朝衣露滴新。","更向碧山深處問，不妨猶有草茅臣。"]', '["丹霄路上歇征輪，勝地偷闲一日身。","不署前驱驚野鸟，唯將後乘載诗人。","巖邊候吏云遮却，竹下朝衣露滴新。","更向碧山深处问，不妨猶有草茅臣。"]', '诗', 'shi', '', NULL, '陪江西裴公遊襄州延慶寺 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f206685-9c84-408a-a644-032564e5237b', '西塞山泊漁家', '西塞山泊漁家', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["白綸巾下髪如絲，靜倚楓根坐釣磯。","中婦桑村挑葉去，小兒沙市買蓑歸。","雨來蓴菜流船滑，春後鱸魚墜釣肥。","西塞山前終日客，隔波相羨盡依依。"]', '["白綸巾下髪如絲，静倚楓根坐釣磯。","中婦桑村挑葉去，小兒沙市買蓑归。","雨来蓴菜流船滑，春後鱸鱼墜釣肥。","西塞山前終日客，隔波相羨尽依依。"]', '诗', 'shi', '', NULL, '西塞山泊漁家 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9994c65-a0d7-4b1d-8e4a-efda9ef25352', '襄州春遊', '襄州春游', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["信馬騰騰觸處行，春風相引與詩情。","等閑遇事成歌詠，取次衝筵隱姓名。","映柳認人多錯誤，透花窺鳥最分明。","岑牟單絞何曾著，莫道猖狂似禰衡。"]', '["信马腾腾觸处行，春风相引與诗情。","等闲遇事成歌詠，取次衝筵隐姓名。","映柳認人多錯誤，透花窺鸟最分明。","岑牟單絞何曾著，莫道猖狂似禰衡。"]', '诗', 'shi', '', NULL, '襄州春遊 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680be041-75fe-49af-afae-631454cd51fc', '送從弟皮崇歸復州', '送從弟皮崇归复州', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["羨爾優游正少年，竟陵煙月似吳天。","車螯近岸無妨取，舴艋隨風不費牽。","處處路傍千頃稻，家家門外一渠蓮。","慇懃莫笑襄陽住，爲愛南溪縮項鳊。"]', '["羨爾優游正少年，竟陵煙月似吳天。","车螯近岸無妨取，舴艋隨风不費牽。","处处路傍千頃稻，家家门外一渠蓮。","慇懃莫笑襄陽住，爲愛南溪縮項鳊。"]', '诗', 'shi', '', NULL, '送從弟皮崇歸復州 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d975111e-b87f-427c-99a2-e2df00fb76c4', '題潼關蘭若', '題潼关蘭若', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["潼津罷驚有招提，近百年無戰馬嘶。","壯士不言三尺劒，謀臣休道一丸泥。","昔時馳道洪波上，今日宸居紫氣西。","關吏不勞重借問，棄繻生擬入耶溪。"]', '["潼津罷驚有招提，近百年無戰马嘶。","壯士不言三尺劒，謀臣休道一丸泥。","昔时驰道洪波上，今日宸居紫氣西。","关吏不勞重借问，棄繻生擬入耶溪。"]', '诗', 'shi', '', NULL, '題潼關蘭若 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19609e4c-196f-461d-8ded-09503531c42d', '襄陽閑居與友生夜會', '襄陽闲居與友生夜會', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["習隱悠悠世不知，林園幽事遞相期。","舊絲再上琴調晚，壞葉重燒酒煖遲。","三徑引時寒步月，四鄰偷得夜吟詩。","草玄寂淡無人愛，不遇劉歆更語誰。"]', '["習隐悠悠世不知，林园幽事遞相期。","旧絲再上琴調晚，壞葉重燒酒煖遲。","三徑引时寒步月，四鄰偷得夜吟诗。","草玄寂淡無人愛，不遇劉歆更語誰。"]', '诗', 'shi', '', NULL, '襄陽閑居與友生夜會 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ae3f10-73be-4221-ac3a-756afb2c6888', '習池晨起', '習池晨起', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["清曙蕭森載酒來，涼風相引繞亭臺。","數聲翡翠背人去，一番芙蓉含日開。","茭葉深深埋釣艇，魚兒漾漾逐流杯。","竹屏風下登山屐，十宿高陽忘却迴。"]', '["清曙蕭森載酒来，涼风相引繞亭台。","數声翡翠背人去，一番芙蓉含日开。","茭葉深深埋釣艇，鱼兒漾漾逐流杯。","竹屏风下登山屐，十宿高陽忘却迴。"]', '诗', 'shi', '', NULL, '習池晨起 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b300278-a1cb-4487-8ab7-03febc9f1da0', '秋晚自洞庭湖別業寄穆秀才', '秋晚自洞庭湖別業寄穆秀才', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["破村寥落過重陽，獨自攖寧葺草房。","風撦紅蕉仍換葉，雨淋黃菊不成香。","野猨偷栗重窺戶，落雁疑人更繞塘。","他日若修耆舊傳，爲予添取此書堂。"]', '["破村寥落過重陽，独自攖寧葺草房。","风撦紅蕉仍換葉，雨淋黄菊不成香。","野猨偷栗重窺戶，落雁疑人更繞塘。","他日若修耆旧傳，爲予添取此书堂。"]', '诗', 'shi', '', NULL, '秋晚自洞庭湖別業寄穆秀才 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3b6dcf-9df8-4497-b35d-b9f8cd786830', '華山李鍊師所居', '华山李鍊師所居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["麻姑古貌上仙才，謫向蓮峰管玉臺。","瑞氣染衣金液啓，香煙映面紫文開。","孤雲盡日方離洞，雙鶴移時只有苔。","深夜寂寥存想歇，月天時下草堂來。"]', '["麻姑古貌上仙才，謫向蓮峰管玉台。","瑞氣染衣金液啓，香煙映面紫文开。","孤云尽日方離洞，雙鹤移时只有苔。","深夜寂寥存想歇，月天时下草堂来。"]', '诗', 'shi', '', NULL, '華山李鍊師所居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c0dcf1-0097-417d-91ae-e122fd20f27a', '宏詞下第感恩獻兵部侍郎', '宏词下第感恩獻兵部侍郎', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["分明仙籍列清虛，自是還丹九轉疎。","畫虎已成翻類狗，登龍纔變即爲魚。","空慙季布千金諾，但負劉弘一紙書。","猶有報恩方寸在，不知通塞竟何如。"]', '["分明仙籍列清虛，自是還丹九轉疎。","畫虎已成翻類狗，登龙纔变即爲鱼。","空慙季布千金諾，但負劉弘一紙书。","猶有報恩方寸在，不知通塞竟何如。"]', '诗', 'shi', '', NULL, '宏詞下第感恩獻兵部侍郎 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd5fada-63af-4c22-a187-6d93c3ec4e99', '襄州漢陽王故宅', '襄州漢陽王故宅', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["碑字依稀廟已荒，猶聞耆舊憶賢王。","園林一半爲他主，山水虛言是故鄉。","戟戶野蒿生翠瓦，舞樓栖鴿汙雕梁。","柱天功業緣何事，不得終身似霍光。"]', '["碑字依稀廟已荒，猶闻耆旧憶賢王。","园林一半爲他主，山水虛言是故乡。","戟戶野蒿生翠瓦，舞楼栖鴿汙雕梁。","柱天功業緣何事，不得終身似霍光。"]', '诗', 'shi', '', NULL, '襄州漢陽王故宅 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ca0612-16bd-4cab-b47f-8d00bfa24902', '傷盧獻秀才', '傷盧獻秀才', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["愍征新價欲凌空，一首堪欺左太沖。","只爲白衣聲過重，且非青漢路難通。","貴侯待寫過門下，詞客偷名入卷中。","手弄桂枝嫌不折，直教身歿負春風。"]', '["愍征新價欲凌空，一首堪欺左太沖。","只爲白衣声過重，且非青漢路难通。","貴侯待寫過门下，词客偷名入卷中。","手弄桂枝嫌不折，直教身歿負春风。"]', '诗', 'shi', '', NULL, '傷盧獻秀才 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c6a09a-9f2d-4d03-b728-22c54a21476b', '南陽', '南陽', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["昆陽王氣已蕭疎，依舊山河捧帝居。","廢路塌平殘瓦礫，破墳耕出爛圖書。","綠莎滿縣年荒後，白鳥盈溪雨霽初。","二百年來霸王業，可知今日是丘墟。"]', '["昆陽王氣已蕭疎，依旧山河捧帝居。","廢路塌平殘瓦礫，破墳耕出爛圖书。","綠莎满縣年荒後，白鸟盈溪雨霽初。","二百年来霸王業，可知今日是丘墟。"]', '诗', 'shi', '', NULL, '南陽 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46939335-ebc9-4075-8eea-85be03765bb0', '秋晚訪李處士所居', '秋晚訪李处士所居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["門前襄水碧潺潺，靜釣歸來不掩關。","書閣鼠穿廚簏破，竹園霜後桔橰閑。","兒童不許驚幽鳥，藥草須教上假山。","莫爲愛詩偏念我，訪君多得醉中還。"]', '["门前襄水碧潺潺，静釣归来不掩关。","书閣鼠穿廚簏破，竹园霜後桔橰闲。","兒童不許驚幽鸟，藥草須教上假山。","莫爲愛诗偏念我，訪君多得醉中還。"]', '诗', 'shi', '', NULL, '秋晚訪李處士所居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96cfdc53-60b4-4f7e-9286-f89f665ba2f5', '李處士郊居', '李处士郊居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["石衣如髪小溪清，溪上柴門架樹成。","園裏水流澆竹響，窗中人靜下棋聲。","幾多狎鳥皆諳性，無限幽花未得名。","滿引紅螺詩一首，劉楨失却病心情。"]', '["石衣如髪小溪清，溪上柴门架樹成。","园裏水流澆竹响，窗中人静下棋声。","幾多狎鸟皆諳性，無限幽花未得名。","满引紅螺诗一首，劉楨失却病心情。"]', '诗', 'shi', '', NULL, '李處士郊居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875c43fa-0e4a-4017-9408-fe8d994f66ca', '送令狐補闕歸朝', '送令狐補闕归朝', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["文如日月氣如虹，舉國重生正始風。","且願仲山居左掖，只憂徐邈入南宮。","朝衣正在天香裏，諫草應焚禁漏中。","爲說明年今日事，晉廷新拜黑頭公。"]', '["文如日月氣如虹，舉国重生正始风。","且願仲山居左掖，只憂徐邈入南宮。","朝衣正在天香裏，諫草應焚禁漏中。","爲说明年今日事，晉廷新拜黑头公。"]', '诗', 'shi', '', NULL, '送令狐補闕歸朝 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ff124a-5df0-4ebe-bca9-e7a0550b1480', '洛中寒食二首 一', '洛中寒食二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["千門萬戶掩斜暉，繡幰金銜晚未歸。","擊鞠王孫如錦地，鬬雞公子似花衣。","嵩雲靜對行臺起，洛鳥閑穿上苑飛。","唯有路傍無意者，獻書未納問淮肥。"]', '["千门万戶掩斜暉，繡幰金銜晚未归。","擊鞠王孫如錦地，鬬雞公子似花衣。","嵩云静对行台起，洛鸟闲穿上苑飞。","唯有路傍無意者，獻书未納问淮肥。"]', '诗', 'shi', '', NULL, '洛中寒食二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6da20e4-bb4a-4c66-9b24-18e7fabed5d4', '洛中寒食二首 二', '洛中寒食二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["遠近垂楊映鈿車，天津橋影壓神霞。","弄春公子正迴首，趁節行人不到家。","洛水萬年雲母竹，漢陵千載野棠花。","欲知豪貴堪愁處，請看邙山晚照斜。"]', '["远近垂楊映鈿车，天津橋影壓神霞。","弄春公子正迴首，趁節行人不到家。","洛水万年云母竹，漢陵千載野棠花。","欲知豪貴堪愁处，請看邙山晚照斜。"]', '诗', 'shi', '', NULL, '洛中寒食二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b181344-5ecc-48c3-92b1-6a84a529acba', '登第後寒食杏園有宴因寄錄事宋垂文同年', '登第後寒食杏园有宴因寄錄事宋垂文同年', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雨洗清明萬象鮮，滿城車馬簇紅筵。","恩榮雖得陪高會，科禁惟憂犯列仙。","當醉不知開火日，正貧那似看花年。","縱來恐被青娥笑，未納春風一宴錢。"]', '["雨洗清明万象鲜，满城车马簇紅筵。","恩榮雖得陪高會，科禁惟憂犯列仙。","當醉不知开火日，正貧那似看花年。","縱来恐被青娥笑，未納春风一宴錢。"]', '诗', 'shi', '', NULL, '登第後寒食杏園有宴因寄錄事宋垂文同年 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1366cf81-dec0-4216-8194-8a0dc5064dce', '陳先輩故居', '陳先輩故居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["杉桂交陰一里餘，逢人渾似洞天居。","千株橘樹唯沽酒，十頃蓮塘不買魚。","藜杖閑來侵徑竹，角巾端坐滿樓書。","襄陽無限煙霞地，難覓幽奇似此殊。"]', '["杉桂交陰一里餘，逢人渾似洞天居。","千株橘樹唯沽酒，十頃蓮塘不買鱼。","藜杖闲来侵徑竹，角巾端坐满楼书。","襄陽無限煙霞地，难覓幽奇似此殊。"]', '诗', 'shi', '', NULL, '陳先輩故居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb150d96-dd60-4020-b816-99d0375bfe5b', '奉和魯望寒夜訪寂上人次韻', '奉和魯望寒夜訪寂上人次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["院寒青靄正沈沈，霜棧乾鳴入古林。","數葉貝書松火暗，一聲金磬檜煙深。","陶潛見社無妨醉，殷浩譚經不廢吟。","何事欲攀塵外契，除君皆有利名心。"]', '["院寒青靄正沈沈，霜棧乾鳴入古林。","數葉貝书松火暗，一声金磬檜煙深。","陶潛见社無妨醉，殷浩譚經不廢吟。","何事欲攀塵外契，除君皆有利名心。"]', '诗', 'shi', '', NULL, '奉和魯望寒夜訪寂上人次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60202dc9-9217-4fa9-ab28-f8d0defd1394', '江南道中懷茅山廣文南陽博士三首 一', '江南道中懷茅山廣文南陽博士三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寒嵐依約認華陽，遙想高人臥草堂。","半日始齋青䭀飯，移時空印白檀香。","鶴雛入夜歸雲屋，乳管逢春落石牀。","誰道夫君無伴侶，不離窗下見羲皇。"]', '["寒嵐依約認华陽，遙想高人臥草堂。","半日始斋青䭀飯，移时空印白檀香。","鹤雛入夜归云屋，乳管逢春落石牀。","誰道夫君無伴侶，不離窗下见羲皇。"]', '诗', 'shi', '', NULL, '江南道中懷茅山廣文南陽博士三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53812167-6f76-48b8-9165-a61f373e3d70', '江南道中懷茅山廣文南陽博士三首 二', '江南道中懷茅山廣文南陽博士三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["住在華陽第八天，望君唯欲結良緣。","堂扃洞裏千秋燕，廚蓋巖根數斗泉。","壇上古松疑度世，觀中幽鳥恐成仙。","不知何事迎新歲，烏納裘中一覺眠。"]', '["住在华陽第八天，望君唯欲結良緣。","堂扃洞裏千秋燕，廚蓋巖根數斗泉。","壇上古松疑度世，观中幽鸟恐成仙。","不知何事迎新歲，烏納裘中一覺眠。"]', '诗', 'shi', '', NULL, '江南道中懷茅山廣文南陽博士三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc681d08-5960-4d33-bdb0-118b3ddfc280', '江南道中懷茅山廣文南陽博士三首 三', '江南道中懷茅山廣文南陽博士三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["五色香煙惹內文，石飴初熟酒初醺。","將開丹竈那防鶴，欲算棋圖却望雲。","海氣平生當洞見，瀑冰初坼隔山聞。","如何世外無交者，一臥金壇只有君。"]', '["五色香煙惹內文，石飴初熟酒初醺。","將开丹竈那防鹤，欲算棋圖却望云。","海氣平生當洞见，瀑冰初坼隔山闻。","如何世外無交者，一臥金壇只有君。"]', '诗', 'shi', '', NULL, '江南道中懷茅山廣文南陽博士三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ab5e4d-5c54-44c8-b589-2f19d71c08c1', '奉和魯望早春雪中作吳體見寄', '奉和魯望早春雪中作吳體见寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["威仰噤死不敢語，瓊花雲魄清珊珊。","溪光冷射觸𪈺瑦，柳帶凍脆攢欄杆。","竹根乍燒玉節快，酒面新潑金膏寒。","全吳縹瓦十萬戶，惟君與我如袁安。"]', '["威仰噤死不敢語，瓊花云魄清珊珊。","溪光冷射觸𪈺瑦，柳带凍脆攢欄杆。","竹根乍燒玉節快，酒面新潑金膏寒。","全吳縹瓦十万戶，惟君與我如袁安。"]', '诗', 'shi', '', NULL, '奉和魯望早春雪中作吳體見寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6aa6de-31ca-4b17-b38a-3efd0fa2833c', '吳中言情寄魯望', '吳中言情寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["古來傖父愛吳鄉，一上胥臺不可忘。","愛酒有情如手足，除詩無計似膏肓。","宴時不輟琅書味，齋日難判玉鱠香。","爲說松江堪老處，滿船煙月濕莎裳。"]', '["古来傖父愛吳乡，一上胥台不可忘。","愛酒有情如手足，除诗無計似膏肓。","宴时不輟琅书味，斋日难判玉鱠香。","爲说松江堪老处，满船煙月濕莎裳。"]', '诗', 'shi', '', NULL, '吳中言情寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183dee5a-d558-4256-ad81-23f1ebb59dad', '行次野梅', '行次野梅', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蔦拂蘿捎一樹梅，玉妃無侶獨裴回。","好臨王母瑤池發，合傍蕭家粉水開。","共月已爲迷眼伴，與春先作斷腸媒。","不堪便向多情道，萬片霜華雨損來。"]', '["蔦拂蘿捎一樹梅，玉妃無侶独裴回。","好臨王母瑤池發，合傍蕭家粉水开。","共月已爲迷眼伴，與春先作斷腸媒。","不堪便向多情道，万片霜华雨損来。"]', '诗', 'shi', '', NULL, '行次野梅 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420687a6-63b9-4670-ac35-365b28ac0dc1', '揚州看辛夷花', '揚州看辛夷花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["臘前千朵亞芳叢，細膩偏勝素柰功。","螓首不言披曉雪，麝臍無主任春風。","一枝拂地成瑤圃，數樹參庭是蘂宮。","應爲當時天女服，至今猶未放全紅。"]', '["臘前千朵亞芳叢，細膩偏勝素柰功。","螓首不言披晓雪，麝臍無主任春风。","一枝拂地成瑤圃，數樹參庭是蘂宮。","應爲當时天女服，至今猶未放全紅。"]', '诗', 'shi', '', NULL, '揚州看辛夷花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2651d3a2-7917-4d23-8a24-553d45a6d254', '暇日獨處寄魯望', '暇日独处寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["幽慵不覺耗年光，犀柄金徽亂一牀。","野客共爲賒酒計，家人同作借書忙。","園蔬預遣分僧料，廩粟先教算鶴糧。","無限高情好風月，不妨猶得事吾王。"]', '["幽慵不覺耗年光，犀柄金徽亂一牀。","野客共爲賒酒計，家人同作借书忙。","园蔬預遣分僧料，廩粟先教算鹤糧。","無限高情好风月，不妨猶得事吾王。"]', '诗', 'shi', '', NULL, '暇日獨處寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1ae302-5908-4038-8f65-cc14cc0c6532', '屣步訪魯望不遇', '屣步訪魯望不遇', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雪晴墟里竹欹斜，蠟屐徐吟到陸家。","荒徑埽稀堆柏子，破扉開澀染苔花。","壁閑定欲圖雙檜，廚靜空如飯一麻。","擬受太玄今不遇，可憐遺恨似侯芭。"]', '["雪晴墟里竹欹斜，蠟屐徐吟到陸家。","荒徑埽稀堆柏子，破扉开澀染苔花。","壁闲定欲圖雙檜，廚静空如飯一麻。","擬受太玄今不遇，可怜遺恨似侯芭。"]', '诗', 'shi', '', NULL, '屣步訪魯望不遇 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc777810-cebc-40f4-bdcc-fee4319d2727', '開元寺客省早景即事', '开元寺客省早景即事', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["客省蕭條柿葉紅，樓臺如畫倚霜空。","銅池數滴桂上雨，金鐸一聲松杪風。","鶴靜時來珠像側，鴿馴多在寶幡中。","如何塵外虛爲契，不得支公此會同。"]', '["客省蕭條柿葉紅，楼台如畫倚霜空。","銅池數滴桂上雨，金鐸一声松杪风。","鹤静时来珠像側，鴿馴多在寶幡中。","如何塵外虛爲契，不得支公此會同。"]', '诗', 'shi', '', NULL, '開元寺客省早景即事 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9db478-5fb2-4168-8ead-15f384b34d48', '奉和魯望獨夜有懷吳體見寄', '奉和魯望独夜有懷吳體见寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["病鶴帶霧傍獨屋，破巢含雪傾孤梧。","濯足將加漢光腹，抵掌欲捋梁武鬚。","隱几清吟誰敢敵，枕琴高臥真堪圖。","此時枉欠高散物，楠瘤作樽石作壚。"]', '["病鹤带霧傍独屋，破巢含雪傾孤梧。","濯足將加漢光腹，抵掌欲捋梁武鬚。","隐几清吟誰敢敵，枕琴高臥真堪圖。","此时枉欠高散物，楠瘤作樽石作壚。"]', '诗', 'shi', '', NULL, '奉和魯望獨夜有懷吳體見寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7d19d2-f89e-43e8-a87a-8f646c94a1f1', '病中有人惠海蟹轉寄魯望', '病中有人惠海蟹轉寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["紺甲青筐染菭衣，島夷初寄北人時。","離居定有石帆覺，失伴唯應海月知。","族類分明連璅𤥐形容好箇似蟛蜞。","病中無用霜螯處，寄與夫君左手持。"]', '["紺甲青筐染菭衣，島夷初寄北人时。","離居定有石帆覺，失伴唯應海月知。","族類分明連璅𤥐形容好箇似蟛蜞。","病中無用霜螯处，寄與夫君左手持。"]', '诗', 'shi', '', NULL, '病中有人惠海蟹轉寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4f23d7-d945-4da2-bc22-7e6782a653df', '病中美景頗阻追遊因寄魯望', '病中美景頗阻追游因寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["癭牀閑臥晝迢迢，唯把真如慰寂寥。","南國不須收薏苡，百年終竟是芭蕉。","藥前美祿應難斷，枕上芳辰豈易銷。","看取病來多少日，早梅零落玉華焦。"]', '["癭牀闲臥晝迢迢，唯把真如慰寂寥。","南国不須收薏苡，百年終竟是芭蕉。","藥前美祿應难斷，枕上芳辰豈易銷。","看取病来多少日，早梅零落玉华焦。"]', '诗', 'shi', '', NULL, '病中美景頗阻追遊因寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa538bf-37c3-4fcf-935e-b5a4da970df8', '魯望以花翁之什見招因次韻詶之', '魯望以花翁之什见招因次韻詶之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["九十攜鋤傴僂翁，小園幽事盡能通。","斸煙栽藥爲身計，負水澆花是世功。","婚嫁定期杉葉紫，蓋藏應待桂枝紅。","不知家道能多少，只在句芒一夜風。"]', '["九十携鋤傴僂翁，小园幽事尽能通。","斸煙栽藥爲身計，負水澆花是世功。","婚嫁定期杉葉紫，蓋藏應待桂枝紅。","不知家道能多少，只在句芒一夜风。"]', '诗', 'shi', '', NULL, '魯望以花翁之什見招因次韻詶之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423c8127-6c8d-46cc-8adc-350b0edad543', '病中庭際海石榴花盛發感而有寄', '病中庭際海石榴花盛發感而有寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一夜春光綻絳囊，碧油枝上晝煌煌。","風勻秖似調紅露，日暖唯憂化赤霜。","火齊滿枝燒夜月，金津含蘂滴朝陽。","不知桂樹知情否，無限同遊阻陸郎。"]', '["一夜春光綻絳囊，碧油枝上晝煌煌。","风勻秖似調紅露，日暖唯憂化赤霜。","火齊满枝燒夜月，金津含蘂滴朝陽。","不知桂樹知情否，無限同游阻陸郎。"]', '诗', 'shi', '', NULL, '病中庭際海石榴花盛發感而有寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7fff4d-12b5-4bea-93ac-0feeb105212f', '早春以橘子寄魯望', '早春以橘子寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["箇箇和枝葉捧鮮，彩凝猶帶洞庭煙。","不爲韓嫣金丸重，直是周王玉果圓。","剖似日魂初破後，弄如星髓未銷前。","知君多病仍中聖，盡送寒苞向枕邊。"]', '["箇箇和枝葉捧鲜，彩凝猶带洞庭煙。","不爲韓嫣金丸重，直是周王玉果圓。","剖似日魂初破後，弄如星髓未銷前。","知君多病仍中聖，尽送寒苞向枕邊。"]', '诗', 'shi', '', NULL, '早春以橘子寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18fb49fc-db3c-4c31-92ed-0a76ac4d342d', '病中書情寄上崔諫議', '病中书情寄上崔諫議', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十日來來曠奉公，閉門無事忌春風。","蟲絲度日縈琴薦，蛀粉經時落酒筒。","馬足歇從殘漏外，魚須拋在亂書中。","慇懃莫怪求醫切，只爲山櫻欲放紅。"]', '["十日来来曠奉公，閉门無事忌春风。","蟲絲度日縈琴薦，蛀粉經时落酒筒。","马足歇從殘漏外，鱼須拋在亂书中。","慇懃莫怪求醫切，只爲山櫻欲放紅。"]', '诗', 'shi', '', NULL, '病中書情寄上崔諫議 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca3668d-597f-422d-b24e-c16d7a3c9937', '病孔雀', '病孔雀', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["煙花雖媚思沈冥，猶自擡頭護翠翎。","強聽紫簫如欲舞，困眠紅樹似依屏。","因思桂蠹傷肌骨，爲憶松鵝損性靈。","盡日春風吹不起，鈿毫金縷一星星。"]', '["煙花雖媚思沈冥，猶自擡头護翠翎。","強听紫簫如欲舞，困眠紅樹似依屏。","因思桂蠹傷肌骨，爲憶松鵝損性靈。","尽日春风吹不起，鈿毫金縷一星星。"]', '诗', 'shi', '', NULL, '病孔雀 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('561e8768-012a-4e74-acc4-49422fe9934b', '奉和魯望上元日道室焚修', '奉和魯望上元日道室焚修', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["明真臺上下仙官，玄藻初吟萬籟寒。","飆御有聲時杳杳，寶衣無影自珊珊。","蘂書乞見齋心易，玉籍求添拜首難。","端簡不知清景暮，靈蕪香燼落金壇。"]', '["明真台上下仙官，玄藻初吟万籟寒。","飆御有声时杳杳，寶衣無影自珊珊。","蘂书乞见斋心易，玉籍求添拜首难。","端簡不知清景暮，靈蕪香燼落金壇。"]', '诗', 'shi', '', NULL, '奉和魯望上元日道室焚修 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57b8748-3c29-47da-b16f-852c81cf9564', '奉詶魯望惜春見寄', '奉詶魯望惜春见寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十五日中春日好，可憐沈痼冷如灰。","以前雖被愁將去，向後須教醉領來。","梅片盡飄輕粉靨，柳芽初吐爛金醅。","病中無限花番次，爲約東風且住開。"]', '["十五日中春日好，可怜沈痼冷如灰。","以前雖被愁將去，向後須教醉領来。","梅片尽飄轻粉靨，柳芽初吐爛金醅。","病中無限花番次，爲約东风且住开。"]', '诗', 'shi', '', NULL, '奉詶魯望惜春見寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09724f18-974f-46d3-9c4b-3161a3d26f95', '聞魯望遊顏家林園病中有寄', '闻魯望游顏家林园病中有寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一夜韶姿著水光，謝家春草滿池塘。","細挑泉眼尋新脉，輕把花枝嗅宿香。","蝶欲試飛猶護粉，鶯初學囀尚羞簧。","分明不得同君賞，盡日傾心羨索郎。"]', '["一夜韶姿著水光，謝家春草满池塘。","細挑泉眼尋新脉，轻把花枝嗅宿香。","蝶欲試飞猶護粉，鶯初学囀尚羞簧。","分明不得同君賞，尽日傾心羨索郎。"]', '诗', 'shi', '', NULL, '聞魯望遊顏家林園病中有寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('207de7b4-8df4-4e4e-9b97-c44485d6d07d', '奉和魯望春雨即事次韻', '奉和魯望春雨即事次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["織恨凝愁映鳥飛，半旬飄灑掩韶暉。","山容洗得如煙瘦，地脉流來似乳肥。","野客正閑移竹遠，幽人多病探花稀。","何年細濕華陽道，兩乘巾車相並歸。"]', '["织恨凝愁映鸟飞，半旬飄灑掩韶暉。","山容洗得如煙瘦，地脉流来似乳肥。","野客正闲移竹远，幽人多病探花稀。","何年細濕华陽道，兩乘巾车相並归。"]', '诗', 'shi', '', NULL, '奉和魯望春雨即事次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d037543-38b2-4579-a8fd-728bb3a634fb', '魯望春日多尋野景日休抱疾杜門因有是寄', '魯望春日多尋野景日休抱疾杜门因有是寄', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["野侶相逢不待期，半緣幽事半緣詩。","烏紗任岸穿筋竹，白袷從披趁肉芝。","數卷蠹書棊處展，幾升菰米釣前炊。","病中不用君相憶，折取山櫻寄一枝。"]', '["野侶相逢不待期，半緣幽事半緣诗。","烏紗任岸穿筋竹，白袷從披趁肉芝。","數卷蠹书棊处展，幾升菰米釣前炊。","病中不用君相憶，折取山櫻寄一枝。"]', '诗', 'shi', '', NULL, '魯望春日多尋野景日休抱疾杜門因有是寄 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40982624-6c86-4d67-8443-1909cfbaf153', '魯望以躬掇野蔬兼示雅什用以詶謝', '魯望以躬掇野蔬兼示雅什用以詶謝', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["杖擿春煙暖向陽，煩君爲我致盈筐。","深挑乍見牛脣液，細掐徐聞鼠耳香。","紫甲採從泉脉畔，翠牙搜自石根傍。","彫胡飯熟𩝊餬軟，不是高人不合嘗。"]', '["杖擿春煙暖向陽，煩君爲我致盈筐。","深挑乍见牛脣液，細掐徐闻鼠耳香。","紫甲採從泉脉畔，翠牙搜自石根傍。","彫胡飯熟𩝊餬軟，不是高人不合嘗。"]', '诗', 'shi', '', NULL, '魯望以躬掇野蔬兼示雅什用以詶謝 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a80bee7-bfc1-4ad8-a5b2-4943f1ac7cb6', '臥病感春寄魯望', '臥病感春寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["烏皮几上困騰騰，玉柄清羸媿不能。","昨夜眠時稀似鶴，今朝餐數減於僧。","藥銷美祿應夭折，醫過芳辰定鬼憎。","任是雨多遊未得，也須收在探花朋。"]', '["烏皮几上困腾腾，玉柄清羸媿不能。","昨夜眠时稀似鹤，今朝餐數減於僧。","藥銷美祿應夭折，醫過芳辰定鬼憎。","任是雨多游未得，也須收在探花朋。"]', '诗', 'shi', '', NULL, '臥病感春寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16cd355-514e-478b-b3d9-bbf961258148', '奉和魯望徐方平後聞赦次韻', '奉和魯望徐方平後闻赦次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["金雞煙外上臨軒，紫誥新垂作解恩。","涿鹿未銷初敗血，新安頓雪已坑魂。","空林葉盡蝗來郡，腐骨花生戰後村。","未遣蒲車問幽隱，共君應老抱桐孫。"]', '["金雞煙外上臨軒，紫誥新垂作解恩。","涿鹿未銷初敗血，新安頓雪已坑魂。","空林葉尽蝗来郡，腐骨花生戰後村。","未遣蒲车问幽隐，共君應老抱桐孫。"]', '诗', 'shi', '', NULL, '奉和魯望徐方平後聞赦次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a538a5d1-5a54-4a7f-a864-ce219ace9c2b', '奉詶魯望見荅魚牋之什', '奉詶魯望见荅鱼牋之什', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["輕如隱起膩如飴，除却鮫工解製稀。","欲寫恐成河伯詔，試裁疑是水仙衣。","毫端白獺脂猶濕，指下冰蠶子欲飛。","若用莫將閑處去，好題春思贈江妃。"]', '["轻如隐起膩如飴，除却鮫工解製稀。","欲寫恐成河伯詔，試裁疑是水仙衣。","毫端白獺脂猶濕，指下冰蠶子欲飞。","若用莫將闲处去，好題春思贈江妃。"]', '诗', 'shi', '', NULL, '奉詶魯望見荅魚牋之什 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a587124-934a-42bd-b479-d76dfcf26ea6', '病後春思', '病後春思', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["連錢錦暗麝氛氳，荆思多才詠鄂君。","孔雀鈿寒窺沼見，石榴紅重墮堦聞。","牢愁有度應如月，春夢無心秖似雲。","應笑病來慙滿願，花牋好作斷腸文。"]', '["連錢錦暗麝氛氳，荆思多才詠鄂君。","孔雀鈿寒窺沼见，石榴紅重墮堦闻。","牢愁有度應如月，春梦無心秖似云。","應笑病来慙满願，花牋好作斷腸文。"]', '诗', 'shi', '', NULL, '病後春思 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3c5a68-56b1-4add-9329-bedb4bb72729', '偶成小酌招魯望不至以詩爲解因次韻詶之', '偶成小酌招魯望不至以诗爲解因次韻詶之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["醉侶相邀愛早陽，小筵催辦不勝忙。","衝深柳駐吳娃幰，倚短花排羯鼓牀。","金鳳欲爲鶯引去，鈿蟬疑被蝶勾將。","如何共是忘形者，不見漁陽摻一場。"]', '["醉侶相邀愛早陽，小筵催辦不勝忙。","衝深柳駐吳娃幰，倚短花排羯鼓牀。","金鳳欲爲鶯引去，鈿蟬疑被蝶勾將。","如何共是忘形者，不见漁陽摻一場。"]', '诗', 'shi', '', NULL, '偶成小酌招魯望不至以詩爲解因次韻詶之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e905c6c-4ac8-4038-88c1-2867c7cb51a1', '以紗巾寄魯望因而有作', '以紗巾寄魯望因而有作', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["周家新樣替三梁，裹髪偏宜白面郎。","掩歛乍疑裁黑霧，輕明渾似戴玄霜。","今朝定見看花昃，明日應聞漉酒香。","更有一般君未識，虎文巾在絳霄房。"]', '["周家新樣替三梁，裹髪偏宜白面郎。","掩歛乍疑裁黑霧，轻明渾似戴玄霜。","今朝定见看花昃，明日應闻漉酒香。","更有一般君未識，虎文巾在絳霄房。"]', '诗', 'shi', '', NULL, '以紗巾寄魯望因而有作 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f288f1-db66-4c94-bf69-234028176b28', '臨頓宅將有歸于之日魯望以詩見貺因抒懷詶之', '臨頓宅將有归于之日魯望以诗见貺因抒懷詶之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["共老林泉忍暫分，此生應不識迴文。","幾枚竹笥送德曜，一乘柴車迎少君。","舉案品多緣澗藥，承家事少爲谿雲。","居然自是幽人事，輒莫教他孫壽聞。"]', '["共老林泉忍暫分，此生應不識迴文。","幾枚竹笥送德曜，一乘柴车迎少君。","舉案品多緣澗藥，承家事少爲谿云。","居然自是幽人事，輒莫教他孫壽闻。"]', '诗', 'shi', '', NULL, '臨頓宅將有歸于之日魯望以詩見貺因抒懷詶之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f335ff18-a7b9-4a8a-8c4b-a44a31498abf', '奉和魯望謝惠巨魚之半', '奉和魯望謝惠巨鱼之半', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["釣公來信自松江，三尺春魚撥刺霜。","腹內舊鉤苔染澀，腮中新餌藻和香。","冷鱗中斷榆錢破，寒骨平分玉筯光。","何事貺君偏得所，秖緣同是越航郎。"]', '["釣公来信自松江，三尺春鱼撥刺霜。","腹內旧鉤苔染澀，腮中新餌藻和香。","冷鱗中斷榆錢破，寒骨平分玉筯光。","何事貺君偏得所，秖緣同是越航郎。"]', '诗', 'shi', '', NULL, '奉和魯望謝惠巨魚之半 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae5119c-4c57-454a-be5e-7ba0540dfa68', '館娃宮懷古', '館娃宮懷古', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["豔骨已成蘭麝土，宮牆依舊壓層崖。","弩臺雨壞逢金鏃，香徑泥銷露玉釵。","硯沼只留溪鳥浴，屧廊空信野花埋。","姑蘇麋鹿真閑事，須爲當時一愴懷。"]', '["豔骨已成蘭麝土，宮牆依旧壓層崖。","弩台雨壞逢金鏃，香徑泥銷露玉釵。","硯沼只留溪鸟浴，屧廊空信野花埋。","姑蘇麋鹿真闲事，須爲當时一愴懷。"]', '诗', 'shi', '', NULL, '館娃宮懷古 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf32246f-c16f-4924-ba35-f6ff4958588d', '以紫石硯寄魯望兼詶見贈', '以紫石硯寄魯望兼詶见贈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["樣如金蹙小能輕，微潤將融紫玉英。","石墨一研爲鳳尾，寒泉半勺是龍睛。","騷人白芷傷心暗，狎客紅筵奪眼明。","兩地有期皆好用，不須空把洗溪聲。"]', '["樣如金蹙小能轻，微潤將融紫玉英。","石墨一研爲鳳尾，寒泉半勺是龙睛。","騷人白芷傷心暗，狎客紅筵奪眼明。","兩地有期皆好用，不須空把洗溪声。"]', '诗', 'shi', '', NULL, '以紫石硯寄魯望兼詶見贈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('060e6b75-d9a1-4593-928e-20fe6c561996', '奉和魯望同遊北禪院', '奉和魯望同游北禪院', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["戚歷杉陰入草堂，老僧相見似相忘。","吟多幾轉蓮花漏，坐久重焚柏子香。","魚慣齋時分淨食，鴿能閑處傍禪牀。","雲林滿眼空羈滯，欲對彌天卻自傷。"]', '["戚歷杉陰入草堂，老僧相见似相忘。","吟多幾轉蓮花漏，坐久重焚柏子香。","鱼慣斋时分淨食，鴿能闲处傍禪牀。","云林满眼空羈滯，欲对彌天卻自傷。"]', '诗', 'shi', '', NULL, '奉和魯望同遊北禪院 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b0fac5-6aad-4cc6-843a-b3b7e11454cf', '孫發百篇將遊天台請詩贈行因以送之', '孫發百篇將游天台請诗贈行因以送之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["孫子荆家思有餘，元戎曾薦入公車。","百篇宮體喧金屋，一日官銜下玉除。","紫府近通齋後夢，赤城新有寄來書。","因逢二老如相問，正滯江南爲𩸃魚。"]', '["孫子荆家思有餘，元戎曾薦入公车。","百篇宮體喧金屋，一日官銜下玉除。","紫府近通斋後梦，赤城新有寄来书。","因逢二老如相问，正滯江南爲𩸃鱼。"]', '诗', 'shi', '', NULL, '孫發百篇將遊天台請詩贈行因以送之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62bf65f-58c3-429a-820b-f9d372902828', '奉和魯望薔薇次韻', '奉和魯望薔薇次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["誰繡連延滿戶陳，暫應遮得陸郎貧。","紅芳掩歛將迷蝶，翠蔓飄颻欲挂人。","低拂地時如墮馬，高臨牆處似窺鄰。","秖應是董雙成戲，剪得神霞寸寸新。"]', '["誰繡連延满戶陳，暫應遮得陸郎貧。","紅芳掩歛將迷蝶，翠蔓飄颻欲挂人。","低拂地时如墮马，高臨牆处似窺鄰。","秖應是董雙成戲，剪得神霞寸寸新。"]', '诗', 'shi', '', NULL, '奉和魯望薔薇次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c65d047-8a95-4441-b4dd-9a8138b9777e', '聞開元寺開笋園寄章上人', '闻开元寺开笋园寄章上人', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["園鏁開聲駭鹿羣，滿林鮮籜水犀文。","森森競泫林梢雨，𡾼𡾼爭穿石上雲。","並出亦如鵝管合，各生還似犬牙分。","折煙束露如相遺，何胤明朝不茹葷。"]', '["园鏁开声駭鹿羣，满林鲜籜水犀文。","森森競泫林梢雨，𡾼𡾼爭穿石上云。","並出亦如鵝管合，各生還似犬牙分。","折煙束露如相遺，何胤明朝不茹葷。"]', '诗', 'shi', '', NULL, '聞開元寺開笋園寄章上人 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d90c21f-4845-4f57-9ae8-7e245898bc21', '開元寺佛鉢詩', '开元寺佛鉢诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["帝青石作綠冰姿，曾得金人手自持。","拘律樹邊齋散後，提羅花下洗來時。","乳麋味斷中天覺，麥麨香消大劫知。","從此共君親頂戴，斜風應不等閑吹。"]', '["帝青石作綠冰姿，曾得金人手自持。","拘律樹邊斋散後，提羅花下洗来时。","乳麋味斷中天覺，麦麨香消大劫知。","從此共君親頂戴，斜风應不等闲吹。"]', '诗', 'shi', '', NULL, '開元寺佛鉢詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed0eb94-827a-481e-9d25-3a8c51e8f2ee', '夏首病愈因招魯望', '夏首病愈因招魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["曉入清和尚袷衣，夏陰初合掩雙扉。","一聲撥穀桑柘晚，數點舂鋤煙雨微。","貧養山禽能箇瘦，病關芳草就中肥。","明朝早起非無事，買得蓴絲待陸機。"]', '["晓入清和尚袷衣，夏陰初合掩雙扉。","一声撥穀桑柘晚，數点舂鋤煙雨微。","貧養山禽能箇瘦，病关芳草就中肥。","明朝早起非無事，買得蓴絲待陸機。"]', '诗', 'shi', '', NULL, '夏首病愈因招魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e23d29-65f1-4634-8738-5031ad614ceb', '奉和魯望新夏東郊閑泛', '奉和魯望新夏东郊闲泛', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["水物輕明淡似秋，多情才子倚蘭舟。","碧莎裳下攜詩草，黃{𥫗/罒/伐}樓中挂酒篘。","蓮葉蘸波初轉櫂，魚兒簇餌未諳鉤。","共君莫問當時事，一點沙禽勝五侯。"]', '["水物轻明淡似秋，多情才子倚蘭舟。","碧莎裳下携诗草，黄{𥫗/罒/伐}楼中挂酒篘。","蓮葉蘸波初轉櫂，鱼兒簇餌未諳鉤。","共君莫问當时事，一点沙禽勝五侯。"]', '诗', 'shi', '', NULL, '奉和魯望新夏東郊閑泛 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fdbb6f5-9ef6-4839-9b04-de45d87c7134', '奉和魯望四月十五日道室書事', '奉和魯望四月十五日道室书事', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["忘朝齋戒是尋常，靜啓金根第幾章。","竹葉飲爲甘露色，蓮花鮓作肉芝香。","松膏背日凝雲磴，丹粉經年染石牀。","剩欲與君終此志，頑仙唯恐鬢成霜。"]', '["忘朝斋戒是尋常，静啓金根第幾章。","竹葉饮爲甘露色，蓮花鮓作肉芝香。","松膏背日凝云磴，丹粉經年染石牀。","剩欲與君終此志，頑仙唯恐鬢成霜。"]', '诗', 'shi', '', NULL, '奉和魯望四月十五日道室書事 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e929b1f0-41ec-4ee2-ae04-02530bfb8cb2', '奉和魯望看壓新醅', '奉和魯望看壓新醅', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一簀松花細有聲，旋將渠椀撇寒清。","秦吳只恐篘來近，劉項真能釀得平。","酒德有神多客頌，醉鄉無貨沒人爭。","五湖煙水郎山月，合向樽前問底名。"]', '["一簀松花細有声，旋將渠椀撇寒清。","秦吳只恐篘来近，劉項真能釀得平。","酒德有神多客頌，醉乡無貨沒人爭。","五湖煙水郎山月，合向樽前问底名。"]', '诗', 'shi', '', NULL, '奉和魯望看壓新醅 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbebbf41-85d4-44a5-a7a3-91d27ca62cfe', '登初陽樓寄懷北平郎中', '登初陽楼寄懷北平郎中', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["危樓新製號初陽，白粉青葌射沼光。","避酒幾浮輕舴艋，下棊曾覺睡鴛鴦。","投鉤列坐圍華燭，格簺分朋占靚妝。","莫怪重登頻有恨，二年曾侍舊吳王。"]', '["危楼新製號初陽，白粉青葌射沼光。","避酒幾浮轻舴艋，下棊曾覺睡鴛鴦。","投鉤列坐圍华燭，格簺分朋占靚妝。","莫怪重登頻有恨，二年曾侍旧吳王。"]', '诗', 'shi', '', NULL, '登初陽樓寄懷北平郎中 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541ce5f8-6aea-4811-bf8b-07c925b40fe2', '夏初訪魯望偶題小齋', '夏初訪魯望偶題小斋', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["半里芳陰到陸家，藜牀相勸飯胡麻。","林間度宿拋棊局，壁上經旬挂釣車。","野客病時分竹米，鄰翁齋日乞藤花。","踟躕爲放閑人去，半[岸]紗帩待月華。"]', '["半里芳陰到陸家，藜牀相勸飯胡麻。","林间度宿拋棊局，壁上經旬挂釣车。","野客病时分竹米，鄰翁斋日乞藤花。","踟躕爲放闲人去，半[岸]紗帩待月华。"]', '诗', 'shi', '', NULL, '夏初訪魯望偶題小齋 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e700a962-d3d2-4d73-9733-c5901b271624', '所居首夏水木尤清適然有作', '所居首夏水木尤清適然有作', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["病來無事草堂空，晝水休聞十二筒。","桂靜似逢青眼客，松閑如見綠毛翁。","潮期暗動庭泉碧，梅信微侵地障紅。","盡日枕書慵起得，被君猶自笑從公。"]', '["病来無事草堂空，晝水休闻十二筒。","桂静似逢青眼客，松闲如见綠毛翁。","潮期暗动庭泉碧，梅信微侵地障紅。","尽日枕书慵起得，被君猶自笑從公。"]', '诗', 'shi', '', NULL, '所居首夏水木尤清適然有作 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4153730-8d0a-4e61-83e9-1bb91c0711b4', '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 一', '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雨滌煙鋤傴僂賷，紺牙紅甲兩三畦。","藥名却笑桐君少，年紀翻嫌竹祖低。","白石靜敲蒸朮火，清泉閑洗種花泥。","怪來昨日休持鉢，一尺彫胡似掌齊。"]', '["雨滌煙鋤傴僂賷，紺牙紅甲兩三畦。","藥名却笑桐君少，年紀翻嫌竹祖低。","白石静敲蒸朮火，清泉闲洗種花泥。","怪来昨日休持鉢，一尺彫胡似掌齊。"]', '诗', 'shi', '', NULL, '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30b88958-e8ee-4b87-b3b8-d308de1cedda', '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 二', '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["香蔓蒙蘢覆昔邪，桂煙杉露濕袈裟。","石盆換水撈松葉，竹徑穿牀避笋芽。","藜杖移時挑細藥，銅缾盡日灌幽花。","支公謾道憐神駿，不及今朝種一麻。"]', '["香蔓蒙蘢覆昔邪，桂煙杉露濕袈裟。","石盆換水撈松葉，竹徑穿牀避笋芽。","藜杖移时挑細藥，銅缾尽日灌幽花。","支公謾道怜神駿，不及今朝種一麻。"]', '诗', 'shi', '', NULL, '重玄寺元達年逾八十好種名藥凡所植者多至自天台四明包山句曲叢翠紛糅各可指名余奇而訪之因題二章 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b6abb50-dd39-4253-a32e-63b2f118feb7', '懷華陽潤卿博士三首 一', '懷华陽潤卿博士三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["先生一向事虛皇，天市壇西與世忘。","環堵養龜看氣訣，刀圭餌犬試仙方。","靜探石腦衣裾潤，閑鍊松脂院落香。","聞道徵賢須有詔，不知何日到良常。"]', '["先生一向事虛皇，天市壇西與世忘。","环堵養龟看氣訣，刀圭餌犬試仙方。","静探石腦衣裾潤，闲鍊松脂院落香。","闻道徵賢須有詔，不知何日到良常。"]', '诗', 'shi', '', NULL, '懷華陽潤卿博士三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d69f37-65d9-4949-a886-f1b012427546', '懷華陽潤卿博士三首 二', '懷华陽潤卿博士三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["冥心唯事白英君，不問人間爵與勳。","林下醉眠仙鹿見，洞中閑話隱芝聞。","石牀臥苦渾無蘚，藤篋開稀恐有雲。","料得虛皇新詔樣，青瓊板上綠爲文。"]', '["冥心唯事白英君，不问人间爵與勳。","林下醉眠仙鹿见，洞中闲話隐芝闻。","石牀臥苦渾無蘚，藤篋开稀恐有云。","料得虛皇新詔樣，青瓊板上綠爲文。"]', '诗', 'shi', '', NULL, '懷華陽潤卿博士三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434b3294-4622-4f03-8ee2-804dc86abf8a', '懷華陽潤卿博士三首 三', '懷华陽潤卿博士三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鳳骨輕來稱瘦容，華陽館主未成翁。","數行玉札存心久，一掬雲漿漱齒空。","白石煮多熏屋黑，丹砂埋久染泉紅。","他年欲事先生去，十賚須加陸逸沖。"]', '["鳳骨轻来稱瘦容，华陽館主未成翁。","數行玉札存心久，一掬云漿漱齒空。","白石煮多熏屋黑，丹砂埋久染泉紅。","他年欲事先生去，十賚須加陸逸沖。"]', '诗', 'shi', '', NULL, '懷華陽潤卿博士三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888711cd-1a3f-4784-8e50-3272c1973198', '魯望以竹夾膝見寄因次韻詶謝', '魯望以竹夾膝见寄因次韻詶謝', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["圓於玉柱滑於龍，來自衡陽彩翠中。","拂潤恐飛清夏雨，叩虛疑貯碧湘風。","大勝書客裁成柬，頗賽谿翁截[作]筒。","從此角巾因爾戴，俗人相訪若爲通。"]', '["圓於玉柱滑於龙，来自衡陽彩翠中。","拂潤恐飞清夏雨，叩虛疑貯碧湘风。","大勝书客裁成柬，頗賽谿翁截[作]筒。","從此角巾因爾戴，俗人相訪若爲通。"]', '诗', 'shi', '', NULL, '魯望以竹夾膝見寄因次韻詶謝 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3c74f1-48a8-4d26-951b-550706dfe880', '夏景無事因懷章來二上人二首 一', '夏景無事因懷章来二上人二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["澹景微陰正送梅，幽人逃暑癭柟杯。","水花移得和魚子，山蕨收時帶竹胎。","嘯館大都偏見月，醉鄉終竟不聞雷。","更無一事唯留客，卻被高僧怕不來。"]', '["澹景微陰正送梅，幽人逃暑癭柟杯。","水花移得和鱼子，山蕨收时带竹胎。","嘯館大都偏见月，醉乡終竟不闻雷。","更無一事唯留客，卻被高僧怕不来。"]', '诗', 'shi', '', NULL, '夏景無事因懷章來二上人二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb329d28-ef4e-42f4-9220-757149ab1b63', '夏景無事因懷章來二上人二首 二', '夏景無事因懷章来二上人二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["佳樹盤珊枕草堂，此中隨分亦閑忙。","平鋪風簟尋琴譜，靜掃煙窗著藥方。","幽鳥見貧留好語，白蓮知臥送清香。","從今有計消閑日，更爲支公置一牀。"]', '["佳樹盤珊枕草堂，此中隨分亦闲忙。","平鋪风簟尋琴譜，静掃煙窗著藥方。","幽鸟见貧留好語，白蓮知臥送清香。","從今有計消闲日，更爲支公置一牀。"]', '诗', 'shi', '', NULL, '夏景無事因懷章來二上人二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c98c5d-e26e-41a1-98b5-9629416c15cd', '寄瓊州楊舍人', '寄瓊州楊舍人', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["德星芒彩瘴天涯，酒樹堪消謫宦嗟。","行遇竹王因設奠，居逢木客又遷家。","清齋淨溲桄榔麪，遠信閑封豆蔻花。","清切會須歸有日，莫貪句漏足丹砂。"]', '["德星芒彩瘴天涯，酒樹堪消謫宦嗟。","行遇竹王因設奠，居逢木客又遷家。","清斋淨溲桄榔麪，远信闲封豆蔻花。","清切會須归有日，莫貪句漏足丹砂。"]', '诗', 'shi', '', NULL, '寄瓊州楊舍人 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c0ec42-8d30-4cdc-be65-fdd9e2bcee93', '魯望以輪鉤相示緬懷高致因作三篇 一', '魯望以輪鉤相示緬懷高致因作三篇 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["角柄孤輪細膩輕，翠篷十載伴君行。","撚時解轉蟾蜍魄，拋處能啼絡緯聲。","七里灘波喧一舍，五雲溪月靜三更。","牛衣鮒足和蓑睡，誰信人間有利名。"]', '["角柄孤輪細膩轻，翠篷十載伴君行。","撚时解轉蟾蜍魄，拋处能啼絡緯声。","七里灘波喧一舍，五云溪月静三更。","牛衣鮒足和蓑睡，誰信人间有利名。"]', '诗', 'shi', '', NULL, '魯望以輪鉤相示緬懷高致因作三篇 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffa9bd8a-04f7-41ba-8536-9567813589dd', '魯望以輪鉤相示緬懷高致因作三篇 二', '魯望以輪鉤相示緬懷高致因作三篇 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一線飄然下碧塘，溪翁無語遠相望。","蓑衣舊去煙披重，篛笠新來雨打香。","白鳥白蓮爲夢寐，清風清月是家鄉。","明朝有物充君信，㰂酒三缾寄夜航。"]', '["一線飄然下碧塘，溪翁無語远相望。","蓑衣旧去煙披重，篛笠新来雨打香。","白鸟白蓮爲梦寐，清风清月是家乡。","明朝有物充君信，㰂酒三缾寄夜航。"]', '诗', 'shi', '', NULL, '魯望以輪鉤相示緬懷高致因作三篇 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d325359-d4de-4b19-9007-d308694786b3', '魯望以輪鉤相示緬懷高致因作三篇 三', '魯望以輪鉤相示緬懷高致因作三篇 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["盡日悠然舴艋輕，小輪聲細雨溟溟。","三尋絲帶桐江爛，一寸鉤含笠澤腥。","用近詹何傳釣法，收和范蠡養魚經。","孤篷半夜無餘事，應被嚴灘聒酒醒。"]', '["尽日悠然舴艋轻，小輪声細雨溟溟。","三尋絲带桐江爛，一寸鉤含笠澤腥。","用近詹何傳釣法，收和范蠡養鱼經。","孤篷半夜無餘事，應被嚴灘聒酒醒。"]', '诗', 'shi', '', NULL, '魯望以輪鉤相示緬懷高致因作三篇 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2264271c-7b34-4739-8baa-ac1748a78a2e', '吳中書事寄漢南裴尚書', '吳中书事寄漢南裴尚书', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬家無事鏁蘭橈，鄉味腥多厭紫虈。","水似棊文交度郭，柳如行障儼遮橋。","青梅蔕重初迎雨，白鳥羣高欲避潮。","唯望舊知憐此意，得爲傖鬼也逍遙。"]', '["万家無事鏁蘭橈，乡味腥多厭紫虈。","水似棊文交度郭，柳如行障儼遮橋。","青梅蔕重初迎雨，白鸟羣高欲避潮。","唯望旧知怜此意，得爲傖鬼也逍遙。"]', '诗', 'shi', '', NULL, '吳中書事寄漢南裴尚書 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93777708-4d5b-44a3-98e8-8f82530d6506', '夏景沖澹偶然作二首 一', '夏景沖澹偶然作二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["秖隈蒲褥岸烏紗，味道澄懷景便斜。","紅印寄泉慙郡守，青筐與笋媿僧家。","茗爐盡日燒松子，書案經時剝瓦花。","園吏暫棲君莫笑，不妨猶更著南華。"]', '["秖隈蒲褥岸烏紗，味道澄懷景便斜。","紅印寄泉慙郡守，青筐與笋媿僧家。","茗爐尽日燒松子，书案經时剝瓦花。","园吏暫棲君莫笑，不妨猶更著南华。"]', '诗', 'shi', '', NULL, '夏景沖澹偶然作二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cedfb88-2fa9-4890-8250-193289eda8c4', '夏景沖澹偶然作二首 二', '夏景沖澹偶然作二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一室無喧事事幽，還如貞白在高樓。","天台畫得千迴看，湖目芳來百度遊。","無限世機吟處息，幾多身計釣前休。","他年謁帝言何事，請贈劉伶作醉侯。"]', '["一室無喧事事幽，還如貞白在高楼。","天台畫得千迴看，湖目芳来百度游。","無限世機吟处息，幾多身計釣前休。","他年謁帝言何事，請贈劉伶作醉侯。"]', '诗', 'shi', '', NULL, '夏景沖澹偶然作二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7fcc446-65c1-4784-aefe-543918779461', '送李明府之任海南', '送李明府之任海南', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["五羊城在蜃樓邊，墨綬垂腰正少年。","山靜不應聞屈鳥，草深從使翳貪泉。","蟹奴晴上臨潮檻，燕婢秋隨過海船。","一事與君消遠宦，乳蕉花發訟庭前。"]', '["五羊城在蜃楼邊，墨綬垂腰正少年。","山静不應闻屈鸟，草深從使翳貪泉。","蟹奴晴上臨潮檻，燕婢秋隨過海船。","一事與君消远宦，乳蕉花發訟庭前。"]', '诗', 'shi', '', NULL, '送李明府之任海南 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cdf775-079c-4c5f-aea0-e2fcae5324f5', '寄題羅浮軒轅先生所居', '寄題羅浮軒轅先生所居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["亂峰四百三十二，欲問徵君何處尋。","紅翠數聲瑤室響，真檀一炷石樓深。","山都遣負沽來酒，樵客容看化後金。","從此謁師知不遠，求官先有葛洪心。"]', '["亂峰四百三十二，欲问徵君何处尋。","紅翠數声瑤室响，真檀一炷石楼深。","山都遣負沽来酒，樵客容看化後金。","從此謁師知不远，求官先有葛洪心。"]', '诗', 'shi', '', NULL, '寄題羅浮軒轅先生所居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d34e2c-b432-4b00-ade3-2d8a3edcf27e', '宿報恩寺水閣', '宿報恩寺水閣', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寺鏁雙峰寂不開，幽人中夜獨裴回。","池文帶月鋪金簟，蓮朵含風動玉杯。","往往竹梢搖翡翠，時時杉子擲莓苔。","可憐此際誰曾見，唯有支公盡看來。"]', '["寺鏁雙峰寂不开，幽人中夜独裴回。","池文带月鋪金簟，蓮朵含风动玉杯。","往往竹梢搖翡翠，时时杉子擲莓苔。","可怜此際誰曾见，唯有支公尽看来。"]', '诗', 'shi', '', NULL, '宿報恩寺水閣 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e028684-1ffb-42c8-bd10-d22c2d48cf7a', '醉中偶作呈魯望', '醉中偶作呈魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["谿雲澗鳥本吾儕，剛爲浮名事事乖。","十里尋山爲思役，五更看月是情差。","分將吟詠華雙鬢，力以壺觴固百骸。","爭得草堂歸臥去，共君同作太常齋。"]', '["谿云澗鸟本吾儕，剛爲浮名事事乖。","十里尋山爲思役，五更看月是情差。","分將吟詠华雙鬢，力以壺觴固百骸。","爭得草堂归臥去，共君同作太常斋。"]', '诗', 'shi', '', NULL, '醉中偶作呈魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f1c818-e1d1-4ed5-8fee-42d0c1191b15', '寄滑州李副使員外', '寄滑州李副使員外', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["兵繞臨淮數十重，鐵衣才子正從公。","軍前草奏旄頭下，城上封書箭𦼮中。","圍合只應聞曉雁，血腥何處避春風。","故人勳重金章貴，猶在江湖積劒功。"]', '["兵繞臨淮數十重，鐵衣才子正從公。","軍前草奏旄头下，城上封书箭𦼮中。","圍合只應闻晓雁，血腥何处避春风。","故人勳重金章貴，猶在江湖積劒功。"]', '诗', 'shi', '', NULL, '寄滑州李副使員外 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d01090-d09a-4b87-b32a-ce15bbc66757', '傷史拱山人', '傷史拱山人', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一緘幽信自襄陽，上報先生去歲亡。","山客爲醫翻貰藥，野僧因弔卻焚香。","峰頭孤冢爲雲穴，松下靈筵是石牀。","宗炳死來君又去，終身不復到柴桑。"]', '["一緘幽信自襄陽，上報先生去歲亡。","山客爲醫翻貰藥，野僧因弔卻焚香。","峰头孤冢爲云穴，松下靈筵是石牀。","宗炳死来君又去，終身不复到柴桑。"]', '诗', 'shi', '', NULL, '傷史拱山人 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364d3de7-b26b-48d8-9704-ed012b0a0ee1', '吳中言懷寄南海二同年', '吳中言懷寄南海二同年', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["曲水分飛歲已賒，東南爲客各天涯。","退公秖傍蘇勞竹，移宴多隨末利花。","銅鼓夜敲溪上月，布帆晴照海邊霞。","三年謾被鱸魚累，不得橫經侍絳紗。"]', '["曲水分飞歲已賒，东南爲客各天涯。","退公秖傍蘇勞竹，移宴多隨末利花。","銅鼓夜敲溪上月，布帆晴照海邊霞。","三年謾被鱸鱼累，不得橫經侍絳紗。"]', '诗', 'shi', '', NULL, '吳中言懷寄南海二同年 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5ff784-9320-4827-8c2e-f7330a0b1279', '奉和魯望白鷗詩', '奉和魯望白鷗诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雪羽䙰褷半惹泥，海雲深處舊巢迷。","池無飛浪爭教舞，洲少輕沙若遣棲。","煙外失羣慙雁鶩，波中得志羨鳧鷖。","主人恩重真難遇，莫爲心孤憶舊溪。"]', '["雪羽䙰褷半惹泥，海云深处旧巢迷。","池無飞浪爭教舞，洲少轻沙若遣棲。","煙外失羣慙雁鶩，波中得志羨鳧鷖。","主人恩重真难遇，莫爲心孤憶旧溪。"]', '诗', 'shi', '', NULL, '奉和魯望白鷗詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db03524-2bb0-4ae6-9a31-d2c67df6939e', '奉和魯望懷楊台文楊鼎文二秀才', '奉和魯望懷楊台文楊鼎文二秀才', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["羊曇留我昔經春，各以篇章鬬五雲。","賓草每容閑處見，擊琴多任醉中聞。","釣前青翰交加倚，醉後紅魚取次分。","爲說風標曾入夢，上仙初著翠霞帬。"]', '["羊曇留我昔經春，各以篇章鬬五云。","賓草每容闲处见，擊琴多任醉中闻。","釣前青翰交加倚，醉後紅鱼取次分。","爲说风標曾入梦，上仙初著翠霞帬。"]', '诗', 'shi', '', NULL, '奉和魯望懷楊台文楊鼎文二秀才 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bdffcd3-de9c-4d5f-8d97-84af7e1283c8', '友人以人參見惠因以詩謝之', '友人以人參见惠因以诗謝之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["神草延年出道家，是誰披露記三椏。","開時的定涵雲液，斸後還應帶石花。","名士寄來消酒渴，野人煎處撇泉華。","從今湯劑如相續，不用金山焙上茶。"]', '["神草延年出道家，是誰披露記三椏。","开时的定涵云液，斸後還應带石花。","名士寄来消酒渴，野人煎处撇泉华。","從今湯劑如相續，不用金山焙上茶。"]', '诗', 'shi', '', NULL, '友人以人參見惠因以詩謝之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ffab9b-b374-46b4-805d-9dabf4d5e85c', '傷進士嚴子重詩', '傷進士嚴子重诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十哭都門牓上塵，蓋棺終是五湖人。","生前有敵唯丹桂，沒後無家秖白蘋。","箬下斬新醒處月，江南依舊詠來春。","知君精爽應無盡，必在酆都頌帝晨。"]', '["十哭都门牓上塵，蓋棺終是五湖人。","生前有敵唯丹桂，沒後無家秖白蘋。","箬下斬新醒处月，江南依旧詠来春。","知君精爽應無尽，必在酆都頌帝晨。"]', '诗', 'shi', '', NULL, '傷進士嚴子重詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f471a654-f0a9-4964-aa18-5bc86012695f', '奉和魯望早秋吳體次韻', '奉和魯望早秋吳體次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["書淫傳癖窮欲死，譊譊何必頻相仍。","日乾陰蘚厚堪剝，藤把欹松牢似繩。","搗藥香侵白袷袖，穿雲潤破烏紗稜。","安得瑤池飲殘酒，半醉騎下垂天鵬。"]', '["书淫傳癖窮欲死，譊譊何必頻相仍。","日乾陰蘚厚堪剝，藤把欹松牢似繩。","捣藥香侵白袷袖，穿云潤破烏紗稜。","安得瑤池饮殘酒，半醉騎下垂天鵬。"]', '诗', 'shi', '', NULL, '奉和魯望早秋吳體次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cc2913-da24-40f7-8e98-be927cb1fb74', '奉和魯望秋賦有期次韻', '奉和魯望秋賦有期次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十載江湖盡是閑，客兒詩句滿人間。","郡侯聞譽親邀得，鄉老知名不放還。","應帶瓦花經汴水，更攜雲實出包山。","太微宮裏環岡樹，無限瑤枝待爾攀。"]', '["十載江湖尽是闲，客兒诗句满人间。","郡侯闻譽親邀得，乡老知名不放還。","應带瓦花經汴水，更携云實出包山。","太微宮裏环岡樹，無限瑤枝待爾攀。"]', '诗', 'shi', '', NULL, '奉和魯望秋賦有期次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac19ce2e-2609-44c9-a262-469bbe37c3e1', '奉和魯望病中秋懷次韻', '奉和魯望病中秋懷次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["貧病於君亦太兼，才高應亦被天嫌。","因分鶴料家資減，爲置僧餐口數添。","靜裏改詩空凭几，寒中注易不開簾。","清詞一一侵真宰，甘取窮愁不用占。"]', '["貧病於君亦太兼，才高應亦被天嫌。","因分鹤料家資減，爲置僧餐口數添。","静裏改诗空凭几，寒中注易不开簾。","清词一一侵真宰，甘取窮愁不用占。"]', '诗', 'shi', '', NULL, '奉和魯望病中秋懷次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be74746-3bb7-4950-aff3-2e7e22cd3c02', '新秋即事三首 一', '新秋即事三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["癡號多於顧愷之，更無餘事可從知。","酒坊吏到常先見，鶴料符來每探支。","涼後每謀清月社，晚來專赴白蓮期。","共君無事堪相賀，又到金虀玉鱠時。"]', '["癡號多於顧愷之，更無餘事可從知。","酒坊吏到常先见，鹤料符来每探支。","涼後每謀清月社，晚来專赴白蓮期。","共君無事堪相賀，又到金虀玉鱠时。"]', '诗', 'shi', '', NULL, '新秋即事三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c68cd992-02a6-40f9-afd3-8ca6e1237a77', '新秋即事三首 二', '新秋即事三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["堪笑高陽病酒徒，幅巾瀟灑在東吳。","秋期淨掃雲根瘦，山信迴緘乳管粗。","白月半窗抄朮序，清泉一器授芝圖。","乞求待得西風起，盡挽煙帆入太湖。"]', '["堪笑高陽病酒徒，幅巾瀟灑在东吳。","秋期淨掃云根瘦，山信迴緘乳管粗。","白月半窗抄朮序，清泉一器授芝圖。","乞求待得西风起，尽挽煙帆入太湖。"]', '诗', 'shi', '', NULL, '新秋即事三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d168d5c5-6b8c-4788-9869-cad38c4a5486', '新秋即事三首 三', '新秋即事三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["露槿風杉滿曲除，高秋無事似雲廬。","醉多已任家人厭，病久還甘吏道疎。","青桂巾箱時寄藥，白綸臥具半拋書。","君卿脣舌非吾事，且向江南問鰒魚。"]', '["露槿风杉满曲除，高秋無事似云廬。","醉多已任家人厭，病久還甘吏道疎。","青桂巾箱时寄藥，白綸臥具半拋书。","君卿脣舌非吾事，且向江南问鰒鱼。"]', '诗', 'shi', '', NULL, '新秋即事三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5854d12-3ec9-40fb-9b09-15e1386bb7e5', '南陽潤卿將歸雷平因而有贈', '南陽潤卿將归雷平因而有贈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["借問山中許道士，此迴歸去復何如。","竹屏風扇抄遺事，柘步輿竿繫隱書。","絳樹實多分紫鹿，丹沙泉淺種紅魚。","東卿旄節看看至，靜啓茅齋慎掃除。"]', '["借问山中許道士，此迴归去复何如。","竹屏风扇抄遺事，柘步輿竿繫隐书。","絳樹實多分紫鹿，丹沙泉淺種紅鱼。","东卿旄節看看至，静啓茅斋慎掃除。"]', '诗', 'shi', '', NULL, '南陽潤卿將歸雷平因而有贈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f9003a-86d9-49cf-9eb4-174f33d1c5e1', '訪寂上人不遇', '訪寂上人不遇', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["何處尋雲暫廢禪，客來還寄草堂眠。","桂寒自落翻經案，石冷空消洗鉢泉。","爐裏尚飄殘玉篆，龕中仍鏁小金仙。","須將二百籤迴去，得得支公恐隔年。"]', '["何处尋云暫廢禪，客来還寄草堂眠。","桂寒自落翻經案，石冷空消洗鉢泉。","爐裏尚飄殘玉篆，龕中仍鏁小金仙。","須將二百籤迴去，得得支公恐隔年。"]', '诗', 'shi', '', NULL, '訪寂上人不遇 皮日休 shi');
